-- Generated by QuestData/Tools/import_multilanguage_quests.py.
-- Known IDs only; Classic-source passages are compatibility fallbacks on Forever.
local source = "MultiLanguage Classic c51dc2e5141f070f5b92de190521d79e8dccaeab"
local data = WordHunterWoW_QuestDataByFlavor
local function apply(id, targets, passages)
    for _, flavor in ipairs(targets) do
        local languages = data and data[flavor]
        for locale, fields in pairs(passages) do
            local record = languages and languages[locale] and languages[locale][id]
            if record then
                for field, text in pairs(fields) do
                    if not record[field] or record[field] == "" then
                        record[field] = text
                        record[field .. "Source"] = source
                        record[field .. "SourceFlavor"] = "classic"
                    end
                end
            end
        end
    end
end

apply(2853, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {race}... Eurem Aussehen nach seid Ihr ein Lederer wie ich. Seid Ihr hier, um etwas von meinem Geschick zu erlangen, oder habt Ihr vielleicht andere Geschäfte mit mir zu besprechen?", completion = "Ah ja, Pratt hat Euch geschickt. Auch wenn er ein Mensch ist, erinnert er mich doch gelegentlich an uns Nachtelfen. Seine Hingabe und seine Talente im Umgang mit Leder sind beeindruckend. Euch so in diesem Brief zu loben, ist ein Zeichen des Respekts, welches ich anerkenne.\n\nMir ist bewusst, dass er Euch die Kunst des Wildleders beigebracht hat. Erlaubt mir, Eure Ausbildung mit diesem Muster abzuschließen. Macht guten Gebrauch davon. Nur wenige auf der Welt kennen die Geheimnisse der Wildlederumhänge." }, enUS = { progress = "Greetings, {race}... from your countenance I can tell you are a leatherworker as am I.  Have you come to draw from my skills, or perhaps you have other business with me?", completion = "Ah yes, Pratt sent you.  Though he is a human, he reminds me of us night elves sometimes.  His dedication and his talents with leather are impressive.  For him to compliment you so in this letter, it is a sign of respect I acknowledge.\n\nI am aware that he has taught you the art of Wild Leather.  Allow me to finish your training with this pattern.  Make good use of it; few in the world know the secrets of Wild Leather cloaks." } })
apply(2854, { "classic", "forever" }, { deDE = { progress = "Nur um es klarzustellen: Ihr werdet bei mir in die Lehre gehen, während Ihr die Kunst der Herstellung von Wildlederrüstungen erlernt. Da Wildranken sowohl mächtig als auch chaotisch sind, verbessert sich die Rüstung, die Ihr herstellen werdet, auf zufällige, aber mächtige Art und Weise. Dieses Wissen war jedoch nicht einfach zu erwerben.\n\nDas Lehrgeld für diesen Prozess beträgt 10 Stücke dickes Leder.\n\nSobald das erledigt ist, kommen wir zu der Arbeit, die Ihr erledigen müsst, um die Muster zu erhalten.", completion = "Nun, {name}, ich bin froh, Euch als meinen Lehrling dabeizuhaben. Ihr habt als Lederer eine schlaue Entscheidung getroffen; diejenigen, die Lederrüstungen verwenden, werden Euch die Bude einrennen, sobald Ihr gelernt habt, wie man die Kunst des Wildleders meistert.\n\nLasst uns an die Arbeit gehen - womit wollt Ihr anfangen?" }, enUS = { progress = "We must be clear; you shall be apprenticed to me while you learn the art of Wild Leather armor.  Because wildvines are both potent and chaotic, it yields a random but strong benefit to the already strong armor you will be making.  This knowledge, however, was not easy for me to acquire.\n\nThe initial cost to begin this process is ten pieces of thick leather.\n\nOnce that is done, we'll get to the work you need to do in order to obtain the patterns.", completion = "Well {name}, I'm glad to have you on board as my apprentice.  You've made a wise decision as a leatherworker; those who make use of leather armor will be clamoring to you once you learn how to master the art of Wild Leather.\n\nLet's get to work - where do you want to start?" } })
apply(2855, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die 6 dicken Rüstungssets und die Wildranke, die ich benötige?\n\nSeht die Anfertigung von Rüstungssets als Übung in gleichmäßiger und verlässlicher Herstellung an. Der einheitliche Stil, den Ihr bei der Ausübung Eures Handwerks entwickelt, hilft Euch dabei, Eure Fertigkeiten so weit zu entwickeln, dass Ihr die aufwändige Arbeit erledigen könnt, die man für die Herstellung von Wildlederrüstungen braucht.\n\nJede Lektion hat ihren Sinn, {name}. Es ist daher wichtig, jede davon bereitwillig anzunehmen.", completion = "Diese Rüstungssets sind von robuster Qualität, {name}. Wenn es etwas gibt, was ich nicht nur von meiner Arbeit, sondern auch von der Arbeit derer erwarte, die ich unterweise, dann ist das Qualität.\n\nIhr habt Euch dieses Muster wohlverdient; ich hoffe, es bringt Euch dieselbe Anerkennung, die es mir gebracht hat." }, enUS = { progress = "Do you have the six thick armor kits and the wildvine I require?\n\nThink of making armor kits as a lesson in steady and reliable crafting; the consistent fashioning method you develop as you ply your trade on these kits helps develop your skills for the intricate work needed to make Wild Leather armors.\n\nEvery lesson has a purpose, {name}.  It is important to embrace each one accordingly.", completion = "These armor kits are of solid quality, {name}.  If there is one thing I demand in not only my work, but in the work of those I give tutelage to, it is quality.\n\nYou've done well to earn this pattern; I hope it brings you the rewards it has brought me." } })
apply(2856, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die beiden Schildkrötenschuppenbrustplatten und -handschuhe? Und vergesst bitte die Wildranke nicht!\n\nSelbst mit den einfachsten Mustern können wir lernen, dass sich die Grundsätze der Formen leicht auf komplexere Gewänder übertragen lassen. Auf verschiedene Weise bereitet Euch die Form der Schildkrötenschuppenbrustplatten auf den Detailreichtum vor, der für die Herstellung von Wildlederwesten benötigt wird.\n\nWährend Ihr in den Lektionen voranschreitet, werden die Fertigkeiten, die ich Euch beibringe, zu einer wahren Kunst werden.", completion = "Das hier sind ein paar sehr schöne Stücke, {name}. Die Handwerkskunst und Sorgfalt, die in die Herstellung dieser Dinge geflossen sind, zeigen, dass Ihr beschlossen habt, Euch völlig diesen Aufgaben zu widmen.\n\nIhr habt meine Forderungen erfüllt und daher erhaltet Ihr Eure Belohnung. Das Wissen um die Herstellung von Wildlederwesten ist jetzt Euer." }, enUS = { progress = "Do you have the two Turtle Scale breastplates and gloves?  Also, don't forget the wildvine!\n\nEven with the earliest patterns, we learn that the fundamentals of shape translate well into more difficult garments.  Though different items, the shape of the Turtle Scale breastplates prepares you for the detailing needed to make a Wild Leather vest.\n\nAs you progress through your lessons, the skills I teach will become as art.", completion = "These are some very nice pieces here, {name}.  The craftsmanship and care put in to making these show you have chosen to dedicate yourself fully to these tasks.\n\nYou've met my requests, and with that comes your reward.  The knowledge of making Wild Leather vests is now yours!" } })
apply(2857, { "classic", "forever" }, { deDE = { progress = "Ich muss erst diese Tuniken und Stirnbänder gefertigt sehen und benötige außerdem das Stück Wildranke, bevor ich das Wissen von den Wildlederhelmen mit Euch teilen kann.\n\nKopfbedeckungen sind unter Abenteurern sehr begehrt, sei es ein entwaffnend einfaches Stirnband oder ein Vollhelm. Die Grundlagen zur Herstellung wertvoller Kopfbedeckungen bleiben dieselben, welcher Gestalt auch immer letztendlich die Ausrüstung ist.", completion = "Diese Ausrüstung des Nachtschleichers, die Ihr geliefert habt, entspricht genau den Anforderungen, die ich an Euch gestellt habe, {name}. Ich erwarte nicht weniger von einem Lederer Eures Kalibers.\n\nIhr habt Euch die Ehre erworben, Wildlederhelme herzustellen. Ich gebe Euch dieses Muster gern und hoffe, dass Ihr davon entsprechend profitieren werdet." }, enUS = { progress = "I need those tunics and headbands made, and I also need that piece of wildvine before I will share with you the knowledge of Wild Leather helmets.\n\nHead gear is highly coveted amongst adventurers, whether it be a disarmingly simple headband or a full-covering helmet.  The fundamentals of creating valued head gear remain constant, no matter what the cosmetic appearance of the gear is.", completion = "This Nightscape equipment you have supplied perfectly meets the requirements I have given to you, {name}.  I expect no less from a leatherworker of your caliber.\n\nYou have earned the honor of crafting Wild Leather helmets.  I give this pattern to you freely, and hope you will profit from it accordingly." } })
apply(2858, { "classic", "forever" }, { deDE = { progress = "Ihr müsst mir erst die Hosen, Stiefel und Wildranken liefern, bevor Ihr das Muster erlernt, {name}. Habt Ihr getan, worum ich Euch gebeten habe?\n\nSchon mit den ersten Stiefeln, die man anzufertigen lernt, beginnt man zu verstehen, dass ein Qualitätsstiefel eine Gratwanderung zwischen Komfort und Funktion darstellt. Dank beider Dinge ist man in der Lage, Gegenstände herzustellen, die es dem Träger erlauben, Erschöpfungszustände zu ignorieren, die diejenigen, die Ware minderer Qualität tragen, lähmen würden.", completion = "Wieder einmal habt Ihr Gegenstände mit dem Geschick einer erfahrenen Fachkraft hergestellt. Ihr habt Euch dieses Muster genauso verdient wie meinen Dank." }, enUS = { progress = "The pants, boots, and wildvines need to be delivered to me before you learn the pattern, {name}.  Have you done as I asked?\n\nFrom the earliest pair of boots we learn how to make, we start to understand that a quality boot needs to ride a razor's edge between comfort and function.  With both, we are able to create items that allow the wearer to ignore fatigue that would cripple those wearing lower quality goods.", completion = "Once again, you have produced items with the skill of a seasoned professional.  You have earned this pattern, as well as my congratulations." } })
apply(2859, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schildkrötenschuppenarmschienen und -helme fertig? Und vergesst nicht die beiden Wildranken, die ich brauche!\n\nInzwischen dürftet Ihr das Potenzial der Macht zu verstehen beginnen, das in Wildlederrüstungen steckt. Eine Rüstung, deren Anwendung keine Grenzen gesetzt sind, ist unschätzbar für einen Lederer. Einschränkungen bestehen lediglich in der Rohstoffmenge, aus der man die Gegenstände herstellen kann, nicht jedoch in der Qualität der Endprodukte!", completion = "Wieder einmal habt Ihr meine Aufgabe fehlerlos bewältigt. Vielleicht komme ich eines Tages ja noch auf der Suche nach Wissen zu EUCH, hm, {name}?\n\nHier habt Ihr das Muster für die Gamaschen sowie meinen Dank. Nehmt diese Lehre in Euch auf und lasst Eure Endprodukte von Euren beeindruckenden Fähigkeiten profitieren!" }, enUS = { progress = "Do you have the Turtle Scale bracers and helms ready?  Don't forget the two wildvines I require.\n\nBy now, you're starting to realize the potential power that lies in Wild Leather armor.  An armor that has no boundaries in application is nearly invaluable to a leatherworker.  The limits are only in the quantities of resources to make the items - not the quality of the finished products!", completion = "Again, you've completed my task without flaw.  Perhaps some day I will come to YOU seeking knowledge, eh {name}?\n\nHere is the pattern for the leggings, along with my thanks.  Commit this lore to your knowledge, and let your finished products tap into your impressive skills!" } })
apply(2860, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {race}... Eurem Aussehen nach seid Ihr ein Lederer wie ich. Seid Ihr hier, um etwas von meinem Geschick zu erlangen, oder habt Ihr vielleicht andere Geschäfte mit mir zu besprechen?", completion = "Ah, ja, Jangdor hat Euch geschickt. Es freut mich zu sehen, dass einer meiner besten Schüler nun selbst einen Schüler hat.\n\nSeine Hingabe und seine Talente im Umgang mit Leder sind beeindruckend. Euch so in diesem Brief zu loben, ist ein Zeichen des Respekts, das ich anerkenne.\n\nMir ist bewusst, dass er Euch die Kunst der Wildlederbearbeitung gelehrt hat. Erlaubt mir, Eure Ausbildung mit diesem Muster abzuschließen. Macht guten Gebrauch davon. Nur wenige auf der Welt kennen die Geheimnisse der Wildlederumhänge." }, enUS = { progress = "Greetings, {race}... from your countenance I can tell you are a leatherworker as am I.  Have you come to draw from my skills, or perhaps you have other business with me?", completion = "Ah yes, Jangdor sent you.  I am pleased to see that one of my finest students now has a student of his own.\n\nHis dedication and his talents with leather are impressive.  For him to compliment you so in this letter, it is a sign of respect I acknowledge.\n\nI am aware that he has taught you the art of Wild Leather.  Allow me to finish your training with this pattern.  Make good use of it; few in the world know the secrets of Wild Leather cloaks." } })
apply(2861, { "classic", "forever" }, { deDE = { completion = "Das ist wahr. Ich habe mit einem Troll ein Hühnchen zu rupfen. Ein großes Hühnchen. Ein wirklich großes!\n\nWollt Ihr mir helfen?" }, enUS = { completion = "That's right.  I do have a bone to pick with a troll.  A few bones.  All her bones!\n\nWant to help me?" } })
apply(2862, { "classic", "forever" }, { deDE = { progress = "Wir schlagen sie zurück und trotzdem greifen sie weiter an! Irgendjemand oder irgendetwas muss sie zur Raserei treiben... Oh, Ihr seid wieder da, was, {name}? Habt Ihr die Mähnen, die ich benötige, um das Kopfgeld auszahlen zu können?", completion = "Dies zeugt von einem guten Anfang, {name}. Euer Geschick als Soldat verdient Lob.\n\nIhr seid nicht der Einzige, dem ich diesen Auftrag gab. Viele haben bereits vor Euch gegen sie gekämpft und in der Vergangenheit haben unsere Bemühungen sie in Schach gehalten. In letzter Zeit haben jedoch ihre Versuche, nordwärts in unser Einflussgebiet einzudringen, dramatisch zugenommen. Ihre Angriffe sind außerdem wilder geworden ... fast als wären sie verzweifelt.\n\nIch habe allerdings einen Plan, {name}, der die Sache mit ihnen ein für alle Mal erledigen sollte ..." }, enUS = { progress = "We drive them back, and yet they still attack!  Someone or something must be driving them into a frenzy... oh, you have returned, eh {name}?  Do you have the manes I require for the bounty to be met?", completion = "This is proof of a good start, {name}.  Your skills as a soldier are to be commended.\n\nYou are not the only one I ask that task of.  Many before you have fought them, and in times past our efforts have kept them at bay.  Recently though, their attempts to push northward into our area of influence have increased dramatically.  Their attacks have also become more savage... almost as if they were desperate.\n\nI have a plan though, {name}, that might settle things once and for all against them..." } })
apply(2863, { "classic", "forever" }, { deDE = { completion = "Ihr habt getan, was ich wollte, und dafür beglückwünsche ich Euch. Nehmt diese kleine Belohnung als Entschädigung für Eure Mühen, {name}.\n\nNachdem ihre Zahl verringert und ihre Anführer erschlagen sind, werden die Gnolle es sich zweimal überlegen, bevor sie unser Lager angreifen. Das löst das derzeitige Problem allerdings nicht...\n\nEs muss einen Grund geben, warum die Gnolle in eine solche Raserei verfallen sind. Bevor sie eine Chance haben, sich erneut zu sammeln, will ich herausfinden, was die Ursache dafür ist." }, enUS = { completion = "You've done as I have asked, and for that I salute you.  Take this small reward as compensation for your efforts, {name}.\n\nWith their numbers thinned and their leaders slain, the gnolls will think twice about storming the camp.  This doesn't conclude the issue at hand, however...\n\nThere must be some reason why the gnolls have been whipped into such a frenzied state.  Before they have a chance to regroup though, I want to find out what is causing it." } })
apply(2864, { "classic", "forever" }, { deDE = { completion = "Hallo!\n\nOh, Ihr habt mit meinem Vetter Krazek gesprochen? Wie geht es ihm? Ich hoffe, Booty Bay bekommt ihm gut...\n\nSkarabäuspanzerschalen, sagt Ihr? Nun... lasst mich Euch eine Geschichte erzählen..." }, enUS = { completion = "Hello!\n\nOh, you spoke to my cousin Krazek?  How is he?  I hope Booty Bay is treating him well...\n\nScarab shells, you say?  Well... let me tell you a story..." } })
apply(2866, { "classic", "forever" }, { deDE = { completion = "Eine Untersuchung des Pavillons zeigt einige interessante und ungewöhnliche Dinge im Vergleich zu den umstehenden Ruinen auf.\n\nErstens ist der Pavillon eindeutig ein wesentlich jüngeres Bauwerk als die anderen Ruinen. Zweitens sind eine Reihe von Glyphen in seine Seiten eingraviert. Das Muster der Glyphen wiederholt sich, aber sein Ursprung oder seine Bedeutung sind ansonsten unklar. Drittens fühlt sich der Stein, aus dem der Pavillon besteht, warm an.\n\nDas zusammen zählt eindeutig als \"auffällig\" für die Durchsuchung der Ruinen." }, enUS = { completion = "Examining the gazebo reveals some interesting and unusual things in contrast to the surrounding ruins.\n\nFirst, the gazebo is clearly a more recent construction than the other objects in the ruins.  Second, the gazebo has a small series of glyphs engraved into the sides of it; the glyphs repeat in their pattern, but it otherwise is unknown in origin and meaning.  Third, the stone of the gazebo itself is warm to the touch.\n\nThis certainly quantifies as \"standing out\" in the search of the ruins!" } })
apply(2867, { "classic", "forever" }, { deDE = { completion = "Willkommen, {name}. Euer Bericht über diesen Pavillon ist höchst... Besorgnis erregend. Selbst wenn die Naga dort keinen Angriff geplant hatten, ist ihre fortwährende Gegenwart doch schlecht für unseren Vormarsch nach Feralas. Wie auch immer, hier ist die Entschädigung für Eure Nachforschungen.\n\nEs sieht so aus, als könnte die Festung Feathermoon dringend zusätzliche Hilfe bezüglich der Hasskammnaga gebrauchen. Ich würde Euch diesen Auftrag gern anbieten, wenn Ihr Interesse daran habt. Es gibt viel zu tun." }, enUS = { completion = "Welcome back, {name}.  Your report on this gazebo is most... disturbing.  It would seem that even if the naga there were not planning on an attack, their continued presence bodes ill for our push into Feralas.  At any rate, here is compensation for your investigation.\n\nIt would seem that Feathermoon Stronghold is in dire need of additional assistance concerning the Hatecrest naga.  I'd like to offer you the task, if you are so inclined.  There is much to do." } })
apply(2869, { "classic", "forever" }, { deDE = { progress = "{name}, falls Ihr hier seid, um Euch der Aufgabe zu vergewissern, die ich Euch gab, dann ist es gut. Es sind 10 Schuppen der Hasskämme, die ich haben möchte. Falls Ihr jedoch zum Schwatzen hier seid: Ich stehe nicht zur Verfügung für Gehaltlosigkeiten.\n\nWisset dies: Wir Nachtelfen sind keine Kriegstreiber. Unser Volk verschreibt sich dem Erhalt von Frieden und Harmonie. Das heißt aber nicht, dass wir nicht aktiv unsere eigenen Interessen schützen. Das ist meine Pflicht General Feathermoon und der Festung gegenüber!", completion = "Ja, doch, diese Schuppen sind mehr als zufrieden stellend. Tatsächlich denke ich, dass ich sie zu Pratt hinunterschicken werde, damit er einen Blick darauf wirft. Vielleicht kann er etwas Nützliches daraus herstellen.\n\nWas Euch betrifft, ich habe eine weitere Mission, auf die ich Euch schicken möchte. Doch zuerst habt Ihr hier einmal Eure Belohnung für die Schuppen. Dass Ihr weiterhin im Dienste des Generals und der Festung Feathermoon steht, ist ein Segen angesichts so großer Not." }, enUS = { progress = "{name}, if you're here to verify the task given to you, then excellent - it is ten Hatecrest scales I seek.  If you are here for chit-chat, then I am currently unavailable for such trivialities.\n\nKnow this - we night elves are not warmongers.  Our race is dedicated to the preservation of peace and harmony.  This does not mean, however, that we will not proactively protect our own interests.  This is my duty to General Feathermoon, and to the stronghold.", completion = "Yes, yes, these scales are more than satisfactory.  Actually, I think I will send these down to Pratt for him to take a look at.  Maybe he can craft something useful out of them.\n\nAs for you, I have another mission I want to send you on.  But first, here is your bounty for the scales.  Your continued service to the General and Feathermoon Stronghold at large is a blessing in the face of adversity." } })
apply(2870, { "classic", "forever" }, { deDE = { progress = "Lord Shalzaru zu verlieren, das würde ihre Pläne sicherlich für Wochen, wenn nicht gar Monate zurückwerfen. Außerdem ist das Relikt, das er gefunden hat, von großem Interesse für uns.\n\nHabt Ihr die Mission ausgeführt, die ich Euch gab, {name}?", completion = "Gut gespielt, {name}! Lord Shalzarus Untergang wird die Naga für eine ganze Weile, wenn nicht sogar für immer in Verwirrung stürzen. Die Bedrohung, die sie darstellen, ist nun besser unter unserer Kontrolle als je zuvor und wir haben Euch dafür zu danken.\n\nHier habt Ihr weiteres Kopfgeld aus der Schatzkammer der Festung - Ihr habt Euch jedes Kupferstück davon verdient. Ihr und die Eurigen seid jederzeit in der Festung Feathermoon willkommen, mein Freund.\n\nBevor Ihr abreist, hätte ich da noch eine Kleinigkeit, {name}... wenn Ihr vielleicht..." }, enUS = { progress = "Bringing down Lord Shalzaru would certainly set their plans back weeks, if not months.  On top of that, the relic he uncovered is of definite interest to us.\n\nHave you performed the mission given to you, {name}?", completion = "Well played, {name}! Lord Shalzaru's demise will throw the naga into disarray for some time, if not permanently.  The threat they pose is now under more of our control than it has ever been, and we have you to thank for it.\n\nHere is more bounty money from the stronghold treasury - you've earned every copper.  You and yours are welcome in Feathermoon Stronghold anytime, my friend.\n\nOne more thing before you depart, {name}... if you could..." } })
apply(2871, { "classic", "forever" }, { deDE = { progress = "Ja, kann ich Euch helfen?\n\nMoment, Ihr seid doch der {class}, der General Feathermoon und Latro mit der Bedrohung durch die Naga geholfen hat, nicht? Ich bin Vestia, Latros - ähm, natürlich Latronicus’ Frau. Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nDoch entschuldigt, Ihr seid sicher geschäftlich hier. Habt Ihr etwas für mich - von ihm vielleicht?", completion = "Interessant... das ist aus den Ruinen von Solarsal, sagt Ihr? Tja, Latro hat Recht, das muss ich mir ansehen. Auf den ersten Blick sieht es nicht so aus, als stamme es aus den Ruinen. Andererseits ist es auch keine Nagamachart... nicht etwas so Fremdartiges wie dies.\n\nEs wird eine Weile dauern, diesen Gegenstand zu erforschen. Wenn meine Nachforschungen abgeschlossen sind, werde ich vielleicht von Euren Talenten Gebrauch machen, solltet Ihr Euch in der Nähe befinden.\n\nHier, nehmt einen der überzähligen Gegenstände, die wir hier haben; ich hoffe, Ihr werdet ihn nutzen können!" }, enUS = { progress = "Yes, may I assist you?\n\nHold on, you're the {class} that has been helping General Feathermoon and Latro out with the naga threat, yes?  I'm Vestia, Latro's - erm, rather, Latronicus' wife.  It is a pleasure to meet you!\n\nI'm sorry, you're here on business, of course.  Do you have something for me - from him, perchance?", completion = "Interesting... this came from the Ruins of Solarsal, you say?  Well, Latro's right that I need to look at this.  At first glance, it seems non-indigenous to the ruins.  Then again, this isn't of naga design... not something as alien as this.\n\nIt is going to take some time to research this item.  Once my research on it is done, maybe I will make use of your talents, should you be around.\n\nHere, take one of these extra items we have; I hope you'll find some use for it!" } })
apply(2872, { "classic", "forever" }, { deDE = { completion = "Ach, Ihr habt also mit MacKinley gesprochen, ja?\n\nEs ist nicht so, wie er denkt! Ich habe keine Angst, ihm etwas Steamwheedle-Bilge-Rum zu geben...\n\nIch habe nur keinen Rum, den ich ihm geben könnte!" }, enUS = { completion = "Ah, so you've been speaking with MacKinley, have you?\n\nIt's not what he thinks!  I'm not afraid to give him some Steamwheedle Bilge Rum...\n\nI just don't have any rum to give him!" } })
apply(2873, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Rumlieferung gefunden, {name}?", completion = "Spitze, danke für die Lieferung! Jetzt können MacKinley und ich endlich unsere Wette abschließen." }, enUS = { progress = "Did you find my shipment of rum, {name}?", completion = "Great, thanks for the shipment!  Now MacKinley and I can finally settle our wager." } })
apply(2874, { "classic", "forever" }, { deDE = { progress = "Hat Stoley meinen Rum ausgespuckt?", completion = "Hm, dann lasst uns mal probieren...\n\nIch kann es nicht glauben! Dieses Zeug ist... schrecklich! Großartig!\n\nNun, ich schätze Stoley kann das Geld behalten, das er mir schuldet. Er hat nicht übertrieben, als er vom Steamwheedle-Bilge-Rum erzählte. Dieses Zeug ist zähflüssig wie Sirup und brennt wie Lava!" }, enUS = { progress = "Did Stoley cough up my booze?", completion = "Hm, let's try this...\n\nI can't believe it!  This stuff is... terrible!  That's great!\n\nWell I guess Stoley can keep the money he owes me.  He's true to his word about Steamwheedle bilge rum.  That stuff is as thick as gravel and burns like lava!" } })
apply(2875, { "classic", "forever" }, { deDE = { progress = "Ihr seht etwas benommen aus. Habt Ihr unsere Rechtsdokumente gelesen?", completion = "Ah, Andres Kopf. Sieht so aus, als käme er letztendlich doch noch rechtzeitig zu seiner Verhandlung!\n\nIch weiß das zu schätzen, {name}. Wenn Ihr jetzt noch hier unterschreibt, kann ich Euch Eure Bezahlung für die geleisteten Dienste überreichen.\n\nMacht Euch wegen dem Kleingedruckten keinen Kopf. Es ist harmlos und ... ich glaube nicht, dass es eine genügend starke Lupe gibt, mit der man es überhaupt entziffern könnte." }, enUS = { progress = "You look a little dazed.  Have you been reading our legal documents?", completion = "Ah, Andre's head.  So I guess he'll make his trial after all!\n\nMuch appreciated, {name}.  Now if you'll just sign here, I can issue you payment for services rendered.\n\nDon't worry about the small print.  It's harmless, and... I don't think there's a magnifying glass small enough to read it anyway." } })
apply(2876, { "classic", "forever" }, { deDE = { progress = "Ihr seht atemlos aus. Habt Ihr mir etwas mitzuteilen?", completion = "Oh, das sieht nach einer Liste aller ankommenden und ablegenden Schiffe aus, komplett mit den richtigen Terminen und allem! Wenn der Kapitän eines Piratenschiffs das in die Finger bekäme, hätte er seine wahre Freude daran!\n\nIhr sagt, Ihr habt dies von einem Piraten? Hmmm, das sind beunruhigende Neuigkeiten ...\n\nDanke, {name}. Ich bin froh, dass Ihr es ihm abgenommen habt, und ich bin ebenso froh, dass dieser Pirat ins Gras gebissen hat!" }, enUS = { progress = "You look out of breath.  You have something to tell me?", completion = "Oh my, this looks to be a list of ship departures and arrivals, with accurate dates and times and everything!  If the captain of a pirate ship got his hands on this, he could have himself a field day!\n\nYou say you got this from a pirate?  Well that's disturbing news...\n\nThank you, {name}.  I'm glad you took it from him, and I'm glad that pirate's eating dirt right now!" } })
apply(2877, { "classic", "forever" }, { deDE = { completion = "Ja, schau mal einer an, Ihr habt den Wildhammers geholfen! Ihr seid ein {class} der Tat... und Taten respektieren wir hierzulande.\n\nEure kleine Aufräumaktion ist viel wichtiger, als Ihr vielleicht glaubt. Dank der Leute, die die Brühschlammer und Schlämme reduzieren, können wir unser Einflussgebiet unverzüglich ausdehnen. Hier - nehmt noch eine Kleinigkeit. Und natürlich habt Ihr Euch auf dem Aerie-Gipfel Freunde gemacht." }, enUS = { completion = "Well look at you, helping out the Wildhammers!  You're a {class} of action, and action is what we respect around here.\n\nYour little clean-up mission is a lot more important than you might think it is.  With folks thinning out the oozes and sludges, we'll be able to extend our sphere of influence in no time. Here - have a little something in addition to just making new friends here in Aerie Peak!" } })
apply(2879, { "classic", "forever" }, { deDE = { progress = "Der Equinex-Monolith steht stumm inmitten der Ruinen. Was mag er enthalten?", completion = "Es ist fast unmöglich, den aktivierten Stock festzuhalten. Seine Macht durchfährt Euren Körper.\n\nIhr greift nach der kalten Oberfläche des Equinex-Monolithen...\n\nEine kleine Tür öffnet sich. Ihr könnt hineingreifen und das Artefakt darin an Euch nehmen.\n\nLichtstrahlen erhellen das Gebiet um den Equinex-Monolithen." }, enUS = { progress = "The Equinex Monolith stands silently among the ruins. What could it be holding?", completion = "Holding the energized stave is almost impossible. Its power rumbles through your body.\n\nYou reach out to the cold surface of the Equinex Monolith...\n\nA small door opens, allowing you to reach in and take the artifact inside.\n\nBeams of light fill the area around the Equinex Monolith." } })
apply(2882, { "classic", "forever" }, { deDE = { progress = "Diese Truhe ist verschlossen.", completion = "Captain Cuergos versteckter Schatz erwartet Euch!" }, enUS = { progress = "This chest is locked!", completion = "Captain Cuergo's hidden treasure awaits!" } })
apply(2902, { "classic", "forever" }, { deDE = { completion = "Eine Untersuchung der Karte zeigt, dass es sich um die Schlachtpläne handelt, die Hadoken Swiftstrider haben will. Zahlreiche Pfeile, die vielleicht Truppenbewegungen darstellen, befinden sich auf der Karte, allerdings scheinen die meisten nach Süden zu deuten, nicht nach Norden, wo das Camp Mojache liegt.\n\nEin anderer Teil der Karte enthält ein Bild von etwas, das man für irgendein großes Insekt halten könnte. Darunter befindet sich eine Art Strichliste. So, wie die Gnolle aussehen, stellt diese vielleicht ihre Verluste gegen das unbekannte Ungeziefer dar..." }, enUS = { completion = "Examining the map reveals it to be the battle plans that Hadoken Swiftstrider wants.  Numerous arrows that perhaps represent troop movements are drawn on the map, though most seem to be headed toward the south rather than to the north where Camp Mojache lies.\n\nAnother section of the map has a picture of what you think is a large insect of some kind, with various tick marks under it.  From the looks of the gnolls, it perhaps represents their losses against the unknown bugs..." } })
apply(2903, { "classic", "forever" }, { deDE = { progress = "Willkommen zurück, {name}. Habt Ihr ein paar greifbare Hinweise auf die Pläne der Gnolle gefunden?", completion = "Ah, das ist genau, was wir gebraucht haben. Auch wenn ich nicht sehr geschickt darin bin, das ganze Gekritzel auf dieser Karte zu entziffern, so habe ich doch in meinem Leben genug Schlachtpläne gesehen, um zu verstehen, was mit den Gnollen passiert. Es sieht so aus, als würden sie derzeit einen Zwei-Fronten-Krieg führen. Einen mit uns... Aber wie es scheint, konzentrieren sie außerdem einen Großteil ihrer Energie auf einen Feind im Süden.\n\nHier läuft mehr, als auf den ersten Blick zu erkennen ist. Wir sollten möglichst bald herausfinden, wer dieser andere Feind, dem sie gegenüberstehen, wirklich ist." }, enUS = { progress = "Welcome back {name} - were you able to find some tangible evidence as to the plans of the gnolls?", completion = "Ah, this is exactly what we needed.  While I am not so skilled at ciphering what most of the scrawling on this map is, I've seen enough battle plans in my day to understand what is happening with the gnolls.  It looks like they are currently fighting a two front war.  One is with us... but it seems that their main energy has been against a foe to their south.\n\nThere's more at hand here than meets the eye.  Perhaps it is time to figure out who this other foe they face really is." } })
apply(2904, { "classic", "forever" }, { deDE = { completion = "Ich schätze, Ihr solltet dafür belohnt werden, Kernobee in einem Stück zurückgebracht zu haben, {name}. Wenn Ihr nach Gnomeregan zurückkehrt, könnten diese hier Euch den entscheidenden Vorteil liefern, den Ihr benötigt, um diesen nichtsnutzigen Verräter Robogenieur Thermaplugg zu besiegen." }, enUS = { completion = "I suppose you should be rewarded for bringing Kernobee back to us in one piece, {name}. If you go back to Gnomeregan, these might give you the edge you'll need in defeating that good-for-nothing backstabber, Mekgineer Thermaplugg." } })
apply(2922, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Techbot gefunden? Habt Ihr seinen Speicherkern gefunden?", completion = "Oh, das ist wunderbar!! Danke, {name}! Ich mache mich gleich an die Arbeit!!\n\nArmer, armer Techbot... Mach dir nichts daraus. Wir kriegen dich wieder hin.\n\nHm, wo hab ich diesen Aufsatz für meine Hydrowinden-Ratsche hingelegt..." }, enUS = { progress = "Did you find Techbot?  Did you retrieve its memory core??", completion = "Oh, this is wonderful!  Thank you, {name}!  I'll get to work immediately!!\n\nPoor, poor Techbot... Don't feel bad.  We'll get you fixed.\n\nNow, where did I put that plug for my hydro-jack swivel spanner..." } })
apply(2923, { "classic", "forever" }, { deDE = { completion = "Ja, es ist wahr. Techbot ist durchgedreht! Könnt Ihr mir bitte helfen?" }, enUS = { completion = "Yes it's true.  Techbot has gone rogue!  Please, can you help me?" } })
apply(2924, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die grundlegenden Artifixe?", completion = "Ihr habt sie! Jetzt kann ich mit meinen neuen Experimenten beginnen!\n\nIch kann Euch gar nicht genug danken, {name}! Durch Eure Tapferkeit hat die Gnomen-Forschung einen riesigen Schritt nach vorn gemacht." }, enUS = { progress = "Do you have the essential artificials?", completion = "You got them!  Now I can begin my new experiments!\n\nI can't thank you enough, {name}!  You're bravery has advanced gnomish research by a leap and a bound!" } })
apply(2925, { "classic", "forever" }, { deDE = { completion = "Allerdings! Ich brauche Hilfe bei einer Mission, die nach Gnomeregan hineinführt. Und Ihr seid genau der {class}, der das tun könnte!" }, enUS = { completion = "I do!  I do need help with a mission into Gnomeregan.  And you're just the {class} to do it!" } })
apply(2926, { "classic", "forever" }, { deDE = { progress = "Seht Ihr denn nicht, dass wir versuchen, ein ganzes Gnomen-Volk zu heilen?! Wir brauchen mehr von dem grünen Leuchten!", completion = "Ausgezeichnete Arbeit! Es ist an der Zeit, die neue Formel zu testen. Wenn sie funktioniert, sollte nicht nur dieser gefangene Lepragnom bald geheilt sein, sondern ich auch wieder ordentlich Haare auf dem Kopf haben. Tretet zurück!" }, enUS = { progress = "Can't you see we're trying to cure an entire species of gnomes here??! We need more of the green glow!", completion = "Excellent work! The time has come to test the new formula. If this works, not only should that captured leper gnome be cured, but I should have a full head of hair! Stand back!" } })
apply(2928, { "classic", "forever" }, { deDE = { progress = "Wenn dies ein Wettrennen wäre, hättet Ihr bereits verloren.", completion = "Das dürfte reichen, {name}. Ein gyrobohrmatischer Exkavationator ist geflickt; fehlen noch 398." }, enUS = { progress = "If this were a race, you would have lost by now.", completion = "This will do nicely, {name}. One gyrodrillmatic excavationator fixed; 398 left to go." } })
apply(2929, { "classic", "forever" }, { deDE = { completion = "Ich stelle mir gern vor, dass das Letzte, was ihm durch den Kopf ging, bevor er zu Boden sank, Euer Fuß war, {race}. Jetzt, da Thermaplugg tot ist, sind wir der Verwirklichung unseres Plans, Gnomeregan wiederzuerobern, einen Schritt näher gekommen." }, enUS = { completion = "I like to think that the last thing that went through his head as he collapsed to the ground was your foot, {race}. With Thermaplugg dead, our plans to retake Gnomeregan are one step closer to becoming a reality." } })
apply(2930, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Prismalochkarte?", completion = "Ihr habt es geschafft! Ihr habt die Prismalochkarte gefunden und die verlorenen Daten wiederbeschafft! Lebenswichtige, kritische, unvorstellbar wertvolle Daten, ohne die wir keine Minute länger hätten leben können!\n\nDer Dienst, den Ihr den Gnomen erwiesen habt, wird lange in Erinnerung bleiben, {name}." }, enUS = { progress = "Do you have the prismatic punch card??", completion = "You did it!  You found the prismatic punch card and recovered the lost data!  Vitally, critically, immeasurably important data that we could not live another moment without!\n\nYour service to the gnomes will be long remembered, {name}." } })
apply(2931, { "classic", "forever" }, { deDE = { completion = "Ich organisiere Datensicherungsmissionen nach Gnomeregan. Wenn Ihr deswegen hier seid, dann hört genau zu!" }, enUS = { completion = "I'm organizing data extraction missions into Gnomeregan.  If you're here for that, then listen up!" } })
apply(2932, { "classic", "forever" }, { deDE = { completion = "Ich habe von Eurer Tat gehört. Eine grausige Tat, aber eine voller Ehre. Lasst uns hoffen, dass die Witherbarks Eure Nachricht verstehen." }, enUS = { completion = "Word reached me of your deed.  A grim deed, but one of honor.  Let us hope the Witherbarks heed your message." } })
apply(2933, { "classic", "forever" }, { deDE = { progress = "Hallo, edler {class}. Der Tag war lang und nicht ein einziges Experiment ist geglückt... Ich hoffe, Ihr bringt mir gute Neuigkeiten.", completion = "Ah, und was ist das? Es sieht aus wie ein Gift... von irgendeiner Spinnenkreatur, schätze ich. Und wo habt Ihr das her?" }, enUS = { progress = "Hello, gentle {class}.  The day has been long and not a single experiment successful...I hope you bring good news to me.", completion = "Ah, and what is this?  It appears to be venom... from some arachnoid creature I deem.  And where did you get it?" } })
apply(2934, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den unbeschädigten Giftbeutel, {name}? Ich sehne mich danach, Experimente mit diesem frischen Gift anzustellen, und habe eine Ansammlung kleiner, unglaublich süßer Tierchen bestellt, um ihn an ihnen zu testen.", completion = "Oh, prächtig! Das Gift ist ziemlich frisch und sicher extrem tödlich. Danke!" }, enUS = { progress = "Do you have the undamaged venom sac, {name}?  I yearn to run experiments with its fresh venom, and have ordered a collection of small, terribly cute animals on which to test it!", completion = "Oh, splendid!  The venom is quite fresh and I'm sure very deadly.  Thank you!" } })
apply(2935, { "classic", "forever" }, { deDE = { completion = "Ah, Ihr wollt also frisches Gift von den Spinnen der Witherbarks, ja? Nun, setzt Euch... Es wird Euch nicht gefallen, was ich Euch sagen muss." }, enUS = { completion = "Ah, so you want fresh venom from the spider of the witherbarks, yes?  Well, sit down... you're not going to like what I have to tell you." } })
apply(2936, { "classic", "forever" }, { deDE = { completion = "Ah, Elortha no Shadra... Flüstert diesen Namen nur, denn seine Aussprache hat in der Welt der Geister großes Gewicht.\n\nIch werde ihn auf ein Pergament schreiben und für Euch einen Beschwörungszauber herstellen." }, enUS = { completion = "Ah, Elortha no Shadra... speak this name only in whispers, for its utterance carries much weight in the realms of the spirit.\n\nI will put it to parchment and create for you a spell of summoning..." } })
apply(2937, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Gift bekommen?", completion = "Prima, Ihr habt ihn!" }, enUS = { progress = "Did you get the venom?", completion = "Sweet, you got it!" } })
apply(2938, { "classic", "forever" }, { deDE = { progress = "Man hat mich von Eurem Kommen unterrichtet, {name}. Ihr habt ein Päckchen für mich?", completion = "Ah, sehr gut. Lydon erwähnte, dass das Gift in diesem Päckchen der potenteste ist, der ihm bisher untergekommen ist, und dass er gerade fieberhaft an neuen Anwendungen dafür arbeitet.\n\nWenn wir Glück haben, finden wir eine Menge davon.\n\nDanke, {name}. Eure Dienste für die königliche Apothekervereinigung können nicht geleugnet werden." }, enUS = { progress = "Word was sent of your coming, {name}.  You have a parcel for me?", completion = "Ah, very good.  Lydon mentioned the poison in this parcel is the most potent he has come in contact with, and is busy working on new applications with it.\n\nWith luck, we will find many.\n\nThank you, {name}.  Your service to the Royal Apothecary Society is undeniable." } })
apply(2939, { "classic", "forever" }, { deDE = { completion = "Oh, Troyas Moonbreeze hat Euch also geschickt?\n\n<gemurmelt>... ständig geht er mir mit seinen wilden Hoffnungen auf die Nerven, dass er etwas Wichtiges gefunden hat...\n\nSeht, {name}, ich sage es Euch ganz unverblümt. Troyas glaubt jedes Mal, dass er in diesen Ruinen etwas Wichtiges gefunden hat. Die Wahrheit ist aber, dass alles, was wirklich wertvoll war, wahrscheinlich vor langer Zeit schon von den Ogern oder Harpyien eingesackt wurde, die jetzt dort leben.\n\nIhr könnt Euch gern umsehen, aber ich weiß nicht, ob Ihr hier irgendwelche Bücher finden werdet, die Euch weiterhelfen." }, enUS = { completion = "Oh, so Troyas Moonbreeze sent you?\n\n<mutters>...always bothering me with his wild notions that he found something important...\n\nLook, {name}, I'll be blunt. Troyas always thinks he has found something important in those ruins. The truth is, anything that was truly valuable was probably hoarded away long ago by the ogres or the harpies that now reside there.\n\nYou're welcome to take a look around, but I don't know if you'll find any books here that will help you." } })
apply(2940, { "classic", "forever" }, { deDE = { completion = "Ihr wollt Euch also \"Feralas: Ein historischer Abriss\" ausleihen?\n\nLasst mich mal überlegen...\n\nIch werde Euch erlauben, das Buch auszuleihen, {name}, aber nur, wenn Ihr zuerst etwas für mich erledigt." }, enUS = { completion = "So, you'd like to borrow Feralas: A History?\n\nLet me think...\n\nI will allow you to borrow this book, {name}, but only if you do something for me first." } })
apply(2941, { "classic", "forever" }, { deDE = { progress = "Ein Brief - für mich?", completion = "Seid Ihr auch einer von Daryns Praktikanten? Sie ist eine ziemlich versierte Historikerin, {name}. Ihr solltet dankbar sein, unter ihrer Leitung zu studieren.\n\nJetzt lasst mich mal den Superschnapper FX holen. Ihr werdet ihn lieben!" }, enUS = { progress = "A letter -- for me?", completion = "Are you another one of Daryn's interns? She's quite a knowledgeable historian, {name}. You should be grateful to be studying under her leadership.\n\nNow, let me get the Super Snapper FX. You're gonna love it!" } })
apply(2942, { "classic", "forever" }, { deDE = { progress = "Ich bin froh, dass Ihr zurück seid, {name}. Ich brenne darauf zu hören, was Ihr herausgefunden habt.", completion = "Ich habe gelesen, seit Ihr gegangen seid, {name}. Dieser Stein, den Ihr gefunden habt, wird Morgenstein genannt. Wenn ich auch noch nicht ganz sicher ob seines Zweckes bin, so könnt Ihr doch sicher sein, dass es etwas von großer Wichtigkeit sein muss, so wie er im Equinex-Monolithen versteckt wurde.\n\nIch werde meine Studien fortsetzen und ich hoffe, dass ich in Zukunft auf Euch zählen kann, {name}. Danke für all Eure Hilfe." }, enUS = { progress = "I am glad you have returned, {name}. I am eager to hear of your findings.", completion = "I have been reading since you left, {name}. This stone you have found is called the Morrow Stone. While I am not entirely sure what its purpose is yet, you can be sure that it is something of great significance to be hidden away inside the Equinex Monolith the way it was.\n\nI will continue my studies, and I hope I will be able to count on you in the future, {name}. Thank you for all your help." } })
apply(2943, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Seid Ihr in Darnassus gewesen?", completion = "Ihr habt ein Buch mitgebracht. Ausgezeichnet!" }, enUS = { progress = "Hello, {name}. Have you been to Darnassus?", completion = "You have brought a book along. Excellent!" } })
apply(2944, { "classic", "forever" }, { deDE = { progress = "Ach, Ihr seid also endlich wieder da, {name}. Und Ihr habt den Apparat dabei, den Curgle für mich gebaut hat... perfekt.", completion = "Gut! Curgles Erfindung hat die Erwartungen erfüllt.\n\nWerdet nicht übermütig, aber wisset, dass ich mit Eurer Arbeit zufrieden bin, {name}.\n\nWo habe ich jetzt nur dieses Buch gelassen..." }, enUS = { progress = "So, you have finally returned, {name}. And you've brought the contraption that Curgle built for me -- perfect.", completion = "Well! Curgle's invention lived up to its expectations.\n\nDon't get too excited, but do know that I am pleased with your work, {name}.\n\nNow, where did I leave that book..." } })
apply(2945, { "classic", "forever" }, { deDE = { progress = "Der Gnomen-Apparat vor Euch trägt eine Plakette mit der Aufschrift \"Der Funkelmat 5200\". Laut der Anleitung unter der Plakette besteht der Sinn dieser Maschine darin, jedweden Schmutz von Gegenständen abzuschrubben. Um den Vorgang zu starten, legt man den Gegenstand in die Maschine und wirft drei Silbermünzen in den Münzschlitz.\n\nEs scheint, als sei der verkrustete Ring, den Ihr gefunden habt, geradezu perfekt, um diese Maschine auszuprobieren.", completion = "Ihr legt den Ring in den Funkelmat 5200 und werft eine Silbermünze in den Schlitz.\n\nFurchtbares Knirschen und Mahlen dringt aus der Maschine, als sie heftig zu ruckeln beginnt. Man kann nur raten, was mit dem Ring in der Maschine passiert...\n\nDann stoppt die Maschine plötzlich, ihren Stillstand mit einem einfachen \"Ding!\" verkündend. Der Aufnahmebehälter öffnet sich und offenbart eine kleine, hübsch verpackte Schachtel mit einer roten Schleife. Es scheint, als würde der Funkelmat 5200 alles auch gleich noch als Geschenk verpacken!" }, enUS = { progress = "The gnomish contraption before you bears a plaque calling it \"The Sparklematic 5200\".  The gist of the machine, from reading the instructions below the plaque, is to scrub away dirt that an item might have.  The machine has a coin slot, accepting three silver coins to start the process once the item is placed inside it.\n\nIt would seem as though the grime-encrusted ring you found earlier is just the thing to try in this machine!", completion = "You place the ring inside the Sparklematic 5200 and deposit a silver coin into the slot.\n\nPainful grinding noises emanate from the machine as it begins to jerk around violently.  One can only guess what is happening with the ring inside the machine...\n\nThe machine suddenly stops, trumpeting its cessation with a simple \"Ding!\"  The item receptacle opens up to reveal a small box that is neatly wrapped with a red bow.  It would appear that the Sparklematic 5200 also gift wraps!" } })
apply(2946, { "classic", "forever" }, { deDE = { progress = "Dieser vertraut aussehende Sockel ragt aus dem heißen Sand heraus. Vielleicht gibt es einen Grund für sein Hiersein...", completion = "Als Ihr den Sockel berührt, summen und glühen die Miniaturplatten von Uldaman in Eurem Rucksack. Eine vertrautes Kribbeln überzieht Eure Hände, als das Bild eines weiteren Steinbeobachters vor den Toren von Uldum zum Leben erwacht.\n\n\"Willkommen. Ich bin der Behüter des Eingangs. Die Scheiben, die für den Zugang verwendet wurden, beinhalten nicht die korrekten Zugangsscheiben, die Platten von Uldum. Bitte fügt diese Platten der Scheibenstruktur hinzu und wiederholt Eure Zugangssequenz. Danke.\"" }, enUS = { progress = "This familiar looking pedestal sticks out of the hot sand.  Perhaps there is something to its presence here...", completion = "As you touch the pedestal, the miniature discs from Uldaman hum and glow in your backpack.  A familiar feeling tingle washes over your hands, as the image of another Stone Watcher springs to life in front of the gates of Uldum.\n\n\"Salutations.  I am a guardian of entry.  The discs that have been used for access are missing the correct entry discs, the Plates of Uldum.  Please incorporate these plates with the disc structure and repeat your access sequencing.  Thank you.\"" } })
apply(2947, { "classic", "forever" }, { deDE = { progress = "He, immer mit der Ruhe, Partner - ich bin ein wichtiger Geschäftsmann! Der Kurier, der die Miete überbringen sollte, ist bestimmt einfach nur spät dran... Moment mal... Ihr seid ja gar nicht mein Vermieter.\n\nNatürlich seid Ihr das nicht - wie dumm von mir! Ihr seid hier, weil Ihr den besten Juwelier in ganz Ironforge sucht, einen, der KEINE VERFLUCHTEN Gegenstände herstellt. Jawohl!\n\nHm... Was braucht Ihr?", completion = "Ein Ring, sagt Ihr? Lasst mich mal sehen... Ja, und wie ich diesen Ring gefertigt habe.\n\nBevor Gnomeregan verloren ging, hatte ich dort einen kleinen Laden. Vielleicht ist es einer von denen, die ich zurückließ, als ich in die Hügel geflohen bin. Er ist recht schlicht gehalten und ich habe mehrere dieser Art hergestellt. Vielleicht gehörte er auch jemandem, der es nicht bis nach draußen geschafft hat.\n\nDunkeleisenzwerge hatten ihn? Tja, das fügt den ganzen Verschwörungstheorien, die bereits herumgeistern, eine weitere Ebene hinzu. Vielleicht interessieren sich offizielle Stellen dafür. Für Leute wie mich ist so etwas unwichtig.\n\nAber jetzt zurück zu diesem Ring..." }, enUS = { progress = "Hey, easy there partner - I'm a very important businessman!  I am sure that the courier is just simply late with the delivery of the rent... wait... you're not my landlord.\n\nWell, of course you aren't - silly me!  You've come to me seeking the finest jeweler in all of Ironforge, one who does NOT make CURSED items!  Yes!\n\nUm... what do you need?", completion = "A ring, you say?  Let's see... yep, I made that ring by golly.\n\nBefore Gnomeregan went up, I had a small shop there.  Perhaps it's one I left behind when I ran for the hills; it's a simple design, and I made several like it.  Maybe it's from someone who didn't make it out.\n\nDark Iron dwarves had this?  Well, that puts a new layer of conspiracy on the nine different layers already floating about.  Maybe the authorities would like to know; it's wasted on the likes of me.\n\nNow, back to the ring..." } })
apply(2948, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Materialien, die ich benötige? Ich würde Euch nicht darum bitten, wenn ich nicht gerade völlig vom Glück verlassen wäre...", completion = "Ah, genau das, was ich brauchte! Eines Tages, wenn ich es aus diesem Loch, in dem ich mich ungerechterweise befinde, herausgearbeitet habe, werde ich für Euch, nein für JEDERMANN die besten Schmuckstücke in ganz Azeroth herstellen! Bis es so weit ist, danke ich Euch, dass Ihr in Bezug auf die Reagenzien so anständig wart. Ich würde normalerweise zehnmal so viel für einen Ring von dieser Qualität verlangen, wie ich Euch abgeknöpft habe ...\n\nWo wir gerade davon sprechen, hier ist Euer neuer Ring!" }, enUS = { progress = "Do you have the materials I need?  I wouldn't ask you for them if I wasn't down on my luck...", completion = "Ah, exactly what I needed!  Someday, when I find myself out of this hole that I am unjustly in, I will make for you, for EVERYONE the finest trinkets in all of Azeroth!  Until then, thanks for being a sport about the reagents.  I'd normally charge ten times what I have charged you for a ring of this quality...\n\nSpeaking of rings, here's your new one!" } })
apply(2949, { "classic", "forever" }, { deDE = { progress = "Man sollte meinen, wir finden selbst einen Weg, diese dreckigen kleinen Gnome zu übertrumpfen. Ich würde sogar wetten, dass sie uns diese Maschine ursprünglich gestohlen haben! Pah, diese schleimigen, schmutzigen... ähm, ja? Braucht Ihr etwas?", completion = "Ein Ring aus Gnomeregan? Lasst mich mal sehen... nicht von mir, aber interessant.\n\nDiese Sache mit Gnomeregan - das hätte keinen größeren Trotteln passieren können. Jahrelang sind sie ein Witz und auf einmal bauen sie quasi über Nacht bessere Maschinen als wir?\n\nDunkeleisenzwerge hatten den Ring bei sich? Das wird ja immer interessanter! Hmmm, vielleicht haben die Gnome ja deren verrückte Golempläne gestohlen und verändert... Diese Dunkeleisenzwerge, die würden ihnen das bestimmt gern ordentlich heimzahlen. Es lohnt sich ganz sicher, da mal nachzuforschen.\n\nUnd da ist schließlich die Sache mit dem Ring..." }, enUS = { progress = "You'd think that we would find a way on our own to outdo those filthy little gnomes.  I would even wager that they stole that rig from us to begin with!  Bah, those greasy, grimy... erm, yes?  You need something?", completion = "A ring from Gnomeregan?  Let's see... not mine, but interesting.\n\nThe Gnomeregan thing - couldn't have happened to a nicer bunch of numbskulls.  For years they're a joke, and now almost overnight they're making better rigs than us?\n\nDark Iron dwarves had the ring?  That's even more interesting!  You know, maybe the gnomes stole their crazy golem plans and modified them.  Those Dark Irons, they'd definitely want some major payback.  It's certainly worth investigating.\n\nYou know, about that ring..." } })
apply(2950, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Materialien, die ich benötige? Ich kann dieses Stück nicht ohne die Dinge verbessern, um die ich Euch gebeten habe.", completion = "Hier habt Ihr Euren Ring, besser als je zuvor. Danke nochmals für die Information über diese Dunkeleisenzwerge. Das sieht nach einem vernünftigen Hinweis darauf aus, woher diese Gnome auf einmal mit Inspiration nach Goblin-Art gesegnet wurden." }, enUS = { progress = "Do you have the materials I need?  I can't improve on this design without everything I asked for.", completion = "Here's your ring, better than before.  Thanks again for the information about those Dark Iron dwarves.  This seems like a reasonable lead as to how those gnomes suddenly were struck with goblin-like inspiration." } })
apply(2951, { "classic", "forever" }, { deDE = { progress = "Es scheint, als brauche das Gerät irgendein schmutzverkrustetes Objekt zum Säubern sowie drei Silbermünzen, um den Apparat in Gang zu bringen. Ist beides vorhanden, sollte der Funkelmat 5200 funktionieren...", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftige, peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparates knarrt und ächzt, als er hin und her schlingert..." }, enUS = { progress = "It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working.  So long as both are present, the Sparklematic 5200 should work...", completion = "You insert the grime-encrusted item and three silver coins into the Sparklematic 5200.  The machine surges to life in an almost frenzied attempt to purge the grime from the unknown item.  Loud, violent churning sounds beat from the heart of the machine.  The metal frame of the beast creaks and groans as it lurches from side to side..." } })
apply(2954, { "classic", "forever" }, { deDE = { progress = "Der Sinn des Steinbehüters muss erst herausgefunden werden, bevor Ihr weitergehen könnt...", completion = "Die Stimme des Steinbeobachters erschallt voller Macht und Autorität:\n\n\"Ihr werdet Eure Scheiben zurückerhalten, wenn Ihr Zugang zum Sockel habt. Wenn Ihr die Platten von Uldum erworben und in Euren bestehenden Scheibensatz eingefügt habt, dann dürft Ihr den Komplex betreten.\"" }, enUS = { progress = "The purpose of the stone watcher must be learned before continuing on...", completion = "The stone watcher's voice resonates with power and authority:\n\n\"Your discs will be returned to you once you access the pedestal.  When you have obtained the Plates of Uldum and incorporated them into your existing disc set, you may then enter the complex.\"" } })
apply(2962, { "classic", "forever" }, { deDE = { progress = "Hm, Ihr leuchtet nicht. Das ist ein gutes Zeichen.", completion = "<Ozzie mustert Euch.> Erstaunlich, Ihr habt noch all Eure Gliedmaßen. Jetzt ist es an der Zeit nachzusehen, was dieses Zeug ausrichten kann!" }, enUS = { progress = "Hrm, you're not glowing. That's a good sign.", completion = "<Ozzie examines you.> Impressive, you still have all of your limbs. Now it's time to see what this stuff can do!" } })
apply(2963, { "classic", "forever" }, { deDE = { completion = "Ich bin froh, dass Ihr Euer Interesse für die Erforschung behalten habt, {name}! Mit Eurem naturgegebenen Geschick und Eurer Courage können wir Rätsel knacken, die wir nicht für möglich gehalten hätten!\n\nDie Scheiben von Norgannon in Uldaman waren eine wahre Fundgrube an Informationen. Ihr durftet lediglich an der Oberfläche der Informationen kratzen, die dort gespeichert sind. Die Schöpfer sollen Gerüchten zufolge weitere Speicher überall in Azeroth gehabt haben. Und das bringt uns nach Uldum ..." }, enUS = { completion = "I am glad you're maintaining your interest in exploration, {name}!  With your natural talent and moxie, we could crack open secrets that we never thought were possible!\n\nThe Discs of Norgannon in Uldaman were a repository of vast information; you were only permitted to access the top layers, as it were, of the information stored there.  The Creators were rumored to have more repositories located throughout Azeroth.  This now brings us to Uldum..." } })
apply(2964, { "classic", "forever" }, { deDE = { completion = "Wir sind uns demnach alle einig - die beste Vorgehensweise ist es, diese Angelegenheit erst einmal ruhen zu lassen, bis wir die Gebiete, in denen diese Scheiben versteckt liegen könnten, etwas eingrenzen können. Ihr habt uns so weit gebracht, {name}, und ich hoffe, dass Ihr derjenige sein werdet, der zurück ins Feld geht und Uldum für uns alle öffnet!\n\nErlaubt mir, Euch zwischenzeitlich dieses Honorar auszuhändigen. Dies sollte alle Ausgaben decken, die bei unserer Unterstützung angefallen sind, inklusive eines kleinen Bonus. Schaut bald wieder bei uns herein ... Uldum ruft!" }, enUS = { completion = "We're all in agreement then - the best plan of attack is putting this on hold until we can narrow down the areas where these plates might lie hidden.  You've brought us this far {name}, and I hope you will be the one to head back in to the field to unlock Uldum for us all!\n\nAllow me to give you this honorarium in the meantime; this should cover any expenses you've encountered in assisting us, and a little something extra.  Be sure to check back with us soon... Uldum beckons!" } })
apply(2965, { "classic", "forever" }, { deDE = { completion = "Es gibt tief in der Tanariswüste einen Ort, der Tal der Behüter genannt wird. Diese Scheiben, die Ihr geborgen habt... Die Übersetzung ihrer Glyphen erwähnt einen Ort, der Uldum genannt wird. Die meisten denken, dieser Ort sei ein Mythos.\n\nIch weiß, dass dem nicht so ist; Uldum existiert. Ich war dort. Nun... jedenfalls davor.\n\nDas Problem ist Folgendes, {name}: Wir glauben, es gibt eine Verbindung zwischen den Scheiben und Uldum, und wir wollen, dass Ihr dort hingeht." }, enUS = { completion = "There is a place deep in the Tanaris desert called the Valley of the Watchers.  The discs that you recovered... their translated glyphs make mention of a place called Uldum.  Most think this place to be a myth.\n\nI know this to be false; Uldum exists.  I've been there.  Well... outside, at any rate.\n\nThe crux is this, {name}: we think there is a connection between the discs and Uldum, and we want you to go there." } })
apply(2966, { "classic", "forever" }, { deDE = { progress = "Dieser vertraut aussehende Sockel ragt aus dem heißen Sand heraus. Vielleicht gibt es einen Grund für sein Hiersein...", completion = "Als Ihr den Sockel berührt, summen und glühen die Miniaturplatten von Uldaman in Eurem Rucksack. Eine vertrautes Kribbeln überzieht Eure Hände, als das Bild eines weiteren Steinbeobachters vor den Toren von Uldum zum Leben erwacht.\n\n\"Willkommen. Ich bin der Behüter des Eingangs. Die Scheiben, die für den Zugang verwendet wurden, enthalten nicht die korrekten Zutrittsscheiben, die Platten von Uldum. Bitte fügt diese Platten der Scheibenstruktur hinzu und wiederholt Eure Zugangssequenz. Danke.\"" }, enUS = { progress = "This familiar looking pedestal sticks out of the hot sand.  Perhaps there is something to its presence here...", completion = "As you touch the pedestal, the miniature discs from Uldaman hum and glow in your backpack.  A familiar feeling tingle washes over your hands, as the image of another Stone Watcher springs to life in front of the gates of Uldum.\n\n\"Salutations.  I am a guardian of entry.  The discs that have been used for access are missing the correct entry discs, the Plates of Uldum.  Please incorporate these plates with the disc structure and repeat your access sequencing.  Thank you.\"" } })
apply(2967, { "classic", "forever" }, { deDE = { progress = "Wilkommen zurück, {name}. Habt Ihr die Scheiben zu Eurem Vorteil nutzen können oder war alles vergebens?", completion = "Euch fehlten einige Scheiben? Interessant, es sieht so aus, als wären die Scheiben von Norgannon nur Teile eines vollständigen Satzes - wie Schlüssel auf einem Schlüsselring, wenn Ihr so wollt.\n\nWenn wir die Platten von Uldum finden könnten, hätten wir tatsächlich Zugang zum Uldum-Komplex selbst. Ich weiß nicht, ob ich mich ob dieser Aussichten freuen oder fürchten soll.\n\nWir müssen vielleicht alles riskieren, um sicherzustellen, dass die Geheimnisse der Erde, die uns alle zerstören könnten, genau das bleiben - nämlich Geheimnisse." }, enUS = { progress = "Welcome back {name}.  Were you able to use the discs to your advantage, or was it for naught?", completion = "You were missing some discs?  Interestingly enough, it seems that the discs of Norgannon are only parts of the complete set - like keys on a key ring, if you will.\n\nIf we can find the Plates of Uldum, then we could actually access the Uldum complex itself.  I don't know whether to be excited by that prospect, or be terrified.\n\nWe may need to risk everything to ensure that those secrets the earth keeps which would destroy us all remain just that - secrets." } })
apply(2968, { "classic", "forever" }, { deDE = { completion = "Wir sind uns demnach alle einig - die beste Vorgehensweise ist es, diese Angelegenheit erst einmal ruhen zu lassen, bis wir die Gebiete, in denen diese Platten versteckt liegen könnten, etwas eingrenzen können. Ihr habt uns so weit gebracht, {name}, und ich hoffe, dass Ihr derjenige sein werdet, der zurück ins Feld geht und den Geheimnissen von Uldum auf den Grund geht!\n\nErlaubt mir, Euch zwischenzeitlich dieses Honorar auszuhändigen. Dies sollte alle Ausgaben decken, die bei unserer Unterstützung angefallen sind, inklusive eines kleinen Bonus. Schaut bald wieder bei uns herein... Uldum ruft uns alle, junger Freund." }, enUS = { completion = "We're all in agreement then - the best course of action is to wait until we can narrow down the areas where these plates might lie hidden.  You've brought us this far {name}, and I hope you will be the one to head back in to the field to confront the secrets of Uldum.\n\nAllow me to give you this honorarium in the meantime; this should cover any expenses you've encountered in assisting us, and a little something extra.  Be sure to check back with us soon... Uldum beckons us all, young one." } })
apply(2969, { "classic", "forever" }, { deDE = { completion = "Dank sei Elune, {name}! Ihr seid ein großer Segen für uns und für die Flitzer, die Ihr gerettet habt. Jer’kai und ich hätten allein den Drachen nicht helfen können - Eure Einmischung in die Angelegenheiten der Grimmtotem wird nicht vergessen werden.\n\nSprecht jetzt mit Jer’kai... Ich muss unseren Vergeltungsschlag vorbereiten. Dass die Feendrachen frei sind, bedeutet nicht, dass es so bleibt. Jer’kai und ich werden jetzt in die Offensive gehen." }, enUS = { completion = "Thank Elune, {name}! You are a great blessing to us and to the darters you saved. Jer'kai and I would never have been able to help the dragons ourselves--your intervention in the Grimtotem's affairs will be remembered.\n\nSpeak to Jer'kai now... I have to prepare for our retribution. Just because the faerie dragons are free, it doesn't mean they will remain so. Jer'kai and I will now go on the offensive." } })
apply(2970, { "classic", "forever" }, { deDE = { progress = "Kindal benötigt Vorbereitungszeit, aber unsere Verluste gehen bereits in die Dutzende. Der Grimmtotemklan ist sich unserer Anwesenheit in der Gegend wohl bewusst und seine Mitglieder suchen uns wie giftige Vipern.\n\nSie werden alles in ihrer Macht Stehende tun, um uns die Köpfe abzureißen. Seid auf der Hut ... Sie werden jetzt, nachdem Ihr Euch eingemischt habt, auch hinter Euch her sein.", completion = "Kindal hatte Recht, was Euch betrifft, {name}... Ihr habt das richtige Händchen dafür. Ihr seid ein erfahrenerer Abenteurer als wir beide zusammen und dafür danken wir Euch.\n\nDer Grimmtotemklan ist viel feindseliger als die meisten Tauren... Ich frage mich, ob die Tauren die Taten von ihresgleichen missbilligen. Es würde mich nicht überraschen. Wie Euch wahrscheinlich klar sein dürfte, haben viele Völker Azeroths Verbindungen zu weniger freundlichen Zeitgenossen.\n\nDoch darüber reden wir ein andermal." }, enUS = { progress = "Kindal needs time to prepare, but our kills already number in the dozens. The Grimtotem clan is more than aware of our presence in the area, and they seek us out like vipers.\n\nThey'll do everything in their power to take our heads from our bodies. You should be alert... they'll be coming for you too now that you've interfered.", completion = "Kindal was right about you, {name}--you do have a knack for this. You are a more seasoned adventurer than the both of us, and for that we thank you.\n\nThe Grimtotem clan is much more hostile than most tauren... I wonder if their own kind frowns upon their actions. I wouldn't be surprised. As you are probably aware, many races on Azeroth have ties to less kindly counterparts.\n\nBut that is a discussion for another day." } })
apply(2972, { "classic", "forever" }, { deDE = { progress = "Hallo, Kindchen. Es freut uns, mächtige Abenteurer hier im Tempel zu haben. Wenn Ihr die Zeit findet, würdet Ihr mit den jüngeren Abenteurern die eine oder andere Geschichte teilen? Ich weiß, dass einige von ihnen von Eurer Weisheit profitieren könnten.\n\nIch bin untröstlich, wie unhöflich von mir. Ihr kamt in den Tempel, um unsere Hilfe zu ersuchen, und ich stelle Ansprüche an Euch. Bitte, verzeiht mir. Sagt mir, was die Diener des Lichts für Euch tun können.", completion = "Das ist eine erstaunliche Geschichte, {name}. Es freut uns, dass Ihr nicht nur den Drachen, sondern auch einer unserer Priesterinnen geholfen habt. Jer’kai hatte Recht, Euch zu mir zu schicken. Ich werde dafür sorgen, dass sie ihren Ring wiederbekommt - ich entsende ohnehin demnächst einige Späher in Richtung Feralas. Das wird eine weitere Sache sein, die sie auf ihrer Mission überprüfen können.\n\nDanke noch einmal, macht es Euch bitte bequem, solange Ihr hier seit." }, enUS = { progress = "Hello, child. It pleases us to have more powerful adventurers here in the temple. If you have the time, will you share a tale or two with the younger adventurers? I know many of them would benefit from your wisdom.\n\nI'm sorry, look how rude of me. You've come to the Temple seeking our aid, and I impose on you. Please, forgive me. Tell me what the servants of the Light can do for you.", completion = "That's an amazing story, {name}. It pleases us that you've not only helped dragonkind, but also one of our own priestess. Jer'kai was right to send you to me. I will make sure she has her ring returned to her--I have scouts heading the direction of Feralas soon. This will be one more thing for them to investigate while on their mission.\n\nThank you again, and please, make yourself at home while you're here." } })
apply(2973, { "classic", "forever" }, { deDE = { progress = "Die Grimmlingflitzer können gefährliche Tierwesen sein, wenn man sie provoziert. Seid vorsichtig im Umgang mit ihnen, {class}. Und passt noch viel mehr auf etwaige Nachtelfen in der Gegend auf. Diese lästigen Narren überfallen einen gern in den Wäldern.\n\nWenn Ihr genug Flügel habt, lasst es mich wissen, ich werde Euch sicher gut entlohnen!", completion = "Wunderbar, {class}! Die sind perfekt. Das sind genug, um einen Umhang für Korrin zu fertigen und vielleicht noch anderes! Danke.\n\nIch hoffe, die Reise war nicht zu gefährlich... Das Gebiet von Feralas ist nicht gerade als harmlos bekannt, aber Ihr habt Euch offensichtlich recht gut geschlagen.\n\nNochmals danke, {class}." }, enUS = { progress = "The sprite darters can be dangerous critters when provoked. Be careful when dealing with them, {class}. And be even more careful of any night elves in the area. The pestering fools tend to hold up in the forests also.\n\nWhen you've gotten enough of the wings, let me know, I'll be sure to reward you well!", completion = "Wonderful, {class}! These will do nicely. There are enough here to make a cloak for Korrin, and possibly even more! Thank you.\n\nI hope the trip wasn't too dangerous? The area of Feralas is not known for being forgiving, but you've obviously done well enough.\n\nThank you again, {class}." } })
apply(2974, { "classic", "forever" }, { deDE = { progress = "Nehmt meine Worte ernst, {class}, der Grimmtotemklan ist böse. Wenn Ihr seinen Aufenthaltsort herausgefunden habt, dann ist es an Euch, zurückzukehren und den ersten Schlag gegen ihren Klan zu führen... bevor er in unser eigenes Land kommt und unsere Dörfer auslöscht oder unser Land plündert.", completion = "Das sind gute Hörner, {class}. Gut gemacht. Ich nehme sie Euch ab und werde Belgrom garantiert davon berichten, sobald wir nach Orgrimmar zurückkehren. Ihr habt mir jetzt schon zweimal geholfen und dafür habt Ihr meine Anerkennung. Vielleicht kann ich Euch in Zukunft einmal helfen! Viel Glück noch für Euch." }, enUS = { progress = "Take my words seriously, {class}, the Grimtotem clan is evil. If you've found their whereabouts, then it's up to you to return and strike the first blow against their clan... before they can come into our own lands and raze our own villages, or pilfer our lands.", completion = "These are good horns, {class}. Well done. I'll take these from you and be sure to tell Belgrom as soon as we return to Orgrimmar. You've helped me twice now, and for that, you have my mark. Perhaps in the future I can help you! Good luck to you." } })
apply(2975, { "classic", "forever" }, { deDE = { completion = "Ausgezeichnet, {name}. Zur rechten Zeit wird das Land heilen. Wir dürfen nicht aufgeben." }, enUS = { completion = "Excellent, {name}. In time, the land will heal. We must not give up." } })
apply(2976, { "classic", "forever" }, { deDE = { progress = "Fasst Euch kurz, {class}, ich habe heute noch einiges zu erledigen.", completion = "Die Grimmtotem!? Das ist interessant. Ihr sagt, Ihr seid ihnen auf der Jagd in Feralas begegnet? Wirklich?\n\nMeine Partner werden Eure Neuigkeiten hören wollen, {class}. Erzählt mir mehr und ich werde derweil Eure Münzen abzählen.\n\nUnd bevor Ihr geht, wisset, dass ich Euch für die Informationen danke, die Ihr an diesem Tag an mich weitergegeben habt." }, enUS = { progress = "Be quick, {class}, I have much to complete today.", completion = "The Grimtotem!? This is interesting. You say you came across them while hunting in Feralas? Truly?\n\nMy peers will want to hear your news, {class}. Tell me more and I'll count out your coin while you do so.\n\nAnd before you go, know that I give you thanks for the information you've passed on to me this day." } })
apply(2977, { "classic", "forever" }, { deDE = { progress = "Willkommen zurück, {name}. Habt Ihr die Scheiben zu Eurem Vorteil nutzen können oder war alles letzten Endes nur Zeitverschwendung?", completion = "Euch fehlten einige Scheiben? Interessant, es sieht so aus, als wären die Scheiben von Norgannon nur Teile eines vollständigen Satzes - wie Schlüssel auf einem Schlüsselring, wenn Ihr so wollt.\n\nWenn wir die Platten von Uldum finden könnten, hätten wir tatsächlich Zugang zum Uldum-Komplex selbst! Stellt Euch nur vor, den Ort zu erforschen, an dem die Schöpfer gearbeitet haben, und das, ohne eine riesige Schaufel mitzunehmen.\n\nNicht, dass an einer Schaufel etwas falsch wäre ... oder am Graben ..." }, enUS = { progress = "Welcome back {name}.  Were you able to use the discs to your advantage, or did it end up being a wild goose chase?", completion = "You were missing some discs?  Interestingly enough, it seems that the discs of Norgannon are only parts of the complete set - like keys on a key ring, if you will.\n\nIf we can find the Plates of Uldum, then we could actually access the Uldum complex itself!  Imagine actually exploring the place where the Creators worked without having to bring a huge shovel!\n\nNot that there's anything wrong with shovels... or digging..." } })
apply(2978, { "classic", "forever" }, { deDE = { progress = "Was ist das?", completion = "Diese Schriftrolle... Ihr habt sie im Außenposten der Gordunni gefunden?" }, enUS = { progress = "What is this?", completion = "This scroll... You found this in the Gordunni Outpost?" } })
apply(2979, { "classic", "forever" }, { deDE = { progress = "Wir müssen mehr darüber herausfinden, warum die Gordunni hier sind, {name}.", completion = "Diese Kugel wird uns mehr Informationen über die Gordunni geben... die wir dann verwenden werden, um ihren Untergang zu planen, {name}." }, enUS = { progress = "We must discover more about why the Gordunni are here, {name}.", completion = "This orb will provide us with more information about the Gordunni... which we will then use in planning their downfall, {name}." } })
apply(2980, { "classic", "forever" }, { deDE = { completion = "Ihr habt Euch als ein vertrauenswürdiger und verlässlicher Verbündeter erwiesen, {name}." }, enUS = { completion = "You have proven yourself to be a trustworthy and dependable ally, {name}." } })
apply(2982, { "classic", "forever" }, { deDE = { completion = "Ich bin sehr dankbar, dass Ihr das für mich tun konntet.\n\nAber bitte kein Wort darüber zu Troyas..." }, enUS = { completion = "I am very grateful you were able to do this for me.\n\nNow, please, don't mention a word to Troyas about this..." } })
apply(2983, { "classic", "forever" }, { deDE = { completion = "Hmmm, hat Swart Euch geschickt, ja?\n\nNun denn, Swart kann man immer vertrauen. Das bedeutet, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, {name}. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, dennoch müsst Ihr wissen, wann Ihr Euch zurückhalten solltet." }, enUS = { completion = "Hmmm, Swart sent you to me, did he?\n\nWell then, Swart could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, {name}. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand." } })
apply(2984, { "classic", "forever" }, { deDE = { completion = "Hmmm, hat Narm Euch geschickt, ja?\n\nNun denn, Narm kann man immer vertrauen. Das bedeutet, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, {name}. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, dennoch müsst Ihr wissen, wann Ihr Euch zurückhalten solltet." }, enUS = { completion = "Hmmm, Narm sent you to me, did he?\n\nWell then, Narm could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, {name}. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand." } })
apply(2987, { "classic", "forever" }, { deDE = { progress = "Los jetzt, macht Euch auf den Weg und fangt an zu graben!\n\nIch muss noch andere Orte besuchen und andere Leute treffen - Zeit ist Geld!", completion = "Perfekt! Ich werde das auf meinen weiteren Reisen mitnehmen, {name}. Ich bin sicher, dass ich jemanden finden kann, der eine hübsche Summe für dieses Kobalt zahlen wird.\n\nHier, nehmt dies für Eure Mühen." }, enUS = { progress = "Get on up there and start digging!\n\nI've got places to go and people to see -- time is money!", completion = "Perfect! I will take these along as I continue my travels, {name}. I'm sure I can find someone that will pay a pretty penny for this cobalt.\n\nHere, take this for your trouble." } })
apply(2988, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Käfige durchsucht, {name}? Wir müssen Scharfschnabel finden!", completion = "Scharfschnabel war nicht in den Dörfern? Hm... Das ist eine schlimme Nachricht. Dieser Greif ist dazu bestimmt, die nächste Greifengeneration anzuführen. Wenn er verloren ist, werden die Stärke und der Geist unserer Flotte deutlich in Mitleidenschaft gezogen." }, enUS = { progress = "Have you searched the cages, {name}?  We must find Sharpbeak!", completion = "Sharpbeak wasn't at the villages?  Hm... this is grim news.  That gryphon is destined to lead the next generation of gryphons.  If he is lost then the strength and spirit of our fleet will suffer immensely." } })
apply(2989, { "classic", "forever" }, { deDE = { completion = "Scharfschnabel war nicht dort? Das sind schlechte Nachrichten, aber gleichzeitig auch gute...\n\nEs ist gut, dass er nicht am Altar von Zul war, denn die Trolle der Vilebranch sind dafür bekannt, Opferungen durchzuführen.\n\nIch danke Euch für all Eure Hilfe, aber ich fürchte, ich habe noch eine weitaus größere Aufgabe an der Hand." }, enUS = { completion = "Sharpbeak wasn't there?  That is bad news, but it is good news too...\n\nIt is good that he was not at the Altar of Zul for the Vilebranch trolls are known for performing sacrifices.\n\nI thank you for all of your aid, but I'm afraid I have an even greater task ahead." } })
apply(2990, { "classic", "forever" }, { deDE = { progress = "{name}, Ihr bringt mir ein Geschenk?", completion = "Oh, ja. Diese Feder gehört einem schönen Greifen. Einem, der für große Taten bestimmt ist... wenn er unbeschadet seine Kindheit übersteht.\n\nIhr wollt ihn finden? Dann hört genau zu, tapferer {class}..." }, enUS = { progress = "{name}, you come bearing a gift?", completion = "Ah, yes.  This feather belongs to a fine gryphon.  One destined for great things... if he can survive into adulthood undamaged.\n\nYou wish to find him?  Then listen close, brave {class}..." } })
apply(2991, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Nekrums Medaillon, {name}? In ihm liegen Kräfte, die ich gern enträtseln würde.", completion = "Ah, das Medaillon von Nekrum. Man sagt, es habe dem Troll ein unnatürlich langes Leben beschert - zu einem hohen Preis. Ich hoffe, einen Weg zu finden, die Macht des Medaillons zu nutzen und dabei seine... unangenehmen Nebenwirkungen zu vermeiden.\n\nIhr habt mir einen großen Dienst erwiesen, {name}. Ich werde jetzt meinen Teil der Abmachung einlösen." }, enUS = { progress = "Do you have Nekrum's Medallion, {name}?  There are powers hidden within it that I am eager to discover.", completion = "Ah, the medallion of Nekrum.  It is rumored to have given the troll an unnatural long life, but at a cost.  I hope to discover a way to reap the medallion's power while avoiding its... unpleasant side effects.\n\nYou have done me a service, {name}.  I shall now uphold my end of our bargain." } })
apply(2992, { "classic", "forever" }, { deDE = { completion = "Das Ritual verlief erfolgreich. Ich habe Scharfschnabel gesehen und kann Euch sagen, wie Ihr ihn findet." }, enUS = { completion = "The ritual was a success.  I have seen Sharpbeak and can tell you how to find him." } })
apply(2993, { "classic", "forever" }, { deDE = { completion = "Ihr habt mit Grimshade gesprochen? Was hat er gesagt?\n\n... Was? Die Vilebranchtrolle haben Scharfschnabel? Das ist unerträglich! Wir müssen eine Truppe zusammenstellen, um ihn zurückzuholen!" }, enUS = { completion = "You've spoken with Grimshade?  What did he say?\n\n...What?  The Vilebranch trolls have Sharpbeak?  That's unbearable!  We must organize a force to get him back!" } })
apply(2994, { "classic", "forever" }, { deDE = { completion = "Swiftwind und Keenclaw sind gerade mit ihrem Jungen zurückgekehrt und machen dabei ein Aufhebens wie frisch gebackene Eltern. Sie wiedervereint zu sehen, das treibt selbst diesem alten Zwerg hier ein paar Tränen in die Augen...\n\nWir können Euch gar nicht genug für das danken, was Ihr getan habt, {name}. Die Greife vom Aerie Peak und ihre Reiter werden Euren Namen für lange, lange Zeit singen." }, enUS = { completion = "Swiftwind and Keenclaw returned with their child moments ago, and are fussing over him like new parents.  Seeing them together again is enough to give even this old dwarf mist in the eyes...\n\nWe cannot repay you enough for what you have done, {name}.  The gryphons of Aerie peak, and their riders, will sing your name for a long, long time." } })
apply(2995, { "classic", "forever" }, { deDE = { completion = "Perfekt, {name}. Während die Hochtalelfen damit beschäftigt sind, ihre verlorenen Informationen wiederzuerlangen, können wir sie noch weiter abschotten..." }, enUS = { completion = "Perfect, {name}. While the Highvale work to recover their lost information, we will be able to seal off the lines even further..." } })
apply(2996, { "classic", "forever" }, { deDE = { completion = "Ein geschäftiger Tag in Ratchet, nicht wahr? Ich liebe es, dem Treiben einer Hafenstadt zuzusehen. So viel Wundersames, so viel Abenteuer... so viel Ignoranz.\n\nSehe ich da Hass in Euren Augen, {name}? Gut, wir werden daraus einen Vorteil ziehen." }, enUS = { completion = "A busy day in Ratchet, isn't it? How I enjoy watching the toil of a port city. So much mystery, so much adventure... so much ignorance.\n\nIs that hatred I see in your eyes, {name}? Good, we will put that to good use." } })
apply(2997, { "classic", "forever" }, { deDE = { completion = "Grüße, {name}. Ich hoffe, das Licht zeigt Euch den wahren Pfad und schützt Euch vor dem Bösen." }, enUS = { completion = "Well met, {name}. I hope the Light shows you the true path and keeps you safe from evil." } })
apply(2999, { "classic", "forever" }, { deDE = { completion = "Grüße, {name}. Ich hoffe, das Licht zeigt Euch den wahren Pfad und schützt Euch vor dem Bösen." }, enUS = { completion = "Well met, {name}. I hope the Light shows you the true path and keeps you safe from evil." } })
apply(3000, { "classic", "forever" }, { deDE = { completion = "Ich grüße Euch und heiße Euch willkommen, {name}." }, enUS = { completion = "I greet you, and bid you welcome, {name}." } })
apply(3001, { "classic", "forever" }, { deDE = { completion = "Ein geschäftiger Tag in Ratchet, nicht wahr? Ich liebe es, dem Treiben einer Hafenstadt zuzusehen. So viel Wundersames, so viel Abenteuer... so viel Ignoranz.\n\nSehe ich da Hass in Euren Augen, {name}? Gut, wir werden daraus einen Vorteil ziehen." }, enUS = { completion = "A busy day in Ratchet, isn't it? How I enjoy watching the toil of a port city. So much mystery, so much adventure... so much ignorance.\n\nIs that hatred I see in your eyes, {name}? Good, we will put that to good use." } })
apply(3002, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr mir gebracht, {race}?", completion = "Faszinierend, {name}...\n\nDiese Kugel ist sehr mächtig, aber auch sehr gefährlich." }, enUS = { progress = "What have you brought me, {race}?", completion = "Fascinating, {name}...\n\nThis orb is very powerful, but also very dangerous." } })
apply(3022, { "classic", "forever" }, { deDE = { progress = "Eine weitere Lieferung von Curgle, nicht wahr?", completion = "Danke für Eure Hilfe, {name}. Die Hippogryph-Population würde ohne uns einfach verkümmern. Aber ich denke, Ihr versteht das nur zu gut, schließlich seid Ihr ja selber nach Feralas gereist und habt die Verwüstung der Gordunni dort gesehen.\n\nNun, wie Ihr seht, bin ich sehr beschäftigt; macht Euch lieber gleich auf den Weg.\n\nNochmals danke, {name}." }, enUS = { progress = "Another shipment from Curgle, I assume?", completion = "Thank you for your help, {name}. The hippogryph population simply wouldn't flourish if it weren't for us. Ah, but I am sure you understand all too well, having traveled to Feralas yourself, and seen the devastation of the Gordunni there.\n\nWell, as you can see, I am hard at work here, so you'd best be on your way.\n\nThanks again, {name}." } })
apply(3042, { "classic", "forever" }, { deDE = { progress = "Bringt Ihr mir den Härter, {name}?", completion = "Ah, das ist wirklich guter Härter! Und so viel davon! Ich werde tagelang arbeiten können, bis alles aufgebraucht ist!\n\nDanke, {name}. Bitte, nehmt dies hier als Bezahlung." }, enUS = { progress = "Did you bring me the temper, {name}?", completion = "Ah, this is very nice temper indeed!  And so much of it!  I'll be at work for days before I use it all!\n\nThank you, {name}.  Please, take this as payment." } })
apply(3062, { "classic", "forever" }, { deDE = { progress = "Der Hass, den Edana über das Land verbreitet, muss gestoppt werden.", completion = "Jetzt weiß ich, dass Edana wahrhaft tot ist. Dieses Herz; ich werde es in Erinnerung dessen behalten, was Ihr hier für mich getan habt, {name}. Danke." }, enUS = { progress = "The hate that Edana spreads across the land must be stopped.", completion = "Now I know that Edana is truly dead. This heart; I will keep it in memory of what did here for me, {name}. Thank you." } })
apply(3063, { "classic", "forever" }, { deDE = { completion = "Danke, {name}. Ihr habt dem Geist eines alten Tauren Ruhe gegeben." }, enUS = { completion = "Thank you, {name}. You have put an old tauren's mind at peace." } })
apply(3065, { "classic", "forever" }, { deDE = { progress = "{race}, noch einer zur Verstärkung unserer Reihen. Mir soll's recht sein.\n\nIhr tut Euch wahrscheinlich schwer damit, eine gute Waffe wie beispielsweise eine Axt zu werfen, aber ein Speer ist genauso gut wie jede andere Waffe.\n\nWillkommen im Tal der Prüfungen.", completion = "Ihr werdet diesen Ort sehr geeignet finden für die weitere Ausbildung auf dem Weg zum {class}. Solltet Ihr Fragen haben, seid so frei und fragt jeden hier. Wenn Ihr bereit seid, kommt zurück und lasst mich Euch ausbilden. Ich habe so viele Situationen und Kämpfe gemeistert, wie jeder andere {class} hier im Tal und kann dieses Wissen an Euch weitergeben ... aber das hat seinen Preis." }, enUS = { progress = "Another {race} to bolster the ranks. Good enough for me.\n\nYou'll probably have a hard time hefting a good weapon like an axe, but a spear's just as good as anything else.\n\nWelcome to the Valley of Trials.", completion = "You'll find this place fitting as you continue to train in the {class} ways. If you have any questions, feel free to ask anyone around, and when you feel you're ready, come back to me for training. I've mastered as much as any {class} here in the Valley and can pass that knowledge on to you... for a price." } })
apply(3082, { "classic", "forever" }, { deDE = { progress = "Jen'shan sehen einen mächtigen {class} vor sich und die Geister geben Zustimmung.\n\nDer Weg des Jägers sein eine der ältesten Lebensweisen. Die Horde sich hat an uns gewendet, als sie ums Überleben kämpfen müssen auf Azeroth, und uns gebeten, ihnen in die Geheimnisse vieler Dinge einzuweihen. Sie bereits stark waren: stark als Schamanen; stark als Krieger. Aber Weg des Jägers nicht ihrer ... damals.", completion = "Wir ihnen bringen diese Dingens bei und sie uns lehren andere. Wir ein Volk werden... na ja, fast. Wir jetzt sein eine lange Zeit Verbündete. Ihr also denken dran, ihnen helfen. Und Jen'shan denken daran, Euch helfen.\n\nJen'shan Euch lehren dann Fertigkeiten von {class} - lehren Euch gut. Ihr nie vergessen, {class} viel respektiert von Stamm. Ihr werden spielen große Rolle in Zukunft... Ihr das nie vergessen.\n\nWenn Ihr wollen, kommen zu Jen'shan. Sie Euch lehren, so viel sie kann, wenn sie meinen, dass Ihr sein bereit." }, enUS = { progress = "Jen'shan see a mighty {class} before her and da spirits approve.\n\nDa path of da {class} is one of our oldest walks of life. Da Horde turned to us when they be just strugglin' to survive on Azeroth, and they ask us to teach them, to show them the secrets of many tings. They were strong already: strong in shaman ways; strong in warrior ways. But the {class} path not be their path... then.", completion = "Now we teach them those things, and they teach us others. We become one race... almost. We be allies for long time now. So you remember to help them. And Jen'shan remember to help you.\n\nJen'shan teach you da ways of the {class}--teach you good. You never forget, {class}'s be respected greatly by da tribe. You be havin' a large role to play in da future... you never forget that.\n\nWhen you feel da need, come to Jen'shan. She teach you as much as she can when she feel you ready." } })
apply(3083, { "classic", "forever" }, { deDE = { progress = "Willkommen im Tal der Prüfungen, {name}. Ihr wärt nicht hier, wenn Ihr meine Schrifttafel nicht erhalten hättet, daher komme ich gleich auf den Punkt.\n\nIch bin Rwag und zuständig für die Ausbildung der Schurken, Diebe und Taschendiebe hier im Tal. Ich bin derjenige, an den sich die Hand wendet, wenn Ihr nicht bereit seid für das, was auf Euch zukommt. Aber keine Sorge, die Hand kontrolliert nicht alles, was Ihr tut - es wäre jedoch ratsam, mit ihnen zusammenzuarbeiten, sollten sie je Bedarf für Eure Talente haben.", completion = "Bis dahin seid Ihr unter meiner Federführung. Ich werde Euch die Tricks lehren, wie manche dazu sagen. Wenn Ihr meint, dass Ihr vorbereitet seid, kommt zu mir und ich werde Eure Ausbildung fortsetzen. Bis dahin übt Eure Fertigkeiten und verfeinert sie auf's Beste. Man kann nie wissen, wann man selbst die unbedeutendste Fähigkeit benötigt." }, enUS = { progress = "Welcome to the Valley of Trials, {name}. You wouldn't be here if you hadn't gotten my tablet, so I will get to the point.\n\nI am Rwag and I am responsible for training the rogues, thieves, and cutpurses here in the Valley. I'm the one the Hand will turn to if you're not ready for what's to come. But don't worry, the Hand won't be controlling everything you do, but it would be wise to work with them if they have need of your talents.", completion = "Until such time comes, you'll be under my tutelage. I will show you the ropes as some folks say. Whenever you feel prepared, come to me and I will see about training you further. Until then, practice your skills and keep them honed to a razor's edge. You'll never know when you'll need even the most insignificant ability." } })
apply(3084, { "classic", "forever" }, { deDE = { progress = "Ah, willkommen, {name}. Schön, dass Ihr eingetroffen seid. Meine Tage sind so lang und geschäftig geworden, mit so vielen Schülern, die ich derzeit lehre - aber der Besuch von einem der Euren erfüllt mich mit tiefer Befriedigung - ich erinnere mich an die Tage, als ich von einem Eurer Schamanen unterrichtet wurde.", completion = "Wie Ihr möglicherweise wisst, geben uns die Elemente unsere Macht. Feuer, Erde, Wasser und Luft - das sind unsere Werkzeuge.\n\nUnsere Kraft erhalten wir von den Geistern unserer Vorfahren. Wir sind die Anführer unseres Volkes. Was Thrall für die Horde ist, werden wir für die Dörfer und Städte sein, die wir aufsuchen. Sie werden sich um Rat und Schutz an uns wenden. Ihr müsst häufig trainieren, um besser vorbereitet zu sein. Wenn Ihr fühlt, dass Ihr mächtiger geworden seid, kommt zu mir und ich werde Euch lehren, was ich vermag." }, enUS = { progress = "Ah, welcome, {name}. I'm pleased you have arrived. My days have become long and even busy what with so many students to teach, but the coming of one of your ilk brings me a great sense of accomplishment--I remember the days when I was taught by one of your shamans.", completion = "As you probably know, the elements give us our power. Fire, earth, water and air--these are our tools.\n\nOur strength comes from the spirits of our ancestors. We are the leaders of our people. Like Thrall is to the Horde, so shall we be to the villages and towns we visit. They will look to us for wisdom and protection. To be better prepared, you must train often. When you feel you've gained more power, come to me and I shall teach you what I can." } })
apply(3085, { "classic", "forever" }, { deDE = { progress = "So Ihr haben hierher geschafft... gut, gut! Geister mir gesagt, Ihr Ken'jai bald aufsuchen. Lasst mich einer der Ersten sein, der Euch im Tal der Prüfungen willkommen heißen. Diese Ort nicht sein Zuhause für lang, aber während es ist, warum nicht machen das Beste daraus.", completion = "Wenn Ihr Euch prüfen, Ihr werden finden, dass Ihr mehr und mehr Kontrolle über die Geister haben - Ihr können sie beschwören für immer größere Dinge... und da kommen der alte Ken'jai ins Spiel. Ihr kommen und reden mit dem alten Ken'jai, wenn Ihr fühlen, dass bereit sein. Wenn Geister zustimmen, dann wir lernen mächtigere Fähigkeiten... aber nur, wenn Geister zustimmen.\n\nGehen jetzt, reden mit anderen im Tal. Reden später wieder mit mir." }, enUS = { progress = "So ya made it... good good! Da spirits tol' me you be comin' to see Ken'jai soon enough. Let me be one o' da first to welcome ya to da Valley of Trials. Dis place not be your home fer long, but while it is, why dontcha make da best o' it.", completion = "As ya test yeself, ya'll find ya have better an' better control o'er da spirits--ya'll be callin' on dem fer greata an' greata tings...  dat's where ol' Ken'jai come in. You come talk to ole Ken'jai when ya feel yer ready. If da spirits agree, den we see 'bout teachin' ya more powerful abilities... but only if da spirits agree.\n\nGo now, talk to da rest of da Valley's people. Speak to me again later." } })
apply(3086, { "classic", "forever" }, { deDE = { progress = "Ihr Mai'ah schon viel Freude bereiten, {name}. Das sein gut. Ihr zollen Mai'ah Respekt, und Mai'ah vielleicht auch Euch zollen Respekt. Aber jetzt genug davon, Ihr sein hier, um über Magie zu lernen, nicht um Mai'ah reden zu hören.\n\nEs geben nur eins, was Mai'ah Euch nicht lehren kann über Magie, {name} - und das sein, wie zu stoppen Verderbnis.", completion = "Ihr werden sein eines der mächtigsten Lebewesen auf dem Planeten, {name}..., daran bestehen kein Zweifel. Und jeder wird es wissen... und gut wissen!\n\nAber Ihr müssen wachsam sein! Weil sein kein Orc oder Elf oder Zwerg, vor dem Ihr fürchten müsst Euch..., es sein Dinge, die Ihr nicht sehen können. Magie können sein mächtig. Euch Dinge tun lassen, die Ihr nicht tun wollen. Euch denken lassen, Ihr sein mächtiger als Ihr in Wirklichkeit sein. Haben Geduld. Seien schlau.\n\nWenn Ihr denken, dass bereit sein für Unterweisung, kommen zurück zu Mai'ah. Sie Euch lehren, was Ihr wissen müssen, kein Problem." }, enUS = { progress = "Ya look to please Mai'ah already, {name}. Dat be good. You give Mai'ah respect, and Mai'ah maybe give you respect back. But enough o' dat, you be here to learn 'bout magic, not hear Mai'ah talk.\n\nThere be only one ting Mai'ah can no teach you 'bout magic, {name}, and dat's how to stop da corruptin'.", completion = "You be among da most powerful beings on da planet, {name}... there no arguin' dat. And everyone know it... know it good, too!\n\nBut ya must be weary! 'cause it not orc, or elf, or dwarf dat you should be scared of... it be da tings you can'na see. Magic be powerful. Make you do tings you may not want to do. Make ya tink you more powerful then you really be. Be patient. Be smart.\n\nWhen ya tink you be ready for trainin', come back to Mai'ah. She teach you what you ready to learn, no problem." } })
apply(3087, { "classic", "forever" }, { deDE = { progress = "Ah, da Ihr sein schließlich. Gut. Jen'shan Euch haben erwartet.\n\nViele meinen, das sein ein einfacher Weg, aber Jen'shan Euch sagen, dass nicht stimmen. Die Beherrschung der Bestien von Durotar und darüber hinaus erfordern genauso viel Fertigkeit wie die Beherrschung der arkanen Künste oder das Reden mit unseren Vorfahren.\n\nDas Abfeuern eines Bogens oder eines Gewehres mögen Euch nicht so gefährlich erscheinen wie das Wirken eines Zaubers, es seien jedoch genauso gefährlich für Euren Feind.", completion = "Wenn wir fertig mit reden, Ihr solltet mit anderen Einwohnern des Tals reden. Sie Euch werden bitten, Dinge für sie zu tun... Dinge, mit denen Eure Fertigkeiten geprüft werden und die Euch einige der Gefahren dieses Landes aufzeigen.\n\nWenn Ihr erfahrener und weiser werdet, Ihr werden brauchen Jen'shan, um Euch bessere Techniken und Fertigkeiten zu zeigen. Besucht Jen'shan oft. Ich werde Euch dann mitteilen, was ich Euch lehren kann." }, enUS = { progress = "Ah, so you come at last. Good. Jen'shan be waitin' for you.\n\nMany tink it be an easy path, but Jen'shan tell you dat not true. Mastering da beasts of Durotar and beyond take as much skill as masterin' the arcane arts or speakin' to our ancestors.\n\nFirin' a bow or rifle may not be as dangerous to you as castin' a spell, but it sure be as dangerous to your enemy.", completion = "When we finish speakin', you should talk to da rest of da citizens in da Valley. They ask you to do tings for them... tings that will test your skill and teach you some of da dangers of this land.\n\nAs you grow in experience and wisdom, you be needin' Jen'shan to show you better techniques and skills. Come back to Jen'shan often. I will let you know what I can teach you." } })
apply(3088, { "classic", "forever" }, { deDE = { progress = "Schhht, nicht so laut. Ich traue Nartok dort drüben nicht. Mit jedem, der sich tiefer in einer Höhle verbergen muss als ich, ist nicht zu spaßen.\n\nIch vermute, Ihr hattet keine Probleme, Euch zurecht zu finden?", completion = "Jetzt, wo Ihr wisst, wo ich mich aufhalte, solltet Ihr Folgendes wissen: Die Shattered-Hand haben mich beauftragt, Euch zu suchen. Sie wollen, dass ich Euch unterweise und Euch über alles informiere, was sie brauchen können. Selbst falls Ihr noch nicht daran interessiert seid, ihnen zu helfen - obgleich Ihr ein Narr wärt, dies nicht zu tun -, werde ich tun, was immer ich kann, um Euch zu unterweisen ... natürlich gegen eine geringe Gebühr. Kommt zu mir zurück, wann Ihr meint bereit zu sein - und ich werde sehen, welche Lektionen Ihr lernen könnt." }, enUS = { progress = "Shhh, not so loud. I don't trust Nartok over there. Anyone that has to hide deeper in a cave than I do shouldn't be trifled with.\n\nI trust you had no problem finding your way around?", completion = "Now that you know where I'm holding up, I should let you know: the Shattered Hand's asked me to look out for you. They want me to train you and keep you informed of anything they might need. Even if you're not interested in helping them yet--which you'd be a fool not to be--I'll do what I can to train you... for a small fee. Come back to me anytime you think you're ready, and we'll see what you're ready to learn." } })
apply(3089, { "classic", "forever" }, { deDE = { progress = "Ihr seid also angekommen. Ich habe mich schon gefragt, ob Ihr wohl auftauchen würdet. Ich habe das Pergament bereits vor einiger Zeit geschickt und war mir nicht sicher, ob es auch angekommen ist.\n\nAber genug geplaudert... Ihr seid hier, weil Ihr auserwählt seid, auserwählt, das spirituelle Leben Eures Volkes zu leiten.", completion = "Ihr werdet der Kanal sein, über den unsere Vorfahren kommunizieren. Ihr werdet die Macht der Elemente zu Eurer Verfügung haben. Die Zerschlagung Eurer Feinde wird ein Kinderspiel sein; die Heilung Eurer Verbündeten so leicht wie das Atmen sein. Behaltet diese Dinge im Gedächtnis, während Ihr neue Herausforderungen meistert, und kehrt so oft zu mir zurück, wie Ihr wollt. Ich werde hier sein, Euch neue Zauber zu lehren, und Euch auf den richtigen Weg bringen, wenn Ihr bereit seid." }, enUS = { progress = "So, you've arrived. I was beginning to wonder when you would show yourself. I sent the parchment some time ago--I wasn't sure if it had arrived.\n\nBut enough chatter... you're here because you have been chosen, chosen to lead the spiritual lives of our people.", completion = "You will be the conduit in which our ancestors communicate. You will have the power of the elements at your beck and call. Sundering your enemies will be child's play; healing your allies as easy as breathing. Keep these things in mind as you face new challenges, and come back to me as often as you'd like. I will remain here to teach you new spells and set you on the correct path when you are ready." } })
apply(3090, { "classic", "forever" }, { deDE = { progress = "Endlich seid Ihr gekommen... und so diskret! Gut.\n\nUnsere Welt ist voller Narren, {name}. Selbst der mächtige Thrall hat mehr Fehler als die meisten erkennen können. Er wendet der Macht, durch die dieses Land ganz unser werden kann, den Rücken zu! Wir sind nicht dasselbe Volk, das einst von den Kreaturen aus dem Nether manipuliert und benutzt wurde. Wir sind ein eigenes Volk. Wir sind stolz... und wir sind stark.", completion = "Und nun seid auch Ihr unseren Reihen beigetreten. Versteht mich nicht falsch, {name}. Nur, weil Ihr Zugang zur Macht habt, auf die viele neidisch sind, bedeutet dies nicht, dass Ihr einfach akzeptiert werdet. Thrall lässt einen unserer Art nach Orgrimmar, weil wir noch immer seinesgleichen sind - er kann uns nicht den Rücken zuwenden oder wir würden ebenso pathetisch werden wie die Menschen, die ihn versklavten. Ich sage nur: seid vorsichtig. Ihr mögt mächtig sein, seid Ihr jedoch tollkühn, seid Ihr so gut wie tot.\n\nWenn Ihr eine Unterweisung im Zaubern benötigt, sucht mich wieder auf." }, enUS = { progress = "Finally, you've arrived... and discretely also. Good.\n\nOur world is full of fools, {name}. Even the mighty Thrall has greater flaws than most can see. He turns his back on the power needed to make this land ours completely! We're not the same people who were manipulated and used by creatures from the Nether. We are our own people. We are proud... and we are strong.", completion = "And now you've joined our ranks also. Don't misunderstand, {name}. Just because you have access to power that many will be jealous of, it does not mean you will be accepted easily. Thrall allows our kind into Orgrimmar because we are still his fellow kin--he cannot turn his back on us, or we would become as pathetic as the humans who enslaved him. My point is: be careful. You can be powerful, but if you are foolish, then you are as good dead.\n\nIf you need training in spells then return to me." } })
apply(3091, { "classic", "forever" }, { deDE = { progress = "Ah, {name}, Ihr seid endlich angekommen. In meiner Nachricht habe ich nicht gelogen, {name}. Wir sind von besonderer Art, nicht unähnlich den Druiden oder Schamanen unseres Stammes. Ihr seid ebenso wichtig. Wir sind die, die zur Verteidigung unserer Grenzen gerufen werden, zur Jagd auf den Zentauren und um in den Krieg zu ziehen.", completion = "Jeder von uns spielt in unserem Stamm eine Rolle. Jeder von uns muss auch dieselben Riten durchlaufen. Lasst Euch niemals von Eurem Stolz etwas anderes sagen.\n\nIch verbleibe hier, um neue {class} auszubilden, die Ruhm in Schlachten suchen und den Wegen der ältesten unserer Vorfahren folgen. Wenn Ihr Euch bereit fühlt, kommt wieder zu mir und ich werde tun, was ich kann, um Euch weiter auszubilden. Jetzt geht mit dem Segen des Stammes, {name}." }, enUS = { progress = "Ah, at last, you've arrived, {class}. I did not lie in my note, {name}. We are a special breed also, not unlike the druids or shamans of our tribe. You are just as important. We are the ones called upon to defend our borders, to hunt the centaur, and to go to war.", completion = "Each of us plays a role in our tribe. Each of us must also go through all the same rites. Do not ever let your pride tell you otherwise.\n\nI remain here to train new warriors that seek the glory of battle and who follow the ways of our oldest ancestors. When you feel ready, come back to me and I will do what I can to train you further. Go with the tribe's blessing, {name}." } })
apply(3092, { "classic", "forever" }, { deDE = { progress = "Willkommen im Camp Narache, {name}. Ich höre viel Gutes über Euch. Euer Geschlecht ist stark und viele der Ältesten halten Eure Fertigkeiten bereits für gut. Aber das wird sich in den Prüfungen zeigen.\n\nDie Ebenen von Mulgore werden für einige Zeit Euer Zuhause sein - Ihr solltet Euch bemühen, sie so gut wie möglich kennen zu lernen. Eines Tages werdet Ihr in unbekanntes Land aufbrechen, um größere Fertigkeiten zu erwerben. Dann müsst Ihr bereit sein.", completion = "Und es ist meine Aufgabe sicherzustellen, dass Ihr bereit seid, indem ich Euch die Grundlagen unserer Profession lehre - Euer Tier zu zähmen, Euer Gewehr abzufeuern und viele andere Fertigkeiten, die Ihr brauchen werdet.\n\n{class} sind ein starker Teil unserer Tradition und Geschichte, {name}. Ihr tätet gut daran, Euch zu erinnern, wie wichtig Ihr für den Stamm seid. Ihr werdet respektiert und verehrt, wenn Ihr unserem Volk gut dient." }, enUS = { progress = "Welcome to Camp Narache, {name}. I hear good things about you. Your bloodline is strong, and many of the elders consider you skilled already. But that we will test.\n\nThe plains of Mulgore will be your home for sometime--you should do your best to learn it very well. One day you will travel to unfamiliar lands to master greater skills. You must be ready.", completion = "And it is my job to make sure you are prepared by teaching you the basics of our profession--how to tame your pet, how to fire your rifle, and many other skills that will become necessary.\n\nHunters are a strong part of our tradition and history, {name}. You would do well to remember how important you are to the tribe. You will be respected and revered if you serve our people well." } })
apply(3093, { "classic", "forever" }, { deDE = { progress = "So schnell, wie Wasser vom Himmel fällt, seid Ihr hier eingetroffen. Eure Eile freut mich. Sie bedeutet, dass Ihr die Bedeutung unseres Treffens versteht und auch um die Bedeutung Eures Hierseins wisst. Ich bin kein Anführer, aber ich verstehe die Elemente und ich kann mit den Geistern unseres Volkes reden. Ich werde Euch lehren, es mir gleichzutun.", completion = "In den kommenden Tagen werden wir uns häufig sehen. Jedes Mal verlasst Ihr mich ein wenig mächtiger... ein wenig besser vorbereitet. Wie die ewige Flamme wird Euer Geist hell und heiß lodern.\n\nGeht jetzt, {name}. Geht und unterzieht Euch den Prüfungen. Ich werde hier sein, wenn Ihr mich braucht." }, enUS = { progress = "As quickly as water falls from the sky, here you are before me. I am pleased by your haste. It means you realize both the importance of our meeting and you being here. I am no leader, but I do understand the elements, and I can speak to the spirits of our people. I will teach you to do the same.", completion = "We will meet many times in the days to come. Each time you will hopefully leave my company a little more powerful... a little more prepared. Like the Eternal Flame, your spirit will burn bright and hot.\n\nGo now, {name}. Go and test yourself. I will be here for you when you need." } })
apply(3094, { "classic", "forever" }, { deDE = { progress = "Ihr seid gekommen. Das ist gut. In letzter Zeit sind die Geister unserer Vorfahren in ganz Mulgore und Umgebung rastlos, ich kann jedoch nicht sagen, warum. Es wird stets Eure Pflicht sein, zu lernen, den Naturgeistern zuzuhören und als ihr Avatar zu fungieren. Denkt stets daran.", completion = "Trotz unseres Bündnisses mit den Nachtelfen solltet Ihr kein herzliches Willkommen von ihnen erwarten. Ihr Stolz begrenzt noch immer ihre Sicht, aber das ist nicht unser Problem. Die Lehren der Erdenmutter sind alles, um was Ihr Euch kümmern müsst, und ich werde Euch lehren, was ich weiß, während Eure Weisheit zunimmt.\n\nSucht mich oft auf, {name}. Ihr werden feststellen, dass die Erdenmutter Ihren hingebungsvollsten Anhängern unglaubliche Fähigkeiten gewährt." }, enUS = { progress = "You have arrived. This is good. Our ancestors' spirits have become restless throughout Mulgore and beyond, but I cannot tell why. It will forever be your duty to learn to listen to nature's spirits, and act as their avatar. Be mindful of that.", completion = "Though we share a common bond, do not expect much welcome from the night elves. Their pride still limits their sight, but that is none of our concern. The teachings of the Earthmother are all you must concern yourself with, and I will teach you what I know as you grow in wisdom.\n\nReturn to me often, {name}. You will find that the Earthmother grants incredible abilities to those who are most dedicated." } })
apply(3095, { "classic", "forever" }, { deDE = { progress = "Ah, Ihr seid also eingetroffen. Gut. Ich habe mitbekommen, dass einige andere dem 'Tod' entrinnen konnten und in die Stadt flohen. Vielleicht zahlt sich diese Widerstandsfähigkeit künftig ebenfalls aus.\n\nIhr könnt Sylvanas für Eure Freiheit danken... die Freiheit von Geist und Körper. Obgleich Ihr noch immer von der Seuche und ihren Auswirkungen heimgesucht seid, steht es Euch jetzt frei, zu kommen und zu gehen wie es Euch beliebt.", completion = "Ich werde hier sein, Euch zu lehren, während Ihr an Erfahrung gewinnt... sucht mich so oft auf, wie Ihr mögt. Ich verlange eine minimale Gebühr, Ihr werdet jedoch alles, was ich Euch lehren kann, lohnenswert finden.\n\nGeht jetzt und prüft Eure Fertigkeiten. Während Ihr an Erfahrung gewinnt, werden sich Euch viele neue Dinge offenbaren; einige davon kann ich hier jetzt nicht mit Euch besprechen. Wisset nur, dass Sylvanas künftig {class} mit Kraft wie Euresgleichen brauchen wird. Ihr werdet das Rückgrat unserer Rettung sein. Vergesst das nicht." }, enUS = { progress = "Ah, so you've arrived. Good. I overheard that a few others were able to escape \"death\" and were heading into town. Perhaps that resilience will pay off in the future also.\n\nYou may thank Sylvanas for your freedom... freedom of mind and body. Though you still remain tortured by the plague and its effects, you are now free to come and go as you see fit.", completion = "I will be here to train you as you grow in experience... find me as often as you like. I charge a minimal fee, but you'll find everything I can teach you to be worthwhile.\n\nGo now and test your skill. Many more things will become known to you as you gain experience, some of which I am unable to discuss with you here. Just know that Sylvanas will need warriors with your type of strength in the future. You will be the backbone of our salvation. Do not forget it." } })
apply(3096, { "classic", "forever" }, { deDE = { progress = "Ihr habt es also hierher geschafft? Gut, wir brauchen mit der Zeit immer mehr Schurken. Die Schattenpirscher werden wahrscheinlich versuchen, Euch zu finden, wenn die Zeit reif ist; seht also zu, dass Ihr nicht in etwas hineingeratet oder etwas tut, was Ihr später bereut. Sie brauchen fähige Agenten ... keine Taschendiebe und Narren.", completion = "Ich habe die meiste Zeit hier im Gasthaus verbracht, auf neue Gesichter geachtet und nach möglichen künftigen Aspiranten Ausschau gehalten. Haltet die Nase frei und ich tue, was ich kann, um Euch einige Dinge zu lehren. Kommt einfach zu mir zurück, wann immer Ihr wollt und wir werden sehen, ob Ihr bereit seid für eine neue Fertigkeit oder zwei." }, enUS = { progress = "So you've made it? Good, we'll have need of more rogues as time goes on. The Shadowstalkers will probably wind up finding you when they think the time's right, so don't go and slip up or do anything you might regret. They need talented agents... not pickpockets and fools.", completion = "I spend most of my time here in the inn keeping an eye out for new faces and just keeping tabs on up-and-coming prospects. Keep your nose clean and I'll do what I can to teach you a few things. Just come back to me whenever you want, and we'll see if you're ready for a new skill or two." } })
apply(3097, { "classic", "forever" }, { deDE = { progress = "Ah, so kommt zwischen Feuer, Seuche, Aufständen und Schlimmerem ein Mal mehr ein 'Getreuer' an meine Tür. Nun, seid gegrüßt, {class}. Und lasst mich Euch kurz ein oder zwei Dinge zu erklären, bevor Ihr Euch auf die Suche nach dem macht, was immer Euch im Leben antreibt: Das Heilige Licht betrifft Euch nicht länger, die Geister Eurer Vorväter sind nurmehr schöne Geschichten und die Kreaturen aus dem Nether wollen Euch nicht.\n\nVersteht Ihr mich so weit?", completion = "Ihr müsst nur eins wissen: Wir haben durch schiere Willenskraft überlebt. Es ist der Glaube an uns selbst, der uns von anderen unterscheidet, und mit unserer Macht werden wir große Veränderungen in gesamt Azeroth herbeiführen. Die Schwachen werden auf Euch angewiesen sein. Die Leprakranken werden Euch Lord nennen. Und die Ignoranten werden Euch um Führung ersuchen. Es ist meine Pflicht sicherzustellen, dass Ihr die nötigen Werkzeuge habt, sodass Ihr bereit seid, wenn die Zeit gekommen ist. Sucht mich auf, während Ihr an Erfahrung gewinnt. Ich werde Euch lehren, wie Ihr noch mächtiger werdet, wenn Ihr dazu bereit seid." }, enUS = { progress = "Ah, so between fire, plague, rioting, and much worse, one more of the \"faithful\" comes to my door. Well, let me bid you welcome, {class}. And allow me a moment to explain a thing or two before you decide it's time for you to seek whatever drives you forward: the Holy Light no longer concerns you, the spirits of your forefathers are fairy tales, and creatures from the Nether don't want you.\n\nDo you understand me so far?", completion = "There is only one thing you must know: we have survived through will alone. It is faith in ourselves that separates us from others, and with our powers, we will cause great change in all of Azeroth. The weak will come to lean on you. The lepers will call you Lord. And the ignorant will look to you for guidance. It is my duty to make sure you have the necessary tools so when the time comes, you are prepared. As you grow in experience, seek me out. I will teach you greater powers if you are ready." } })
apply(3098, { "classic", "forever" }, { deDE = { progress = "Ich wusste, Ihr würdet zu mir kommen, {name}. Nicht, weil Ihr nicht den Willen habt, Eurem eigenen Weg zu folgen, sondern weil wir verwandte Geister sind. Beide haben wir Schmerz gefühlt. Beide haben wir gelitten. Und jetzt wollen wir die Macht, um uns das zurückzuholen, von dem wir wissen, dass es unser ist: dieses Land, unser Leben, unser Schicksal. Aber Ihr müsst noch immer viel lernen.", completion = "Ihr müsst oft zu mir zurückkehren, wenn Ihr mächtig genug werden wollt, um unsere Gegner zu vernichten. Die Regeln der Magie gelten noch immer für Euch, {name}. Ihr werdet noch immer feststellen, dass Euch die Verderbnis folgt, wie hungrige Wölfe in der Nacht. Ihr werdet ihre sanften Berührungen fühlen und feststellen, dass sie einer Sucht ähnelt, einem alten Liebhaber, dem es noch immer verlangt, an Eurer Seite zu sein. Ihr könnt diese Dinge jedoch abschütteln. Diese Dinge werden Euch nur kontrollieren, wenn Ihr dies zulasst.\n\nGeht jetzt und kehrt zurück, wenn Ihr mächtiger geworden seid." }, enUS = { progress = "I knew you would come to me, {name}. Not because you do not have the will to follow your own path, but because we are kindred spirits. We both have felt pain. We have both suffered. And now we want the power to take back what we know is ours: this land, our lives, our destinies. But there is much for you to learn still.", completion = "You must return to me often if you are to become powerful enough to destroy those who would oppose us. The rules of magic still apply to you, {name}. You will still find corruption follows you like hungry wolves in the night. You will find its caress is not unlike an addiction, an old lover still wanting to be by your side. But these things can be staved off. These things will only control you if you allow them to.\n\nGo now, return to me when you've grown more powerful." } })
apply(3099, { "classic", "forever" }, { deDE = { progress = "Ich heiße Euch willkommen, Bruder. Ich wusste, Ihr würdet kommen. Es war nur eine Frage der Zeit.\n\nWas ich sagte, hat Euch interessiert, nicht wahr? Es schlug eine Saite an... etwas in Euch wusste, dass meine Worte wahr waren. Gut.\n\nDoch wisset dies: Ich bin kein Verräter an Sylvanas. Wenn überhaupt, würde sie meine Worte zu schätzen wissen, wenn man bedenkt, dass es ihre eigenen Überzeugungen waren, die die Verlassenen in die Situation gebracht haben, in der sie sich jetzt befinden.", completion = "Ich sprach davon, dass ein Sklave immer ein Sklave bleibt, ungeachtet des Meisters. Erinnert Ihr Euch? Wir beide wissen, dass es diese Art von Kontrolle - diese Art von Macht - ist, die uns jetzt antreibt. Wir wollen, dass uns Kreaturen dienen. Wir wissen, dass wir mächtiger sind und mehr Respekt verdienen als andere uns zollen... Und somit streben wir jetzt danach, uns den Respekt zu nehmen.\n\nIch werde in diesem Kampf Euer Verbündeter sein - im Kampf um unsere eigene Freiheit. Die Freiheit, unsere eigenen Zugehörigkeiten wählen zu können. Wenn Ihr bereit seid, kommt zurück zu mir und ich werde Euch alles lehren, was ich weiß." }, enUS = { progress = "I bid you welcome, brother. I knew you would come. It was only a matter of time.\n\nWhat I said interested you, didn't it? I hit a chord... something inside you knew what I claimed was truth. Good.\n\nKnow this though: I am no traitor to Sylvanas. If anything, she would appreciate my claims considering it was her own beliefs that has put the Forsaken in the position it is now.", completion = "I mentioned a slave still being a slave, no matter the master. Do you remember? We both know that it is that type of control--that type of power--that now drives us. We seek to have creatures serve us. We know we are more powerful and deserve more respect than others give us ... and so now we look to take it.\n\nI will be your ally in this struggle--the struggle for our own freedom. Freedom to seek our own allegiances. When you feel ready, return to me and I will teach you all I know." } })
apply(3100, { "classic", "forever" }, { deDE = { progress = "Ah, Ihr habt meinen Brief erhalten, {name}... gut.\n\nIn letzter Zeit gab es einen Zustrom von Kriegern in Elwynn - was gut ist für Stormwind, jedoch schlecht für die Kobolde und Defias in dieser Gegend.", completion = "Messt Euch mit anderen, macht Euch mit den Gegebenheiten dieses Landes vertraut und kommt zu mir zurück, wann immer Ihr weitere Unterweisung wünscht. Ich werde hier sein, bei Tag und Nacht.\n\nDie Ritter der Silberhand haben viel geleistet und dies zu einem recht sicheren Ort gemacht; wenn Ihr aber andere Einwohner trefft, werdet Ihr wohl feststellen, dass sie alle Probleme haben, bei denen sie ein wenig Hilfe gebrauchen könnten - Hilfe, die ihnen ein {class} gewähren kann. Viel Glück." }, enUS = { progress = "Ah, you got my letter, {name}... good.\n\nThere's been an influx of warriors in Elwynn recently--which is good for Stormwind, but bad for the kobolds and Defias in the area.", completion = "Get yourself squared away, learn the layout of the land, and come back to me whenever you need training. I'll be here night or day.\n\nThe Knights of the Silver Hand have done well in making this place fairly safe, but as you meet the other citizens, I think you'll find they all have problems they could use some help with--help a {class} can give them. Good luck." } })
apply(3101, { "classic", "forever" }, { deDE = { progress = "Endlich! Wir stehen uns von Angesicht zu Angesicht gegenüber, Bruder und Bruder. Ich heiße Euch willkommen in Nordhain. Hier wird während der kurzen Zeit Euer Zuhause sein, in der Ihr lernt, wie die Dinge laufen, aber wisset, dass Stormwind nicht weit von hier ist und dass Euer Weg Euch über kurz oder lang dorthin führen wird. Bis dahin, habt Geduld... Ritter der Silberhand.", completion = "In der Zwischenzeit solltet Ihr einige andere Dinge wissen. Ihr seid ein Symbol für viele hier im Land - verhaltet Euch entsprechend. Das Heilige Licht leuchtet in Euch und dies ist sowohl für Eure Verbündeten als auch Eure Feinde offensichtlich.\n\nZudem, wenn Ihr an Weisheit und Macht gewinnt, müsst Ihr trainieren, um neue Fähigkeiten zu erlernen. Und da komme ich ins Spiel. Wenn Ihr denkt, dass Ihr genug Erfahrung hier in Nordhain gesammelt habt, kommt zu mir zurück und ich werde Euch die Dinge lehren, zu denen Ihr meiner Meinung nach bereit seid. Viel Glück... {class}!" }, enUS = { progress = "Finally! We meet face to face, brother to brother. I welcome you to Northshire. This will be your home for a short time while you learn the ins and outs of how things are done, but know that Stormwind is not far off, and sooner or later, your path will take you there. But until then, be patient... Knight of the Silver Hand.", completion = "In the meantime, you should know one or two other things. You are a symbol to many here in this land--act accordingly. The Holy Light shines within you, and it will be obvious to both your allies and your enemies.\n\nAlso, as you gain in wisdom and power, you will need to train to learn new abilities. That's where I come in. When you feel you've gained some experience here in Northshire, come back to me and I will teach you what I feel you are ready to learn. Good luck... {class}!" } })
apply(3102, { "classic", "forever" }, { deDE = { progress = "Ihr habt es in einem Stück hierher geschafft und es sieht so aus, als ob Ihr nicht von zu vielen Leuten gesichtet wurdet. Das reicht mir. Ich mag es nicht, zu viel Aufmerksamkeit auf mich hier zu lenken... ich bin gern für mich und unbehelligt. Ich bin sicher, Ihr versteht mich.\n\nGab es Ärger bisher? Nicht? Freut mich zu hören. Das wird sich jedoch schon bald ändern.", completion = "Ihr werdet feststellen, dass es eine Reihe von Gruppierungen für Eure Fertigkeiten gibt, {name}. Abenteurer, SI:7... sogar die Bruderschaft der Defias hätte gern einen Spion oder zwei in Stormwind. Aber vergesst nicht, es ist Eure Entscheidung. Lasst Euch nicht zu etwas drängen, was Ihr nicht tun wollt! Darüber hinaus halten wir alle Trümpfe in der Hand... zumindest werden wir dies, bevor das Spiel vorbei ist. Versteht Ihr, was ich meine?\n\nEgal, ich wollte mich nur kurz vorstellen und Euch wissen lassen, dass ich hier bin, wenn Ihr Unterweisungen wünscht. Ihr seid jederzeit gern gesehen." }, enUS = { progress = "You made it here in one piece, and it doesn't look like too many people saw you. Good enough for me. I don't like to have much attention drawn to me back here... nice and quiet. I'm sure you can understand.\n\nHave any trouble yet? I'm glad to hear not. That'll change soon enough.", completion = "You're gonna find a number of outfits that covet our skills, {name}. Adventurers, SI:7... heck, even the Defias Brotherhood wouldn't mind a spy or two inside Stormwind. But you remember this, you're your own man. Don't let nobody bully you into doing something you don't wanna do! Besides, we hold all the cards... at least, we do before the game's done. Know what I mean?\n\nAnyway, just wanted to introduce myself and let you know that I'm here if you need any training. Come by anytime." } })
apply(3103, { "classic", "forever" }, { deDE = { progress = "Ah, endlich seid Ihr gekommen. Ich wusste, Ihr würdet Euren Weg zu mir finden. Das Heilige Licht scheint auf Euch und den Weg, den Ihr gewählt habt. Die Zeiten sind hart - die Brennende Legion ist auf Azeroth noch immer allgegenwärtig, ganz Kalimdor sucht neue Wege, um sich vor den eigenen Widerwärtigkeiten zu schützen, und es ist an Euch, so vielen wie möglich zu helfen.", completion = "Während Ihr an Erfahrung gewinnt, sucht mich auf und ich werde tun, was in meiner Macht steht, um Euch mein Wissen zu vermitteln. Bis dahin, geht, haltet das Mitgefühl in Eurem Herzen und lasst Euch von der Weisheit leiten. Denkt daran, die Welt wird nur dann zu einem besseren Ort, wenn Ihr sie dazu macht." }, enUS = { progress = "Ah, at last you've come. I knew you would find your way to me. The Holy Light shines upon you, and the path you've chosen. These times are harsh--the Burning Legion still has a presence upon Azeroth, the entirety of Kalimdor seeks new ways to defend itself from its own tribulations, and it is up to you to aid as many as you can.", completion = "As you grow in experience, return to me and I will do what I can to impart my knowledge upon you. Until then, go with compassion in your heart, and let wisdom be your guide. Remember, the world only becomes a better place if you make it so." } })
apply(3104, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Ich bin Kheldon. Kann ich etwas für Euch tun?", completion = "Haha, ich wusste, meine Notiz würde Euch nicht von Eurem Weg abbringen. Ihr seid also bereit, hm? Bereit, Euer Schicksal anzunehmen? Bereit, die Götter herauszufordern und alle anderen Kräfte, die zwischen Euch und dem Erlangen von Wissen und Macht stehen?\n\nIch werde Euch nicht belügen, {name}, Ihr werdet ebenso gefürchtet wie respektiert werden. Aber wisset auch dies, ich werde hier sein für Euch, wenn Ihr Unterweisung benötigt. Sucht mich einfach auf, während Ihr mächtiger werdet." }, enUS = { progress = "Hello, {name}. I am Khelden. Is there something I can do for you?", completion = "Haha, I knew my note would not dissuade you from your path. So, you're prepared then, are you? Prepared to accept your fate? Prepared to challenge the gods and any other forces that stand before you in the pursuit of knowledge and power?\n\nI will not lie, {name}, you will be feared as much as respected. But also know this, I will be here for you when you need training. Simply seek me out as you grow more powerful." } })
apply(3105, { "classic", "forever" }, { deDE = { progress = "Ah, Ihr seid eingetroffen, und das keinen Moment zu früh, {name}. Einige Wachen waren gerade da und sahen mich sehr neugierig an... armselige sterbliche Geschöpfe.", completion = "Während Ihr mächtiger werdet, werdet Ihr in Versuchungen geraten - Ihr müsst stets daran denken die Kontrolle zu bewahren. Ich werde Euch nicht belügen - Verderbnis kann jeden Ausübenden der arkanen Künste ereilen, besonders diejenigen, die sich mit den Kreaturen des wirbelnden Nethers beschäftigen. Habt Geduld und seid vorsichtig... Aber nehmt Euch in Euren Ambitionen nicht zu stark zurück.\n\nWenn Ihr mächtiger werdet, sucht mich erneut auf und ich werde Euch mehr über unsere Lebensart lehren." }, enUS = { progress = "Ah, so you've arrived, and not a moment too soon, {name}. Some of the guards were over here a moment ago and were giving me curious looks... pathetic mundanes.", completion = "As you grow in power, you will be tempted--you must always remember to control yourself. I will not lie--corruption can come to any practitioner of the arcane; especially one who deals with creatures from the Twisting Nether. Be patient, and be prudent... but do not let that repress your ambition.\n\nAs you grow more powerful, return to me and I will teach you more about our ways." } })
apply(3106, { "classic", "forever" }, { deDE = { progress = "Verdammt, ist das kalt heute, was? Es scheint, als ob der Schnee nie schmelzen würde, {name}.\n\nIhr habt es wahrscheinlich längst gemerkt, dass jetzt Gnome in unserer Stadt leben. Und das nur, weil sie sich selbst das Dach überm Kopf weggesprengt haben. Erzählt das nicht weiter, aber ich kann es ihnen nicht mal verübeln ... wenn Ironforge so schlimm mit Dunkeleisenzwergen oder ähnlichen Kreaturen verseucht wäre, würde ich auch zu Sprengstoff greifen.", completion = "Es gibt noch mehr, was Ihr wahrscheinlich auch sehen werdet: Zwerge, die im Kampf Magie statt Gewehre einsetzen. Einige von uns beten das Heilige Licht an, wie einige der Menschen, und nicht zu vergessen, einige der Troggs. Ihr werdet später mehr über sie erfahren. Was Ihr jedoch wissen müsst, ist, dass ich da bin, um Euch zu helfen.\n\nIch werde Euch lehren, ein richtiger {class} zu werden. Jedes Mal, wenn Ihr meint, mehr Unterweisung zu brauchen, kommt Ihr zu mir und ich werde sehen, was ich tun kann." }, enUS = { progress = "Blast it's cold today, ain't it? It's like the snow never goes away, {name}.\n\nYou've probably noticed already, but there are gnomes now living in our city. That's because they went and got themselves blown out of their own home. Don't go spreadin' this 'round, but I can hardly blame them--I think I woulda resorted to explosives too if Ironforge were infested with Dark Irons or the like.", completion = "Other things you'll probably see too, just so yer in the know: dwarves usin' magic in a fight 'stead of a rifle. Some of us takin' to worshippin' the Holy Light like some of the humans, and, last but not least, troggs. You'll learn more 'bout them later, but what you need to know now is that I'm here to help ya.\n\nI be here to teach ya how to be a real {class}. Anytime ya think ya need more trainin', come back to me and I'll see what I can do." } })
apply(3107, { "classic", "forever" }, { deDE = { progress = "Ihr habt es also hierher geschafft! Und das keine Sekunde zu früh. Es gibt viel zu tun im Coldridgetal und in der Umgebung. Ich werde Eure Hilfe brauchen, so wie Ihr die meine!\n\nIhr seid nun ein Ritter der Silberhand, zeigt Euch der Aufgabe gewachsen.", completion = "Die Menschen haben uns viel über das Heilige Licht gelehrt und darüber, wie wichtig der Orden für sie ist... und für den Schutz von ganz Azeroth. Wir haben großen Respekt vor der Bedeutung der Tradition und davor, wie nur ein einziger, eine Opferung, den Unterschied bewirken kann zwischen Schmerz und Erlösung.\n\nWir zwei werden eine Weile zusammenarbeiten. Kommt zu mir zurück, wann immer Ihr meint bereit zu sein, und wir werden ein bisschen üben. Wir können Euch ja nicht unvorbereitet in die Welt hinausziehen lassen, oder?" }, enUS = { progress = "So, you've made it! And not a second too soon. There's much to be done in Coldridge Valley and beyond. I'm gonna need your help as much as you're gonna need mine!\n\nYou're a Knight of the Silver Hand now, be ready to play the part.", completion = "The humans have taught us a great deal about the Holy Light and how important their order is to them... and to protecting all of Azeroth. We have a great respect for how it is steeped in tradition, and how just one figure, one sacrifice, can make the difference between pain and salvation.\n\nThe two of us are gonna be working together for a bit. Any time you think you're ready, come back to me and we'll see about getting you some training. Can't have you go out into the world unprepared, now, can we?" } })
apply(3108, { "classic", "forever" }, { deDE = { progress = "Ihr habt's also hierher geschafft! Das ist eine gute Nachricht! Musstet mich wohl auch nicht verfolgen, um den Ort hier zu finden. Ha-ha!\n\nUnsere Profession ist recht traditionslastig, {name}. Die Gegebenheiten des Landes lernen. Einen Bären durch die Berge verfolgen lernen. Selbst das einfache Überleben, nur mit Hilfe des Verstandes, erfordert viel Mut und Schläue. Meint Ihr, dass Ihr dazu fähig seid?", completion = "Eines solltet Ihr niemals vergessen: Ihr müsst die Welt respektieren, in der Ihr lebt. Die Wildtiere, die den Kampf an Eurer Seite wählen; den Glanz Eurer Waffe; das Gewicht Eurer Munition; das Beißen eines schneidenden Windes; all diese Dinge müsst Ihr wie Eure Westentasche kennen.\n\nIch werde alles tun, was ich vermag, um Euch zu helfen; die meiste Arbeit müsst Ihr jedoch allein leisten. Sucht mich auf, wann immer Ihr meint, bereit zu sein. Ich bilde Euch aus, wenn ich kann!" }, enUS = { progress = "Ya made it! Good to hear! Betcha didn't have to track me to find the place either. Haha!\n\nOur profession is pretty steeped in tradition, {name}. Learning the ways of the land. Learning to track a bear through the mountains. Even just surviving on wits alone takes a great deal of courage and cunning. Think you're capable?", completion = "One thing you should always remember is that you gotta respect the world you're livin' in. The beasts that choose to fight along side you; the shine of your weapon; the weight of your ammo; the bite of a bitter wind; all these things you need to know intimately.\n\nI'll do what I can to help you, but most of the work's up to you. Anytime you think you're ready, come back and talk to me. I'll train you when I can." } })
apply(3109, { "classic", "forever" }, { deDE = { progress = "Ihr habt es hierher geschafft! Großartig!\n\nWir bemerken in letzter Zeit verstärkte Aktivitäten, daher bin ich froh, ein weiteres Mitglied des Ironforgeklans in unseren Reihen zu wissen. Für meinen Geschmack beschäftigen sich zu viele von uns mit dem Arkanen und Göttlichen. Nichts gegen sie und ihren Glauben, aber es geht doch nichts über eine kalte Klinge in der Hand und einen Schatten, der einen vor dem Licht schützt, wenn Ihr wisst, was ich meine?", completion = "Wie dem auch sei, wenn Ihr Euch in Coldridge umseht, werdet Ihr wahrscheinlich irgendwann in einigen Dingen eine Ausbildung benötigen. Kommt einfach zu mir zurück, wann immer Ihr das Bedürfnis nach Unterweisung verspürt, und ich werde Euch lehren, was ich weiß - einen Trick hier, ein kleines Manöver dort. Ihr wisst schon, alles Mögliche, was einen am Leben erhält und einige Münzen extra einbringt.\n\nHaltet auch Ausschau nach unseren gnomischen Freunden ... bei der Zerstörung von Gnomeregan haben sie wohl ... den Kürzeren gezogen. Sie brauchen unsere Hilfe, um sich hier zu Hause zu fühlen." }, enUS = { progress = "You made it! Great!\n\nWe've got an influx of activity lately, so I'm glad to count another of the Ironforge clan among our numbers. Nothin' like a cold blade in your hand and a shadow to keep you one step ahead, and if you're here, you know exactly what I mean!", completion = "Anyway, as you start peekin' around Coldridge you'll probably have need of training at some point. You just come back to me whenever you feel you need it and I'll teach you what I know--a trick here, a maneuver there. You know, the stuff that keeps you alive and makin' a little extra coin.\n\nKeep an eye out on our gnomish friends too... they kinda got the short end of the stick what with Gnomeregan being... destroyed. They'll need our help to feel welcome." } })
apply(3110, { "classic", "forever" }, { deDE = { progress = "Ahh! Ihr habt's also hierher geschafft, {name}! Großartig!\n\nWas ich sagen wollte, fast hätte ich den Glauben daran verloren, dass Ihr überhaupt erscheint..., versteht Ihr, den Glauben verloren? Nur ein Spaß, Jungchen... äh, ist ja auch egal. Ihr seid ja nicht gekommen, um meine schlechten Witze zu hören.", completion = "Ich kann Euch unterweisen, während Ihr lernt, Euch im Coldridgetal zurechtzufinden. Wenn Ihr Euch bereit fühlt, kommt zurück zu mir und wir werden sehen, ob Ihr schon so weit seid, einen oder zwei neue Zauber zu lernen, um das Tal gegen die verdammten Troggs zu verteidigen.\n\nIhr habt das Licht sowie ganz Ironforge auf Eurer Seite, {name}, ... kein Druck lastet auf Euch, etwas Besonderes zu werden.." }, enUS = { progress = "Ach! Ya made it, {name}! Wonderful!\n\nI was gonna say, I was about to lose faith that ye'd arrive at all... get it, lose faith? It's a joke, lad... aww, nevermind. Ya didn't come here for me bad jokes anyway.", completion = "I'm the one who can train ya as you start to find your way around Coldridge Valley. When ya feel yer ready, come back to me and we'll see about maybe teaching you a new spell or two to fend off the valley from them blasted troggs.\n\nYa got the Light on yer side, along with all of Ironforge, {name}... no pressure on ya to become somethin' special." } })
apply(3112, { "classic", "forever" }, { deDE = { progress = "Ah, nun, ein weiteres Memorandum von einem {race} im Einsatz... ist das nicht kurios.\n\nNein, nein, ich mache mich nicht über Euch lustig, Kleiner. Eure Zähigkeit verdient Respekt, so viel ist sicher. Ich wäre genauso verärgert, wenn Ironforge von Dunkeleisenzwergen eingenommen würde, glaubt also nicht, dass ich kein Mitgefühl verspüre für Eure Not...", completion = "Tja, wie ich sehe, ist dies Eure 'Oberste Direktive', oder wie auch immer Ihr dies heutzutage nennt. Ich habe mein Wort gegeben, dass ich alles in meiner Macht Stehende tun würde, um Euch und die Euren bereit zu machen, Eure Heimat zurückzuerobern... und genau das werde ich jetzt tun.\n\nWann immer Ihr bereit seid, kommt zurück zum alten Thran und ich werde mein Wissen gern mit Euch teilen. Für meine Unterweisungen nehme ich eine geringe Gebühr, aber es wird nicht zu teuer. Viel Glück." }, enUS = { progress = "Ah, well, another memorandum from a {race} on a mission... isn't this quaint.\n\nNo, no, I ain't teasin' ya, little one. Gotta respect your tenacity, that much is fer sure. I'd be just as peeved if Ironforge was taken by Dark Iron dwarves, so don't be thinkin' I don't feel for your plight...", completion = "Well, seein' how this is your prime directive, or whatever yer callin' it these days, I gave my word I'd do whatever I can to make sure you and yours were ready to take back your home... and that's just what I'm gonna do.\n\nAny time you feel yer ready, come back to good ol' Thran and I'll be happy to share my knowledge wit ya. There's some cost to me trainin' ya, but it won't be too expensive. Good luck." } })
apply(3113, { "classic", "forever" }, { deDE = { progress = "Bin froh, dass Ihr meine Nachricht erhalten habt und mich hier aufsucht. Tut mir Leid, dass ich vorgeben musste, das Memorandum stamme von einem Eurer Vorgesetzten... war nicht böse gemeint. Ich weiß einfach, dass wir beide, gemeinsam mit den anderen unserer Art, zusammenhalten müssen.\n\nNicht viele glauben, dass es gut ist, wenn sich Eure Art und meine Art in derselben Stadt verschanzen, aber ich denke, wir bekommen das schon gut hin. Was meint Ihr?", completion = "Ich bin hier in der Gegend ziemlich für mich geblieben, sodass man uns für fehlende Dinge nicht verantwortlich macht; doch wenn Ihr etwas benötigt, Unterweisung oder sonst was, kommt gern auf mich zurück.\n\nIhr und ich, wir verstehen einander. Wir wissen, dass man im Grunde nur der Familie trauen kann - und das ist genau das, was wir hier sein werden, nicht wahr? Ungeachtet dessen, dass Gnomeregan... überrannt wird und was sich uns auch sonst in den Weg stellen mag, wir geben uns gegenseitig Rückendeckung. Nicht wahr?" }, enUS = { progress = "Glad to see you got my note and came over. Sorry about pretendin' it was a memorandum from your higher-ups... no offense intended. I just knew the two of us, along with others of our kind, gotta stick together.\n\nNot many think it's the best thing in the world to have your kind and my kind holed up in the same city, but I think we can work things out just fine. What do you think?", completion = "I pretty much keep to myself around here so we don't get a bad rap for things gone missing, but if you need anything, some training or somethin', just come back anytime.\n\nYou and me got an understandin'. We know when it comes down to it you can only trust family... and that's just what we got going on here, isn't it? Regardless of Gnomeregan being... overrun, and whatever else is thrown our way, we got one another to back each other up. Right?" } })
apply(3114, { "classic", "forever" }, { deDE = { progress = "Ja, wie war das, {race}? Sprecht lauter, bitte. Nach einigen Bieren höre ich nicht mehr so gut.", completion = "Oh, ja! Arkane Künste... klaro.\n\nDas müsst Ihr wissen, {name}: Geht Ärger möglichst aus dem Weg. Spart einige Münzen auf, um mir ein Bier zu kaufen... oder irgendwelche Zauber, die Ihr wollt. Und bleibt auf jeden Fall weg von Gnomeregan. Ansonsten wünsche ich Euch einen angenehmen Tag! Ich werde hier sein, wenn Ihr mich braucht oder trainieren wollt... oder was auch immer." }, enUS = { progress = "Yeah, what's that, {race}? Speak up, if you don't mind. I don't hear so good after a few ales.", completion = "Oh, yeah! Arcane Arts... of course.\n\nHere's what you need to know, {name}: Don't get into too much trouble. Save some coin to buy me an ale... or any spells ya might want. And stay the heck away from Gnomeregan. Other than that, have a good day! I'll be here if you need me or want to train... or whatever." } })
apply(3115, { "classic", "forever" }, { deDE = { progress = "Großartig! Offensichtlich habt Ihr mein Memorandum erhalten.\n\nIgnoriert die Narren um Euch herum, {name}. Das Heilige Licht?! Das Schwert und Schild?! Dies sind keine Wege für jemanden mit einem so offenen Geist, wie wir ihn haben. Seht, wie \"normale\" Magie Eure Heimat zugerichtet hat. Zusammen mit diesen verdammten Tüftlern wurde unser Volk beinahe ausgerottet! Und jetzt müssen wir auf die Zwerge vertrauen - und die würden sich eher mit den Menschen verbünden, als uns beim Wiederaufbau unserer Heimat zu helfen. Wir sind wie Bürger zweiter Klasse. Habt Ihr gesehen, wie sie uns ansehen?", completion = "Aber nichts davon zählt wirklich. Was zählt ist, dass Ihr Euer eigenes Heiliges Licht gesehen habt! Ihr wisst, woher die Macht wirklich stammt. Ihr erkennt, dass es sehr viel... weiser ist, unsere eigenen Verbündeten zu haben. Spezielle Verbündete. Verbündete, die, ungeachtet der Aufgabe, bis zum letzten Atemzug gehorchen.\n\nUnd da komme ich ins Spiel, {name}. Ich kann Euch die Anfänge dieser speziellen Mächte lehren. Sucht mich häufig auf und ich werde tun, was in meiner Macht steht, um Euch weitere Zauber zu lehren." }, enUS = { progress = "Wonderful! You got my memorandum obviously.\n\nIgnore the fools around you, {name}. The Holy Light?! The sword and shield?! These aren't paths for ones as open minded as us. Look at what \"normal\" magic did to our home. Coupled with  those damned tinkerers, our race almost became extinct. And now we have to rely on the dwarves-- they'd rather spend time allying with humans than help us rebuild our own home. We're like second-class citizens. Have you seen the way they look at us?", completion = "But none of that matters. What matters is that you've seen your own Holy Light! You know where power truly comes from. You realize that having our own allies is much more... prudent. Special allies. Allies that, no matter the task, will obey till their last breath.\n\nAnd that's where I come in, {name}. I can train you in the beginnings of those special powers. Seek me out often and I will do what I can to teach you more spells." } })
apply(3116, { "classic", "forever" }, { deDE = { progress = "Ihr habt es hierher geschafft. Ich bin so froh.\n\nViel ist in den letzten Jahren geschehen, {name}: Die Erbauung von Teldrassil, die Verderbnis vieler Kreaturen des Waldes hier und in der Fremde, die Entdeckung von Ländern, von denen wir dachten, sie seien für uns verloren wie Feralas ..., so viel in so kurzer Zeit. Aber dies sind nur einige der Gründe, warum wir hier sind, der wichtigste ist, unsere Art vor weiterem Bösen zu schützen.", completion = "Bald werdet Ihr Angehörige anderer Völker im Geäst unserer Heimat sehen... lasst keine Vorurteile in Euch aufkommen. Sie sind willkommen. Sie werden uns helfen, wenn sie können. Nicht alle von ihnen tun dies aus purer Selbstlosigkeit, es sollte ihnen jedoch ein bisschen Vertrauen entgegengebracht werden.\n\nAber all das ist jetzt nicht wichtig. Jetzt müssen wir uns auf Euch konzentrieren und wie Ihr unserem Volk helfen könnt. Aus diesem Grund bin ich auch hier. Ich werde Euch in den Fertigkeiten eines Kriegers unterweisen, während Ihr stärker und stärker werdet. Kehrt zu mir zurück, wann immer Ihr wollt, und ich werde alles in meiner Macht Stehende tun, um Euch zu helfen." }, enUS = { progress = "You made it. I'm so glad.\n\nMuch has happened over the last few years, {name}: the creation of Teldrassil, the corruption of many of the forest creatures here and abroad, discovery of lands we thought lost to us like Feralas... so much, in so little time. But those are just some of the reasons we are here, the most important being to protect our kind from further evil.", completion = "Soon you will see others from different races in the boughs of our home--do not let it cause any prejudice within you. They are welcome. They will aid us when they can. Not all of them will be altruistic, but they should be granted some amount of trust.\n\nBut none of this matters now. Now we must focus on you, and how you can aid our people. I am here for that very purpose. I will train you in the ways of a {class} as you become stronger. Return to me whenever you wish and I will do what I can to aid you." } })
apply(3117, { "classic", "forever" }, { deDE = { progress = "Ihr seid im passenden Moment eingetroffen, {name}. Willkommen in Shadowglen.\n\nIch hoffe, mein Siegelzeichen erreichte Euch bei guter Laune und Gesundheit.\n\nWie ich bereits sagte, bin ich hier, um Euch als geschickten {class} auszubilden. Das bedeutet, Ihr werdet lernen, wie man Wildtiere zähmt, damit sie Euch im Kampf helfen, wie man den Bogen mit unfehlbarer Zielsicherheit einsetzt. Ihr werdet lernen, das Land, das wir Heimat nennen, zu respektieren und ebenso die Länder jenseits davon.", completion = "Während Ihr erlebt was Shadowglen Euch lehren kann, kommt und besucht mich - ich kann Euch dabei behilflich sein, Eure Aufgabe als {class} besser zu verstehen und zu erkennen, zu was Ihr fähig seid.\n\nWir leben in gefährlichen Zeiten, {name}, nehmt die Fertigkeiten Eurer Tiere nicht als gegeben an - es gibt in dieser Welt gefährlichere Dinge als Ihr Euch vorzustellen vermögt. Geht mit Elune und kommt wieder zu mir zurück." }, enUS = { progress = "You've arrived, and none too soon, {name}. Welcome to Shadowglen.\n\nI trust my sigil found you in good spirits and health?\n\nAs I said previously, I am here to train you as a {class}; to tame beasts to aid you in battle; to use a bow with unerring accuracy; to respect the lands which we call home and also the lands beyond.", completion = "As you experience what Shadowglen has to teach you, come see me--I will be able to help you understand more about your role as a {class} and what you are capable of.\n\nThese are dangerous times, {name}, do not take for granted the skill of your pets--there are things in this world more dangerous than you can imagine. Go with Elune and return to me again." } })
apply(3118, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Ich bin erfreut, dass Ihr mich gefunden habt, ich dachte schon, Ihr hättet Euch vielleicht auf dem Weg hierher verirrt.\n\nSeitdem ich Euch mein Siegelzeichen sandte, ist nicht viel Neues in Shadowglen passiert, aber ich überlasse es Euch, Informationen zu sammeln. Ihr könnt gern mit den anderen Leuten in Aldrassil sprechen, wenn Ihr möchtet.", completion = "Bis dahin solltet Ihr wissen, dass unsere Art in diesen bedrückenden Zeiten mehr als sonst gebraucht wird. Der Frieden mit den anderen Völkern kann jeden Moment zusammenbrechen und es wird häufig von Mitgliedern der Horde berichtet, die sich bemühen, eine immer größere Saat des Misstrauens zu säen. Bedenkt dies.\n\nKommt zu mir zurück, wenn Ihr stärker geworden seid und Euch besser vorbereitet fühlt und ich werde mich um Eure Ausbildung kümmern. Es ist unter anderem sehr wichtig, dass Ihr mit der Waffe Eurer Wahl gut umgehen könnt." }, enUS = { progress = "Hello, {name}. I'm glad you found me. I was thinking that perhaps you got lost on the way here.\n\nNothing really new has happened in Shadowglen since I sent you my sigil, but I'll leave all the information gathering to you. Speak to the rest of the people around Aldrassil if you'd like.", completion = "Until then, know that our kind are needed more than ever in this tenuous time. Peace with the other races can fail at any moment, and there is much talk about members of the Horde looking to sow even greater seeds of distrust. Remember that.\n\nAs you gain in power and feel more prepared, come back to me here and I will see about getting you some training. It's important that you know how to handle your weapon of choice, among other things." } })
apply(3119, { "classic", "forever" }, { deDE = { progress = "Ich bin sehr erfreut, dass Ihr so schnell eingetroffen seid, {name}. Willkommen.\n\nWie Ihr vielleicht bereits gehört habt, herrscht in ganz Teldrassil ein ständiges Kommen und Gehen von Reisenden. Sogar den Mitgliedern der Allianz wurde der Zutritt zu Teldrassils Ästen erlaubt, um sich mit anderen Kaldorei zu treffen, die sich auf die kommenden Abenteuer vorbereiten.", completion = "Aber im Moment müsst Ihr Euch nicht um die Welt unterhalb von Teldrassil kümmern. Dafür ist später noch Gelegenheit. Geht nun und sprecht mit den anderen in Shadowglen - sie können Euch mehr von den Ereignissen berichten, die sich zugetragen haben. Helft Ihnen so gut Ihr es vermögt, und wenn Ihr das Gefühl habt, weitere Ausbildung zu benötigen, kommt zu mir zurück und ich werde Euch lehren, was ich weiß." }, enUS = { progress = "It pleases me to see you've arrived so quickly, {name}. Welcome.\n\nAs you've probably heard, all of Teldrassil is stirring with the comings and goings of travelers. Even members of the Alliance have even been allowed access onto Teldrassil's boughs in order to meet with other Kaldorei who prepare for the adventures ahead.", completion = "Do not concern yourself with the world below Teldrassil for now. There will be time for that later. Go now and speak to the others in Shadowglen--they can tell you more about what events have transpired. Help them in any way you can, and anytime you feel you need more training, come back to me and I will teach you what I can." } })
apply(3120, { "classic", "forever" }, { deDE = { progress = "Ah, {class}. Ich sehe, dass Ihr es kaum erwarten könnt, Eure Studien fortzuführen. Gut.\n\nIch frage mich, ob Ihr schon viel Zeit im Smaragdgrünen Traum verbracht habt... Vielleicht seid Ihr darauf noch nicht genügend vorbereitet... Irgendwann wird es so weit sein, ganz sicher.\n\nDoch bis dahin sollten wir andere Dinge besprechen.", completion = "Vorerst werde ich Euer Mentor und Führer sein. Es ist meine Pflicht, Euch nicht nur zu lehren, wie man die Mitteilungen der Geister deutet, sondern auch die Komplexität und Geheimnisse des Smaragdgrünen Traums.\n\nJe mehr Ihr lernt und an Macht gewinnt, desto mehr werdet Ihr auch über unseren tranceähnlichen Schlaf erfahren. Aber bis dahin dürft Ihr so oft Ihr wollt zu mir kommen, und ich werde Euch alles, was ich über die Wege unserer Art weiß, lehren." }, enUS = { progress = "Ah, young {class}. I see you're eager to continue your studies. Good.\n\nI wonder, have you spent much time in the Emerald Dream already? Perhaps you're not prepared for that yet... In time, I'm sure.\n\nBut until then, we should discuss other matters.", completion = "I will be your mentor and guide for now. It is my duty to teach you how to interpret not only what the spirits communicate to us, but also the complexities and secrets of the Emerald Dream.\n\nAs you learn and grow in power, you will learn more of our sleeping trance. But until then, return to me as often as you like and I will teach you what I can in the ways of our kind." } })
apply(3121, { "classic", "forever" }, { deDE = { progress = "Ja?", completion = "Ich habe schon darauf gewartet, dass Uzer'i mir das bringt...\n\nIch möchte Euch diese Kräutermixtur geben, die ich für seine... ähm, Experimente vorbereitet habe..." }, enUS = { progress = "Yes?", completion = "I have been waiting for Uzer'i to deliver this...\n\nLet me give you the herb mixture I prepared for his... well, experiments..." } })
apply(3122, { "classic", "forever" }, { deDE = { progress = "Habt Ihr mit Neeru gesprochen?", completion = "Das ist genau das, was ich benötige, um das Muisekgefäß vorzubereiten, {name}. Bald schon werden wir sehen, ob meine neuesten Beschwörungen so mächtig sind wie ich gehofft hatte.\n\nEinen Moment, bitte. Ich muss das Ritual durchführen und die Kräuter ansetzen." }, enUS = { progress = "Have you spoken to Neeru?", completion = "This is just what I need to prepare the muisek vessel, {name}.  Soon we will see if my latest incantations prove to be as powerful as I had hoped.\n\nPlease, a moment. I must perform the ritual and apply the herbs." } })
apply(3123, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr einen Wildekin einfangen?\n\nWenn Ihr Erfolg habt, sind wir in der Lage, die Kreaturen von Feralas zu schrumpfen und deren Muisek einzufangen.", completion = "Bei einem grausamen Tod ist es möglich, dass das Muisek der Kreatur entkommt und Rache sucht. Durch das Schrumpfen der Kreaturen, wie Ihr es getan habt, {name}, kann das Muisek nicht entfliehen. Jetzt können wir ihn so benutzen, wie es uns gefällt!" }, enUS = { progress = "Were you able to capture the wildkin?\n\nIf you succeed, we will be ready to shrink and capture the muisek of creatures of Feralas.", completion = "Upon a violent death, the muisek of a creature may escape and seek revenge. Shrinking the creatures, as you did, {name}, prevents the muisek from escaping. Now we may use it as we please!" } })
apply(3124, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr die Hippogryphen einfangen?", completion = "Wenn wir ein Tier töten und dem Muisek erlauben, zu entfliehen, kann es die Gestalt einer noch größeren Kreatur annehmen. Wir wären niemals sicher vor seiner Rache.\n\nIch hatte Euch mit einer gefährlichen Aufgabe betraut, {name}. Und wieder habt Ihr sie gut bewältigt." }, enUS = { progress = "Were you able to capture the hippogryphs?", completion = "After killing an animal, if we allowed the muisek to escape, it may take the form of an even greater creature. We would never be safe from its vengeance.\n\nThis is a dangerous job I have given you, {name}. Again, you have completed it well." } })
apply(3125, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr das Muisek der Feendrachen einfangen?", completion = "Danke, {name}. Jetzt steht die geistige Macht der Feendrachen auch uns zur Verfügung.\n\nIch hoffe, Ihr seid willens, eine weitere Aufgabe für mich zu vollbringen." }, enUS = { progress = "Were you able to capture the muisek of the faerie dragons?", completion = "Thank you, {name}. Now the spiritual powers of the faerie dragon will be available to us.\n\nI hope you willing to perform another task for me." } })
apply(3126, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr die umherwandernden Waldgänger einfangen?", completion = "Danke, {name}. Unsere Muiseksammlung ist nahezu vollständig." }, enUS = { progress = "Were you able to capture the wandering forest walkers?", completion = "Thank you, {name}. Our muisek collection is almost complete." } })
apply(3127, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr die Bergriesen einfangen?", completion = "Denkt nur an all die Möglichkeiten, die wir jetzt besitzen, {name}. Zusammen mit den Materialien, die Ihr gesammelt habt, kann ich nun das Muisek dieser Kreaturen auf ewig in jeglicher Gestalt gefangen halten." }, enUS = { progress = "Were you able to capture the mountain giants?", completion = "Just imagine the possibilities of what we now possess, {name}. Along with the materials that you have collected, I will be able to forever trap the muisek of these creatures into whatever I wish." } })
apply(3128, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr die Materialien, die ich benötige, finden?", completion = "Exzellent! Diese Materialien, zusammen mit dem Muisek, sollten uns genau die Ergebnisse liefern, die wir benötigen." }, enUS = { progress = "Were you able to collect the materials I need?", completion = "Excellent! These materials, combined with the muisek, should yield just the results we've been wanting." } })
apply(3129, { "classic", "forever" }, { deDE = { completion = "Wie versprochen, habt Ihr nun die Wahl, {name}. Das Muisek dieser Kreaturen wurde auf ewig in die Macht dieser Waffen eingeschlossen.\n\nIhre Energie ist nun die Eure. Verwendet sie gut." }, enUS = { completion = "As promised, you have your choice, {name}. The muisek of the creatures has been forever sealed into the power of these weapons.\n\nYou may now wield their energy as your own. Use it well." } })
apply(3130, { "classic", "forever" }, { deDE = { completion = "Exzellent, {name}... ich schätze eine \"Geht klar\"-Einstellung bei Leuten, mit denen ich arbeite.\n\nIch wurde von General Feathermoon beauftragt, die Naga direkt anzugehen. Mein Plan besteht aus zwei Teilen: Abschnitt eins sieht vor, dass wir sie sowohl zahlenmäßig als auch hinsichtlich ihrer Befehlshaber schwächen, und danach werden wir herausfinden, was sie in den Ruinen vorhaben. Mit Eurer Hilfe werden wir den Naga entgegentreten, ohne die allgemeine Sicherheit der Festung zu beeinträchtigen." }, enUS = { completion = "Excellent, {name} - I value a \"can do\" attitude in those who I work with.\n\nI've been tasked by General Feathermoon to address the naga in a direct manner.  My plans are two fold: one, we will weaken their forces both in number and in command, and two, we will uncover what they are up to in the ruins.  With your help, we'll counter the naga presence without sacrificing the general security of the stronghold." } })
apply(3141, { "classic", "forever" }, { deDE = { progress = "Unterbrecht mich nicht, {race}.", completion = "So sei es..." }, enUS = { progress = "Do not interrupt me, {race}.", completion = "So be it..." } })
apply(3161, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Probleme?\n\nIhr könnt Gahz'ridian fast überall in Tanaris finden, {name}, also sucht weiter!", completion = "Perfekt, diese Ornamente sind einfach perfekt für meine Studien. Ich danke Euch sehr für Eure Hilfe, {name}.\n\nAch ja, kann ich meinen Helm zurückhaben?" }, enUS = { progress = "Are you having any trouble?\n\nYou can find Gahz'ridian just about anywhere in Tanaris, {name}, so keep looking!", completion = "Perfect; these ornaments are perfect for my studies. Thanks so much for the help, {name}.\n\nOh, can I get my helmet back?" } })
apply(3181, { "classic", "forever" }, { deDE = { progress = "Nein, ich werde das Tor nicht öffnen.", completion = "Was habt Ihr denn da? Offensichtlich eine Fälschung!\n\nIch stand Margol von Angesicht zu Angesicht gegenüber und weiß ganz genau, dass das Horn mindestens acht Mal so groß ist wie dasjenige, das Ihr in Euren Händen haltet, {name}. Das da habt Ihr wahrscheinlich von einer Sturmschnauze aus dem Brachland. Nein, werter Herr, Pebblebitty könnt Ihr nichts vormachen!" }, enUS = { progress = "No, I will not open the gate.", completion = "What have you got there? A fake obviously!\n\nI've been face to face with Margol and I know for a fact that her horn is at least eight times larger than the one you've got in your hands, {name}. You probably got that off of a stormsnout in the Barrens. No sir, you can't fool Pebblebitty!" } })
apply(3182, { "classic", "forever" }, { deDE = { progress = "Ah, guten Tag, junger Herr. Hättet Ihr gern eine Führung durch das Museum?", completion = "Was ist denn das?\n\nOh nein, das kann ich gar nicht glauben! Wisst Ihr, was Ihr da habt, {race}? Dies ist das Horn von Margol! Margol ist der Fluch eines jeden Archäologen, der jemals seinen Fuß in die sengende Schlucht gesetzt hat.\n\nKann ich es behalten?" }, enUS = { progress = "Why hello there young man. Would you like a tour of the museum?", completion = "What's this?\n\nOh my, I don't believe it! Do you realize what you've got here, {race}? This is the horn of Margol the Rager! Margol, the bane of every archaeologist that ever set foot in the Searing Gorge.\n\nMay I keep it?" } })
apply(3201, { "classic", "forever" }, { deDE = { progress = "Ich kann es nicht glauben.", completion = "Ich weiß zwar nicht, wie jemand, der so schwach ist wie Ihr, Margol überwältigen konnte, aber eine Abmachung ist eine Abmachung. Hier habt Ihr den Schlüssel.\n\nSollte Euch jetzt etwas zustoßen, ist es Eure eigene Schuld." }, enUS = { progress = "I don't believe it.", completion = "I don't know how someone as weak as you overcame Margol, but a deal is a deal. Here is the key.\n\nIf anything happens to you after this, it will be your own fault." } })
apply(3221, { "classic", "forever" }, { deDE = { completion = "Ah, sehr gut. Es gibt da etwas bezüglich der Wolfherzen, die Ihr mir gebracht habt, das unserer Aufmerksamkeit bedarf." }, enUS = { completion = "Ah, very good.  There is a matter regarding the wolf hearts you brought to me earlier that demands our attention." } })
apply(3261, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt. Ihr seid hier, um den Pfad des Jägers zu beschreiten?\n\nSehr gut. Lasst uns beginnen." }, enUS = { completion = "Greetings, young one.  You are here to walk the hunter's path?\n\nVery good.  Let us begin." } })
apply(3281, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Silber?", completion = "Aha! Also haben die Raptoren das Silber in ihrem Unterschlupf versteckt. Es ist kaum zu glauben, dass es diese Bestien nach Silber verlangt. Vielleicht sind diese Geschichten über ihre Intelligenz doch nicht so weit von der Wahrheit entfernt, wie ich dachte.\n\nDanke, {name}. Nehmt dies als Belohnung für Eure uns erwiesenen Dienste und wisset, dass die Wachen am Scheideweg ihren nächsten Monatslohn Euch verdanken." }, enUS = { progress = "Do you have the silver?", completion = "Aha!  So the raptors did hide the silver at their lair.  It's hard to believe these beasts would have the desire for silver.  Perhaps the stories of their intelligence are not as far from the mark as I thought!\n\nThank you, {name}.  Take this as a reward for your service to us, and know that the guards of the crossroads owe their next month's pay to you." } })
apply(3301, { "classic", "forever" }, { deDE = { progress = "Ich kann den Staub des Brachlandes an Euch riechen, {class}. Ihr seid weit gereist.", completion = "Ah... was ist denn das? Diese Schale glüht von innen, als ob in ihr noch Leben pulsierte. Erstaunlich! Ich muss sie weiter untersuchen.\n\nDanke, {name}. Wenn wir Glück haben, enthält diese Schale ein Geheimnis, das ich verwenden kann, um dem armen Land Silberwald zu helfen." }, enUS = { progress = "I can smell the dust of the Barrens on you, {class}.  You have traveled far.", completion = "Ah, what is this?  This shell has an inner glow, as if it still pulses with life.  Amazing!  I must study it further.\n\nThank you, {name}.  With luck, this shell will hold a secret I can use to aid the poor land of Silverpine." } })
apply(3321, { "classic", "forever" }, { deDE = { completion = "Erhebt Euch und seid gewürdigt, {name}, Schmied des Mithrilordens." }, enUS = { completion = "Rise and be recognized, {name}, blacksmith of the Mithril Order." } })
apply(3341, { "classic", "forever" }, { deDE = { progress = "Diese Angelegenheit ist von äußerster Wichtigkeit, {name}. Wir müssen jeden Versuch der Geißel zunichte machen, ihre Reihen zu vergrößern.", completion = "Die Loyalität eines Lich ist unerschütterlich, {name}. Lasst sie wissen, dass diese Loyalität ihnen nur Verderben bringt." }, enUS = { progress = "This matter is of utmost importance, {name}. We must stop any attempt by the Scourge to bolster their ranks.", completion = "The loyalty of a Lich is unswerving, {name}. Let them know that such loyalty will only bring them destruction." } })
apply(3361, { "classic", "forever" }, { deDE = { progress = "Liebe Güte {name}, diese Stadt ist für Leute wie mich nicht sehr geeignet. Hier gibt es ja ebenso viele widerliche Kreaturen wie in Gnomeregan vor diesem Unfall!\n\nHabt Ihr meine Habseligkeiten? Falls nicht... oje, wer weiß, was die Trolle damit angestellt haben...", completion = "Hurra, Ihr habt sie gefunden! Ihr seid wirklich eine echte Hilfe. Hier, es ist zwar nicht viel, aber doch etwas, um Euch für den Ärger zu entlohnen, den Ihr meinetwegen hattet. Danke!" }, enUS = { progress = "Oh goodness {name}, this town is not well suited for the likes of me.  There are as many nasty creatures here as there were in Gnomeregan before the accident!\n\nDo you have my belongings?  If you don't, then who knows what the trolls have done with them now...", completion = "Huzzah, you've found them!  You're an absolute savior, my friend.  Here, it's not much, but it's something for the trouble I've put you through!  Thank you!" } })
apply(3362, { "classic", "forever" }, { deDE = { completion = "So groß sind die? Ich muss meinen Plan vielleicht noch einmal überdenken...\n\nAber Ihr habt Euren Teil der Abmachung gehalten, also bekommt Ihr auch, was ich versprochen habe. Hier, nehmt." }, enUS = { completion = "They're that big? I might have to rethink my plan...\n\nBut you did hold up your end of the bargain, so here's what I promised." } })
apply(3364, { "classic", "forever" }, { deDE = { progress = "Jawohl, ich bin Durnan Furcutter. Habt Ihr denn etwas für mich?", completion = "Ah, sehr gut, das trifft sich ja wunderbar. Erlaubt mir eine kleine Pause, um dieses kochend heiße Morgengebräu zu genießen!" }, enUS = { progress = "Aye, I'm Durnan Furcutter.  You have something for me?", completion = "Ah good, now this will hit the spot.  Allow me to take a small break while I enjoy this scalding mornbrew!" } })
apply(3365, { "classic", "forever" }, { deDE = { progress = "Ich hoffe ja, dass das kochend heiße Morgengebräu Durnan rechtzeitig erreicht hat! Habt Ihr daran gedacht, mir meinen Becher zurückzubringen?", completion = "Exzellent, {name}! Ihr wärt überrascht, wenn ich Euch erzähle, wie viele Kuriere etwas so Einfaches wie das Zurückbringen des Bechers vergessen. Es heißt nicht umsonst, dass Becher nicht auf Bäumen wachsen!\n\nHier habt Ihr etwas für Eure Mühe. Ich danke Euch nochmals für Eure Hilfe." }, enUS = { progress = "I trust the scalding mornbrew got to Durnan on time!  Did you remember to bring me back my mug?", completion = "Excellent, {name}!  You'd be surprised how many couriers I meet who forget to do something as simple as bring back the mug.  Mugs don't grow on trees, or so they tell me!\n\nHere's a little something for the effort.  Thanks again for your help." } })
apply(3367, { "classic", "forever" }, { deDE = { progress = "Ich schaffe es nicht...", completion = "Dorius ließ diesen Brief fallen, als er erschossen wurde." }, enUS = { progress = "I'm not going to make it...", completion = "This letter was dropped by Dorius when he was shot." } })
apply(3368, { "classic", "forever" }, { deDE = { progress = "<Thorius schluchzt.>", completion = "<Thorius wischt sich sein Gesicht ab.>\n\nIm Namen des Lichts, sein Wunsch soll erfüllt werden. Das schwöre ich." }, enUS = { progress = "<Thorius sobs.>", completion = "<Thorius wipes his face dry.>\n\nIn the name of the Light, he will have his wish. This I vow." } })
apply(3369, { "classic", "forever" }, { deDE = { progress = "Kann ich Euch behilflich sein?", completion = "Falla hat Euch zu mir gesandt? Dann lasst mich mal jenen Splitter sehen, über den sie nur so ungern sprechen mochte, wie Ihr sagt...\n\n<Hamuul sieht in den Splitter>\n\nOh... Ich habe nicht... Nun ja.\n\n{name}, ich danke Euch, dass Ihr mir das hier gebracht habt. Lasst mich Euch jedoch sagen, dass es nicht sehr klug ist, von Dingen wie diesen zu sprechen. Das sind Dinge, mit denen Ihr Euch nicht beschäftigen solltet.\n\nSagen wir einfach mal, dass die Dinge im Smaragdgrünen Traum nicht so sind, wie wir es dachten...\n\nVielleicht werden wir uns einmal wiedersehen." }, enUS = { progress = "May I help you with something?", completion = "Falla sent you to me? Well now, let's see that shard that you say she was so hesitant to talk about...\n\n<Hamuul peers into the shard>\n\nOh... I didn't... Well.\n\n{name}, thank you for delivering this to me. It isn't wise to speak of things such as this, though, I advise you. These are matters that you should not concern yourself with.\n\nLet's just say that things in the Emerald Dream are not as we thought...\n\nPerhaps in the future, our paths may cross again." } })
apply(3370, { "classic", "forever" }, { deDE = { progress = "Kann ich Euch behilflich sein?", completion = "Falla hat Euch zu mir gesandt? Dann lasst mich mal jenen Splitter sehen, über den sie nur so ungern sprechen mochte, wie Ihr sagt...\n\n<Mathrengyl sieht in den Splitter>\n\nOh... Ich habe nicht... Nun ja.\n\n{name}, ich danke Euch, dass Ihr mir das hier gebracht habt. Lasst mich Euch jedoch sagen, dass es nicht sehr klug ist, von Dingen wie diesen zu sprechen. Das sind Dinge, denen sich die cenarischen Druiden allein stellen müssen.\n\nSagen wir einfach mal, dass die Dinge im Smaragdgrünen Traum nicht so sind, wie wir es dachten...\n\nVielleicht werden wir uns einmal wiedersehen." }, enUS = { progress = "May I help you with something?", completion = "Falla sent you to me? Well now, let's see that shard that you say she was so hesitant to talk about...\n\n<Mathrengyl peers into the shard>\n\nOh... I didn't... Well.\n\n{name}, thank you for delivering this to me. It isn't wise to speak of things such as this, though, I advise you. These are matters that the Cenarion druids alone must attend to.\n\nLet's just say that things in the Emerald Dream are not as we thought...\n\nPerhaps in the future, our paths may cross again." } })
apply(3371, { "classic", "forever" }, { deDE = { completion = "Lasst mich, helft den anderen." }, enUS = { completion = "Forget about me, help the others." } })
apply(3372, { "classic", "forever" }, { deDE = { progress = "Der Altar ist leer.", completion = "Ihr stellt das mysteriöse Artefakt auf den Altar von Suntara." }, enUS = { progress = "The altar is empty.", completion = "You place the mysterious artifact on the altar of Suntara." } })
apply(3373, { "classic", "forever" }, { deDE = { progress = "Während Ihr Euch dem Essenzborn nähert, von dem Eranikus Euch berichtet hat, ertönt seine Stimme erneut in Eurem Kopf.\n\n\"Ja, sterbliches Wesen, dieser Essenzborn wird den reinen Teil meiner Psyche, die sich noch innerhalb dieses Edelsteins befindet, erlösen. Legt den Edelstein in den Born hinein und lasst die Magie des grünen Drachenschwarms Verderbnis und Besudelung von meinem Wesen entfernen. Erst dann werde ich wahre Erlösung finden und erst dann wird der Drachenschwarm in der Lage sein, seine Führung über den Atal'ai wieder zu bestätigen.\"", completion = "Ihr legt den Edelstein in den Essenzborn hinein.\n\n\"Ich danke Euch, sterbliches Wesen, Ihr habt - nein... das, das darf nicht sein! Nein! Die Verderbnis dieses verfluchten Gottes hat sogar die Reinheit eines Essenzborns des grünen Drachenschwarms beschmutzt! Bitte, nein, ich fühle, wie meine Essenz von mir gerissen wird! DER SCHMERZ! Ich fühle, wie mich die Umklammerung eines ewigen Alptraums umschlingt...\"\n\n\"Sterbliches Wesen, ich flehe Euch an! Findet einen vom grünen Drachenschwarm, um dem ein Ende zu bereiten... helft mir... Ich bin in der Dunkelheit gebunden... auf ewig in Schmerzen... bitte nicht... foltern...\"" }, enUS = { progress = "As you near the essence font that Eranikus told you of, his voice once again touches your mind.\n\n\"Yes mortal, this essence font will redeem what untainted element of my psyche remains imbued in this gem.  Place the gem inside the font, and let the magic of the Green Dragonflight cleanse the corruption and taint from my being.  Only then will I find true release, and only then will the Dragonflight be able to reassert their stewardship over the Atal'ai.\"", completion = "You place the gem inside the essence font.\n\n\"Thank you mortal, you have - no... this, this cannot be! No!  The corruption of this accursed god even taints the sanctity of a Green Dragonflight essence font!  No please, I feel my essence ripping from me!  THE PAIN!  I feel the grip of an eternal nightmare taking hold on me...\"\n\n\"Mortal, I implore you!  Find one of the Green Dragonflight to stop this... help me... I am chained in darkness... forever in agony... please do not torture...\"" } })
apply(3374, { "classic", "forever" }, { deDE = { progress = "Hier sind wir nun, {name}, wieder an einem Scheideweg. Es ist jetzt an der Zeit, eine weitere Entscheidung zu treffen. Welche Wahl werdet Ihr treffen?", completion = "Ihr habt Eure Wahl getroffen und so beginnt es. Bis jetzt waren Eure Entscheidungen, soweit es mich betrifft, die richtigen. Eure Taten und Aktionen werden nun bestimmen, ob dies weiterhin der Fall sein wird." }, enUS = { progress = "Here we are {name}, at yet another crossroads.  The time has come to make another choice.  What choice do you make, mortal?", completion = "You have made your choice, and so it begins.  Your choices have been, to date, what I would consider to be the correct ones; your actions and deeds henceforth will determine whether this is to continue." } })
apply(3375, { "classic", "forever" }, { deDE = { progress = "Um eine weitere Phiole herzustellen, brauche ich einen Manatrank, ein Stück Kohle und etwas süßen Nektar.\n\nUnd außerdem anscheinend noch jede Menge Geduld.", completion = "Der mächtige Abenteurer bringt die Sachen herbei. Wie schön für mich. Übrigens, ich hab gelogen... ich hatte noch eine Phiole. Hng, nehmt sie.\n\nNa, was habt Ihr denn erwartet? \"Oh, hier, nehmt die hier! Ich bin ja nur ein Idiot, der nichts Besseres zu tun hat, als magische Kommunikationsgeräte an Abenteurer zu verschleudern!\" Eins ist jedoch sicher, das, was Ihr mir gebracht habt, reicht aus, um Euch eine weitere Phiole zu machen, wenn Ihr diese hier auch verlieren solltet.\n\nEs wäre jedoch schön, wenn ich mich irren würde und Ihr die neue nicht verliert, ja?" }, enUS = { progress = "To make another phial I need a mana potion, a piece of coal, and some sweet nectar.\n\nThat, and a whole lotta patience apparently.", completion = "The mighty adventurer delivers.  Hooray for me.  By the way, I lied - I had another phial.  Ungh, take it.\n\nWell, what did you expect?!  \"Oh, here, have another one!  I'm just some goofball who has nothing better to do than hand out magical communication devices to adventurers!\"  Rest assured though, what you have given to me will be enough make you another phial when you lose that too.\n\nPlease prove me wrong and don't lose the new one, okay?" } })
apply(3376, { "classic", "forever" }, { deDE = { progress = "Spitzhauer wird uns nicht mehr belästigen, sobald Ihr mir den Beweis seines Todes liefert. Ich will seinen Kopf, {name}.\n\nWir {race} leben für die Jagd und es gibt keine größere Jagd als gegen einen, der schlau genug ist, uns vielleicht auch zu jagen. Wenn Ihr in dieser Aufgabe erfolgreich seid, werdet Ihr anfangen zu begreifen, was ich meine.", completion = "Der Gerechtigkeit wurde heute durch Eure schnellen Taten Genüge getan, {name}. Möge sein Tod allen als Warnung dienen, die unsere Heimat bedrohen.\n\nIhr habt diese Belohnung verdient, die Euch auf Euren Reisen helfen soll, {class}." }, enUS = { progress = "Sharptusk will trouble us no more once you have brought me proof of his death.  It is his head that I seek, {name}.\n\nWe {race} live for the hunt, and there is no greater hunt than against one that is cunning enough to perhaps hunt us back.  If you are successful in this task, young one, you will start to learn what I mean.", completion = "Justice has been served on this day by your swift actions, {name}.  Let this deed serve as a warning to all who would threaten our home.\n\nYou have earned this reward to help you on your sojourn, young {class}." } })
apply(3377, { "classic", "forever" }, { deDE = { progress = "Erlaubt mir, meine Geschichte zu beenden.", completion = "Ich habe mich mit meinem Schicksal hier in diesem Käfig abgefunden, aber das Gebet muss gefunden werden." }, enUS = { progress = "Allow me to finish my story.", completion = "I have accepted my fate here in this cage, but the prayer must be found." } })
apply(3378, { "classic", "forever" }, { deDE = { progress = "Was führt Euch in den Tempel des Mondes, {name}?", completion = "Heute Abend lächelt Elune auf Euch herab, {name}. Ihr habt ihr eine verlorene Seele zurückgebracht. Bitte nehmt dies als ein Zeichen unserer Dankbarkeit." }, enUS = { progress = "What brings you to the Temple of the Moon, {name}?", completion = "Elune smiles upon you this eve, {name}. You have returned a lost soul to her. Please accept this as a token of our gratitude." } })
apply(3379, { "classic", "forever" }, { deDE = { progress = "Welche Informationen bringt Ihr?", completion = "Ausgezeichnete Arbeit, {name}.\n\nIch bin sicher, dass Ihr ein solches Stück Schattenzwirn bis jetzt noch nicht gesehen habt." }, enUS = { progress = "What information do you have?", completion = "Excellent work, {name}.\n\nI am sure that this is a piece of shadoweave that you have not yet seen." } })
apply(3380, { "classic", "forever" }, { deDE = { completion = "Ja, der Versunkene Tempel, ich darf behaupten, dass ich ihn mit meinen eigenen Augen gesehen habe. Vielleicht möchtet Ihr etwas mehr darüber erfahren?\n\nIhr scheint mir von der abenteuerlustigen Sorte zu sein - und ich weiß von Dingen, die Euch interessieren könnten ..." }, enUS = { completion = "Yes, the Sunken Temple, I can say that I have seen it with my own eyes. Perhaps you'd like to hear more about it?\n\nYou look like the adventurous type -- I know things that may intrigue you..." } })
apply(3382, { "classic", "forever" }, { deDE = { completion = "Ihr habt es geschafft! Danke! Das war mit Sicherheit eine der brutalsten Schlachten, an denen ich jemals teilgenommen habe. Ich kann Euch gar nicht genug danken.\n\nIch wünschte nur, ein größerer Teil meiner Mannschaft hätte diese Prüfung überlebt.\n\nIch möchte Euch bitten, mit den überlebenden Passagieren der HERRIN DES HORIZONTS zu sprechen. Einige von ihnen hatten hier geschäftlich zu tun und haben vielleicht ein oder zwei Aufträge für Euch, wenn Ihr wollt. Nochmals danke für all Eure Hilfe." }, enUS = { completion = "You've done it! Thank you! Surely this was one of the most brutal battles I've ever taken part in. I can't thank you enough.\n\nI only wish more of my crew could have lived through this trial.\n\nI would ask you to speak to any surviving passengers from the Horizon Scout. Some of them had business in the area, and may have a request or two of you if you're willing. Again, thank you for all your help." } })
apply(3385, { "classic", "forever" }, { deDE = { progress = "Der Handelsmeister lebt noch?", completion = "Ihr habt einen entscheidenden Schlag gegen den Untermarkt geführt. Seine Anführer werden es sich gut überlegen, bevor sie weitere Übeltäter in die Schlucht schicken.\n\nAch, ich habe auch nichts Nützliches im Händlerranzen finden können. Ihr könnt behalten, was immer Ihr im Innern findet." }, enUS = { progress = "The Trade Master still lives?", completion = "You have struck a decisive blow against the Undermarket. Their leaders will think twice before sending more cronies into the gorge.\n\nOh, and I also found nothing of use in the trader's satchel. You may keep whatever you find inside." } })
apply(3402, { "classic", "forever" }, { deDE = { completion = "Kovic ist tot??! Was für ein glorreicher Tag, {name}! Seit Jahren hat dieser Halunke undurchsichtige Untermarktgeschäfte getätigt und so ehrliche und hart arbeitende Händler in der ganzen Welt unterboten und betrogen.\n\nFür diese Leistung verdient Ihr eine feine Belohnung! Und Ihr werdet eine feine Belohnung erhalten!" }, enUS = { completion = "Kovic slain??! This is a glorious day, {name}! For years that scoundrel has been running shady undermarket trades, undercutting honest, hard working traders all over the world.\n\nYou deserve a fine reward for this accomplishment! And a fine reward you shall have!" } })
apply(3444, { "classic", "forever" }, { deDE = { progress = "Ratchet ist nicht weit von hier, {name}. Die Reise dürfte nicht lange dauern.", completion = "Ja... Das ist der Stein.\n\nIch erinnere mich jetzt an alles, {name}..." }, enUS = { progress = "Ratchet is not far from here, {name}. The journey shouldn't take long.", completion = "Yes... This is the stone.\n\nIt's all coming back to me now, {name}..." } })
apply(3445, { "classic", "forever" }, { deDE = { completion = "Ja, der Versunkene Tempel, ich darf behaupten, dass ich ihn mit meinen eigenen Augen gesehen habe. Vielleicht möchtet Ihr etwas mehr darüber erfahren?\n\nIhr scheint mir von der abenteuerlustigen Sorte zu sein - und ich weiß von Dingen, die Euch interessieren könnten ..." }, enUS = { completion = "Yes, the Sunken Temple, I can say that I have seen it with my own eyes. Perhaps you'd like to hear more about it?\n\nYou look like the adventurous type -- I know things that may intrigue you..." } })
apply(3446, { "classic", "forever" }, { deDE = { progress = "Während Ihr die Statue untersucht, bemerkt Ihr eine Vertiefung an ihrer Seite, die genau die Größe des Zeichens hat, das Marvon Euch mitgab...", completion = "Ihr legt den runden Stein in die Öffnung hinein und hört, wie er an seinem Platz einrastet.\n\nNun, da der Stein an seinem Platz ist, könnt Ihr weitermachen... aber was solltet Ihr als Nächstes tun?\n\nVielleicht solltet Ihr diesen Altar etwas näher untersuchen..." }, enUS = { progress = "Upon examining the statue, you notice a depression in its side, just the size of the token that Marvon gave you...", completion = "You push the stone circle into the opening, and you hear it lock into place.\n\nNow that the stone is in place, you may continue... but what should you do next?\n\nPerhaps you should examine this altar further..." } })
apply(3447, { "classic", "forever" }, { deDE = { completion = "Sogar in dem Halbdunkel des Tempels glitzert das Auge des Götzenbildes hell. Seine Transparenz enthüllt etwas Glänzendes, das dahinter versteckt ist. Ihr schiebt es zur Seite, fasst hinein und ergreift das, was im Inneren der Statue liegt.\n\nDer Schatz der Atal'ai gehört nun Euch." }, enUS = { completion = "The eye of the idol glitters brightly even in the half-darkness of the temple. Its transparency reveals something shiny behind it. Sliding it to the side, you reach in and grasp what lies inside the statue.\n\nThe Atal'ai treasure is now yours." } })
apply(3448, { "classic", "forever" }, { deDE = { completion = "Ah, Karnik hat Euch also geschickt? Ich habe darauf gewartet, bald von ihm zu hören. Ich habe solch wundersame Dinge über Azshara erfahren... Ich weiß zwar, dass Nachtelfen eine unglaubliche Lebensspanne haben, aber jeder vergisst doch einige der... unglücklicheren Geschehnisse in seinem Leben. Das ist jetzt nicht als Kritik zu verstehen, es ist nur eine Beobachtung.\n\nVor langer Zeit schufen die Elfen Städte, die erfüllt waren mit Wissen über Magie und andere verlorene Künste. Da ich nun solche Dinge selbst studiere, habe ich meine eigenen Nachforschungen angestellt. Was ich herausfand, war äußerst fesselnd." }, enUS = { completion = "Ah, Karnik sent you, did he? I expected to hear from him soon. I've discovered such wonderful things about Azshara.. I know night elves have incredible life spans, but everyone forgets some of the more... unfortunate events in their lives sometimes. That's not meant as a criticism, just an observation.\n\nLong ago, there were cities created by the elves filled with knowledge about magic and other lost arts. Being a student of such things, I started my investigation. What I found was quite thrilling." } })
apply(3449, { "classic", "forever" }, { deDE = { progress = "Ach nein, wie schön zu sehen, dass Ihr es hierher geschafft habt, {name}. Konntet Ihr die Abpausbilder für Tymor machen?\n\nAuch wenn es hier ganz schön gefährlich ist, entlang der Küste war nicht viel los. Das kann natürlich an den Naga liegen, die da unter Wasser herumschwimmen, aber das ist nicht mein Problem ... Ich patrouilliere den Himmel.", completion = "Schön, dass Ihr wohlauf und gesund seid, {name}. Ich hoffe, es war nicht zu anstrengend für Euch.\n\nIch werde das sofort zu Tymor bringen. Er wird so aufgeregt sein, endlich einen Blick darauf werfen zu können.\n\nLos, werft die Leuchtfeuerwaffe weg... wird Euch wahrscheinlich eh nicht mehr viel nützen, und ich hab auch schon eine neue." }, enUS = { progress = "Well, well, well, glad to see you made it out here, {name}. Did you get the rubbings for Tymor?\n\nAs dangerous as this place is, there hasn't been too much action along the coast. That might be on account of the naga swimming underwater, but that's not my problem... I patrol the skies.", completion = "Good to see you safe and sound, {name}. I hope things weren't too tough for you.\n\nI'll get these to Tymor right away. He'll be thrilled to take a look at these things.\n\nGo ahead and toss the flare gun... probably won't be any good to you anymore anyway, and I already got a new one." } })
apply(3450, { "classic", "forever" }, { deDE = { completion = "Was kann ich für Euch tun, {name}? Bin ein wenig beschäftigt im Moment, bereite mein Schiff für eine lange Reise vor. Kam gerade nur vorbei, um mit einigen Panzerpiloten zu sprechen - ich brauche einige Wendigomähnen um mein Cockpit auszupolstern, und meist haben sie welche übrig.\n\nIhr habt eine Minute, wenn Ihr Euch kurz fasst... einer der Jungs ist gerade zu Steelgrills Depot, um nachzusehen, ob die Piloten dort Mähnen für mich übrig haben." }, enUS = { completion = "What can I do for you, {name}? Kinda busy at the moment preparing my ship for a long trip. I just came over to see some of the tank pilots--I need some wendigo manes to line my cockpit and they usually have extra.\n\nI can give you a minute if you're brief... one of the boys just took off to Steelgrill's Depot to see if the pilots down there have extra manes for me." } })
apply(3451, { "classic", "forever" }, { deDE = { completion = "Hier ist meine Standardausrüstung-Leuchtfeuerwaffe, und habt nach dem Abfeuern der Waffe etwas Geduld - diese Sorte hat nur zwei Aufladungen und ich werde wahrscheinlich etwas Zeit brauchen, um bei Euch zu landen, je nachdem, wie weit draußen ich auf See bin." }, enUS = { completion = "Here's my standard issue flare gun, and be patient after you fire off the gun--there are only a couple charges in one of these, and it might take me a minute to get to you depending on how far out to sea I am. Just look out to sea after you fire off the flare." } })
apply(3454, { "classic", "forever" }, { deDE = { completion = "Ihr greift die Fackel mit beiden Händen, und Wellen von Hass und Wut pulsieren durch Euer ganzes Wesen." }, enUS = { completion = "You grab the torch with both hands; waves of hatred and anger pulse through your being." } })
apply(3462, { "classic", "forever" }, { deDE = { completion = "Seid Ihr bereit, Euren Schlag auszuführen?" }, enUS = { completion = "Are you prepared to make your strike?" } })
apply(3463, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Euch verlaufen, {name}?", completion = "Es ist glorreich! Ist es nicht glorreich, Meister?" }, enUS = { progress = "Are you lost, {name}?", completion = "It is glorious! Is it not glorious master?" } })
apply(3481, { "classic", "forever" }, { deDE = { completion = "Bei Eurer Berührung öffnet sich die Truhe. Wie viel Käse kann hier wohl drin sein? Es gibt nur einen Weg, das herauszufinden." }, enUS = { completion = "The chest opens at your touch. How much cheese could possibly be in here? There is only one way to find out." } })
apply(3501, { "classic", "forever" }, { deDE = { progress = "Hattet Ihr Glück bei Euren Forschungen?", completion = "Ihr widert mich an, {race}. Ein erwachsener Mann, sabbernd über einem Haufen Plunder? Jämmerlich! Nehmt Eure Belohnung und geht mir aus den Augen." }, enUS = { progress = "Have you had any luck in your exploration?", completion = "You truly disgust me, {race}. A grown man drooling over a pile of junk? Pitiful! Take your reward and get out of my sight." } })
apply(3502, { "classic", "forever" }, { deDE = { progress = "Also? Draenethyst? Erinnert Ihr Euch?\n\n<Kum'isha ballt seine Faust und klopft an Euren Kopf.>\n\nJemand zu Hause?", completion = "Ihr widert mich an, {race}. Ein erwachsener Mann, sabbernd über einem Haufen Plunder? Jämmerlich! Nehmt Eure Belohnung und geht mir aus den Augen.\n\nKommt Euch das bekannt vor? Das sollte es, denn ich sage das ungefähr tausend Mal am Tag.\n\nOh, wie ich diese Welt verabscheue." }, enUS = { progress = "Well? Draenethyst? Remember?\n\n<Kum'isha clenches his fist and knocks on your head.>\n\nIs anybody home?", completion = "You truly disgust me, {race}. A grown man drooling over a pile of junk? Pitiful! Take your reward and get out of my sight.\n\nSounds familiar? It should, because I say it a thousand times per day.\n\nOh how I loathe this world." } })
apply(3505, { "classic", "forever" }, { deDE = { progress = "Der Titel des Buches ist mit Goldbuchstaben in den schwarzen Ledereinband eingeprägt... Kaldorei-Foliant der Beschwörung. Während Ihr die Seiten aufschlagt, erkennt Ihr, dass das Buch zwar sehr alt, aber in einem sehr gut erhaltenen Zustand ist.\n\nIhr geht davon aus, dass der Text in einer uralten Sprache geschrieben wurde... vielleicht Kaldorei?\n\nEuer Instinkt sagt Euch, dass Ihr hierher zurückkehren solltet, sobald Ihr bei den Blutelfen Vergeltung für ihren Verrat geübt habt.", completion = "Ihr blättert einige Seiten durch, bis Ihr an eine Seite kommt, die mit einem dünnen, schwarzen Seidenstreifen markiert wurde.\n\nWährend Ihr versucht, das Manuskript zu entziffern, entdeckt Ihr ein Diagramm unten auf einer der Seiten. Ihr seht Euch kurz um und bemerkt, dass die Kristalle, der Kreis und auch andere Komponenten auf dem Boden ein Muster ergeben, dass dem des Diagramms im Buch sehr ähnlich ist." }, enUS = { progress = "The title of the book is emblazoned on the black leather cover in gold leaf--Kaldorei Tome of Summoning. As you open the pages you can see that the book is very old but in superb condition.\n\nYou assume the text is of some ancient language... perhaps Kaldorei?\n\nYour instincts tell you that you should return here once you've finished doling out retribution on the blood elves for their betrayal.", completion = "You begin to skim some of the pages until you come to a page that's marked by a thin, black strip of silk cloth.\n\nAs you try to decipher the script, you see a diagram on the bottom of one of the pages. A quick look around at the scene before you and you realize that the crystals, the circle, and even some of the other components on the ground are set up in a similar pattern as the diagram." } })
apply(3506, { "classic", "forever" }, { deDE = { progress = "Wie geht Euer Beseitigen der Blutelfen-Verräter voran, {name}? Konntet Ihr Fortschritte machen?\n\nIch hoffe, dass Ihr stark genug seid, diese Hündin in die Knie zu zwingen! Sie verdient für das, was sie getan hat, nur eines: einen schmerzhaften Tod!", completion = "RAR!! Unglaublich!\n\nIhr habt es geschafft! Das wird Belgrom erfreuen! Nun endlich können die Geister von Dutzenden unserer Krieger ihren Frieden finden. Danke, {name}." }, enUS = { progress = "How goes your slaughter of the blood elf traitors, {name}? Have you made any progress?\n\nI hope you are the one strong enough to bring that dog to her knees! She deserves nothing but a painful death for all that she has done!", completion = "RAR!! Incredible!\n\nYou've done it! Belgrom will be pleased! Finally the spirits of dozens of our warriors can be at peace. Thank you, {name}." } })
apply(3507, { "classic", "forever" }, { deDE = { progress = "Ich erinnere mich an Euch, {class}. Ich habe Euch gebeten, nach Azshara zu gehen und dieses Weib zu erledigen, das mich verraten hat! Das scheint so viele Monde her zu sein. Sagt mir nicht, dass Ag'tor und die anderen auch tot sind!", completion = "HAHA! Sieh dich an, lächerliches Weib! Ich spucke auf deine Überreste!\n\nDanke, {name}. Ich danke Euch aus tiefstem Herzen! Das ist wirklich ein großer Tag!\n\nWenn es in meiner Macht stünde, würde ich Euch ein Königreich geben! Aber ich hoffe, Ihr seid auch hiermit zufrieden.\n\n\n\nHa-ha! Blöde Blutelfin, schau dich nur mal an... in einem Sackleinenbeutel und ohne Körper! Du hättest Belgrom nicht verraten sollen!" }, enUS = { progress = "I remember you, {class}. I asked you to go to Azshara to destroy that wench that betrayed me! That seems like many moons ago. Don't tell me that Ag'tor and the others are dead also!", completion = "HAHA! Look at you now, pathetic woman! I spit on your remains!\n\nThank you, {name}. Thank you from the bottom of my heart! This is indeed a great day!\n\nI would give you a kingdom if it were in my power! But perhaps you will settle for this.\n\n\n\nHaha! Stupid blood elf, look at you now... in a burlap sack and missing your body! You should never have betrayed Belgrom!" } })
apply(3508, { "classic", "forever" }, { deDE = { completion = "Der Name der Bestie muss erst gefunden werden." }, enUS = { completion = "The name of the beast must be found." } })
apply(3509, { "classic", "forever" }, { deDE = { completion = "Ein Dämonenlord?\n\n<Lord Arkkoroc lacht.>\n\nVielleicht kann der Eine Euch mit der passenden Information helfen, doch vorher müsst Ihr dem Einen helfen." }, enUS = { completion = "A demon lord?\n\n<Lord Arkkoroc laughs.>\n\nPerhaps the one can assist you with this information; but first, you must assist the one." } })
apply(3510, { "classic", "forever" }, { deDE = { progress = "<Lord Arkkoroc beugt sich nach unten, um Euch zu betrachten.>\n\nWo sind sie?", completion = "Endlich jemand, der der Weisheit von Arkkoroc würdig ist!" }, enUS = { progress = "<Lord Arkkoroc bends down to inspect you.>\n\nWhere are they?", completion = "Finally, one worthy of the wisdom of Arkkoroc!" } })
apply(3511, { "classic", "forever" }, { deDE = { progress = "Ihr seid zurückgekehrt! Erstaunlich, {race}. Habt Ihr den wahren Namen erfahren?", completion = "Durch den Härter wird das notwendige Vitriol, das wir zum Schmieden der Waffen benötigen, hinzugefügt. Es fehlt nur noch ein Schritt bis zu ihrer Herstellung." }, enUS = { progress = "You return! Astounding, {race}. Did you discover the true name?", completion = "The temper will add the necessary vitriol we require for the forging of the weapons. There is but one more step in their creation." } })
apply(3512, { "classic", "forever" }, { deDE = { completion = "Itharius war sehr weise, Euch zu mir zu senden. Eranikus ist in Eurem Sinne nicht wirklich tot, er wird uns bald mit seinen eigenen Worten Ratschläge erteilen. Im Moment vermag ich Euch nicht direkt zu helfen... zumindest noch nicht.\n\nIch werde Euch meine Fertigkeit des Totensprechens gern zur Verfügung stellen, aber zunächst benötige ich die Hilfe von jemandem, der - im Gegensatz zu mir - nicht durch die Gebrechlichkeit des Alters eingeschränkt ist. Mein machtvollstes Vorzeichengerät wurde mir gegen meinen Willen genommen, und solange ich es nicht wieder zurückerhalten habe, werden wir Eranikus nicht helfen können." }, enUS = { completion = "Itharius was wise to send you to me.  While he is not dead as you understand death, Eranikus will soon give us advice in his own words.  For now though, I cannot directly help you... at least not yet.\n\nI will lend my skill at death-speaking to you, but first I need the help of one who - unlike me - is not limited by the frailties of old age.  My most potent augury device has been taken from me against my will, and unless I have it back we will be at a loss to help Eranikus." } })
apply(3513, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr da?", completion = "Ach... Wo habt Ihr das gefunden?" }, enUS = { progress = "Whaddya got?", completion = "Well now... Where did you find this?" } })
apply(3514, { "classic", "forever" }, { deDE = { completion = "Ihr seid ganz schön dreist! Rynthariel aus dem Bau zu beseitigen, ist ein großer Schritt, {name}. Sie werden sich nur langsam neu formieren und so können wir im Brachland künftig mit weniger Allianzläufern rechnen. Sie werden es sich gut überlegen, bevor sie noch mal einen hier entlangschicken.\n\nDanke." }, enUS = { completion = "You're a tough one! Ridding the Den of Rynthariel is a major step, {name}. They will be slow to regroup, and so we can count on less Alliance runners in the Barrens. They will think again before sending another this way.\n\nThank you." } })
apply(3517, { "classic", "forever" }, { deDE = { progress = "Die Schrifttafeln, die Ihr für mich sammeln sollt, dürften den richtigen Leuten ein hübsches Sümmchen einbringen. Ich werde Euch sagen, an wen sie geliefert werden sollen, sobald Ihr sie gefunden habt. Ich bin nicht dumm... Ihr werdet Euren Anteil erst bekommen, wenn ich den Beweis erhalten habe, dass sie geliefert worden sind.\n\nAlso macht Euch an die Arbeit... wir haben nicht den ganzen Tag Zeit. Sonst muss ich vielleicht einen anderen suchen, der mir behilflich ist.", completion = "Wunderbar, {name}, und auch noch in gutem Zustand. Dies sollte uns von den beteiligten Gruppen einen guten Preis einbringen.\n\nLasst uns hier nicht länger als nötig verweilen. Lasst uns Geld verdienen." }, enUS = { progress = "The tablets I'm having you gather should bring in a pretty copper or two to the right parties. I'll tell you who we need to deliver them to after you've found them. But I'm no fool... you'll get your share after I have proof that they've been delivered.\n\nSo get to it--we don't have all day. I might have to find someone else to help me.", completion = "Perfect, {name}, and in good condition also. These should get us a good price from all the parties concerned.\n\nLet's not dawdle around here any longer than we have to. We have some money to make." } })
apply(3518, { "classic", "forever" }, { deDE = { progress = "Ja, {name}. Was kann ich für Euch tun? Ich muss mich um viele Dinge kümmern, also fasst Euch bitte kurz.", completion = "Ah, endlich, die Schrifttafel von Beth'Amara. Ich fragte mich schon, ob meine Zusammenarbeit mit Jediga ein Fehler war oder ob die Arme in Azshara ihren Tod gefunden hat. Ich freue mich, dass sie erfolgreich war.\n\nBeth'Amara war einer der einflussreichsten Alchimisten der Hochgeborenen. Unter anderem wird gesagt, dass der Hexer in der Lage war, Metall zu transmutieren." }, enUS = { progress = "Yes, {name}. What can I do for you? I have many matters I must attend to, so please, be quick.", completion = "Ah, at long last, the Tablet of Beth'Amara. I was wondering if my partnership with Jediga had failed or if the poor orc had found her death in Azshara. I am glad she was successful.\n\nBeth'Amara was one of the Highborne's most influential alchemists. The wizard alone was said to have mastered transmuting metals among other things." } })
apply(3519, { "classic", "forever" }, { deDE = { completion = "Oh nein, ich habe mich schon gefragt, warum ich Iverron heute noch nicht gesehen habe. Dabei habe ich ihn immer vor diesen Spinnen gewarnt." }, enUS = { completion = "Oh dear; I was wondering why I hadn't seen Iverron yet today. And I've always warned him about those spiders..." } })
apply(3520, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Essenz der Kreischergeister gesammelt, {name}?", completion = "Ihr habt Eure Sache gut gemacht, {name}. Vielleicht ist es jetzt an der Zeit, mehr zu erzählen...\n\nEs gibt bei den Trollen eine alte Prophezeiung, laut der der tote Gott Hakkar der Seelenschinder eines Tages auf diese Erde zurückkehren wird. Einige sagen, die Ankunft von Hakkar würde Freude und Ruhm für alle Trolle bringen, andere glauben hingegen, dass seine Auferstehung das Ende aller Dinge bedeutet.\n\nIch glaube diese Geschichten nicht, aber ich weiß, dass die Essenz von Hakkar eine große Macht enthält, und diese Macht sollte von jenen fern gehalten werden, die sie missbrauchen würden..." }, enUS = { progress = "Have you collected the essence of the screecher spirits, {name}?", completion = "You have done well, {name}.  Perhaps now it is time to reveal more...\n\nThere is an ancient prophecy among the trolls, where the dead god Hakkar, the Soulflayer, will one day return to this earth.  Some say the coming of Hakkar will bring joy and glory to trollkind, while others believe his resurrection marks the end of all things.\n\nI do not believe this myth, but I do know the essence of Hakkar holds great power, and this power should be kept from those who would abuse it..." } })
apply(3521, { "classic", "forever" }, { deDE = { progress = "Bitte sammelt die Zutaten, {name}. Iverron braucht unsere Hilfe!", completion = "Elune sei Dank, dass Ihr diese Zutaten so schnell gesammelt habt.\n\nEs dauert nur einen Moment, bis ich das Gegengift zubereitet habe." }, enUS = { progress = "Please, collect the ingredients, {name}. Iverron needs our help.", completion = "Thank Elune that you have gathered these ingredients so quickly!\n\nIn just a moment, I will have the antidote prepared." } })
apply(3522, { "classic", "forever" }, { deDE = { progress = "Oh... {name}, ich bin so froh, dass Ihr wieder zurückgekommen seid.", completion = "Was ist das, {name}?\n\nOh, ich wusste, Dirania würde mir helfen können!\n\n\n\nIch gerate ständig in Schwierigkeiten und Dirania, na ja, sie schafft es immer wieder, mir da herauszuhelfen.\n\nIch fühle mich schon viel besser, aber ich denke, ich werde hier noch eine Weile sitzen bleiben, bis ich wieder ganz in Ordnung bin. Na ja, das ist der eine Grund, und ich hoffe außerdem, dass Ihr für mich einen Weg durch diese heimtückischen Waldweberspinnen frei macht..." }, enUS = { progress = "Oh... {name}, I'm so glad you have returned.", completion = "What is this, {name}?\n\nOh, I knew Dirania would be able to help me!\n\n\n\nI'm always getting into trouble and Dirania, well, she always manages to help me out of it.\n\nI am feeling much better, but I think I will sit here for a while longer, until I feel completely better. Well, that, and I was hoping you'd clear a path for me through those vicious Webwood spiders..." } })
apply(3523, { "classic", "forever" }, { deDE = { progress = "Ich schere mich nicht um Politik; mich interessiert nicht, ob Ihr Euch auf die Seite der Horde oder der Allianz schlagt. Ich bin eher daran interessiert, direkte und schreckliche Drohungen gegen alle Völker auszuschalten... und das hier ist eine ziemlich große.\n\nWenn Ihr willens seid, für alle Völker ein wahrer Held zu sein, dann übergebt mir den Schwurstein, den ich Euch gab, als Zeichen der Verpflichtung. Ich bin... nicht aus dieser Gegend, ein Schwurstein bedeutet für Leute wie mich ein Bund der Übereinkunft.", completion = "Phantastisch, ich dachte schon, dass Ihr heldenmutig ausseht! Ich will Euch nicht anlügen, {name}, wir haben eine Menge Arbeit vor uns. Wenn wir uns auf die vor uns liegende Aufgabe konzentrieren, sollten wir in der Lage sein, als Sieger aus der Sache hervorzugehen.\n\nJetzt will ich Euch auf den neuesten Stand der Dinge bringen ..." }, enUS = { progress = "I'm not one for politics; I care not if your affiliations are for either Horde or Alliance.  I am more interested in squelching direct and dire threats to all the races... and we have quite a large one in here.\n\nIf you're willing to be a true hero for all people, then hand me the oathstone I have given you as a sign of commitment.  I'm... not from around these parts; an oathstone is important to people of my kind as a bond of agreement.", completion = "Fantastic, I thought you looked to be the heroic type!  We've got our work cut out for us {name}, I'm not going to lie to you.  If we stay focused on the task at hand, we should be able to come out on top.\n\nNow, let me bring you up to speed on what's been going on..." } })
apply(3524, { "classic", "forever" }, { deDE = { progress = "Diese Kreaturen begannen erst vor kurzem, in solch alarmierender Zahl an den Ufern von Dunkelküste zu landen. Ich kann mir nicht helfen, aber ich glaube, dass dies irgendein schlechtes Omen ist. Wenn Ihr eine Probe der Knochen dieser Kreatur im Süden beschaffen könntet, würde uns das in Darnassus sehr bei der Einschätzung der Situation helfen!", completion = "Ich hoffe, die Murlocs haben Euch keine allzu großen Schwierigkeiten bereitet, als Ihr das für uns geholt habt! Ich werde das definitiv mit dem nächsten Hippogryph nach Darnassus schicken. Der Tempel des Mondes hat mir einige Geldmittel zur Verfügung gestellt, um damit Hilfe zu belohnen; bitte nehmt dies mit unserem Dank.\n\nAufgrund Eures Erfolges hier wage ich, Euch eine Gelegenheit zu bieten, dem Tempel des Mondes erneut zu helfen, falls Ihr interessiert seid ..." }, enUS = { progress = "It is only recently that these creatures started landing on the coast of Darkshore in such alarming numbers.  I can't help but think that this is an ill omen of some sort.  Recovering a sample of that creature's bones to the south would help us in Darnassus assess this situation!", completion = "I hope the murloc did not give you much trouble in collecting this for us!  I will be sure to get this on the next hippogryph to Darnassus.  The Temple of the Moon has given me some funds to hand out for assistance; please have some with our thanks.\n\nYour success here emboldens me to offer you a chance to aid the Temple of the Moon further, if you are interested..." } })
apply(3525, { "classic", "forever" }, { deDE = { completion = "Belnistrasz' plötzlicher Abgang hat eine brennende Kohlenpfanne hinterlassen. Während Ihr in die Flammen starrt, erfüllt das Bild eines roten Großdrachen mit riesigen Flügeln Euren Geist. Eine rauere Version von Belnistrasz' Stimme spricht direkt zu Euch.\n\n\"Wahrlich, sterbliche Wesen, Ihr seid die Helden, die ich mir erhofft hatte. Dank Euch gehören die Schlächtereien, die diese Bestien begangen haben, der Vergangenheit an. Mein Glaube an sterbliche Wesen wie Euch ist wieder einmal erneuert worden. Nehmt dies als Belohnung, die eines Helden würdig ist.\"" }, enUS = { completion = "Belnistrasz's sudden departure has left behind a burning brazier.  As you stare in to the flame, the image of a great-winged red dragon fills your mind.  A more graveled version of Belnistrasz's voice speaks directly to you.\n\n\"Indeed mortals, you are the heroes I had hoped you would be.  Thanks to you the butchery these beasts were perpetrating is a thing of the past.  My faith in mortals such as yourself has been once more renewed.  Take this as a reward befitting of a hero.\"" } })
apply(3526, { "classic", "forever" }, { deDE = { progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, {name}, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, {name}, und Ihr könnt vielleicht was lernen." }, enUS = { progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away.  Have you come seeking to learn about the mastery of the explosion?", completion = "Well {name}, you were wise to seek my tutelage!  Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that.  It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked {name}, and you might learn something." } })
apply(3527, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schrifttafeln der Prophezeiung von Mosh'aru, {name}?\n\nWenn ich die Schrifttafeln in meinen Besitz bringe, werde ich sie studieren und erfahren, wie die Essenz von Hakkar bewahrt werden kann!", completion = "Ah, das ist gut. Ich kann diese alten Schrifttafeln zusammenfügen und dann ihre verborgenen Geheimnisse studieren.\n\nMeine Schuld Euch gegenüber wächst, {name}. Und sie wird noch weiter wachsen!" }, enUS = { progress = "Do you have the tablets of the Prophecy of Mosh'aru, {name}?\n\nWhen I gain the tablets, I will study them, and learn how to contain the essence of Hakkar!", completion = "Ah, this is good.  I can fuse these ancient tablets together, and then study their hidden secrets.\n\nMy debt to you grows, {name}.  And it will grow further still." } })
apply(3528, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Avatar von Hakkar besiegt, {name}? Hat seine Essenz das Ei, das ich Euch gab, schon ermächtigt?", completion = "Die Essenz von Hakkar wurde eingefangen! Gerade jetzt beginnt sich das Leben im Ei zu regen! Sind die Geschichten von Hakkar doch wahr?\n\nDas darf nicht wahr sein! Ich fürchte mich vor dem, was Hakkar tun könnte, wenn er erneut geboren wird. Ich werde dieses Ei sicher aufbewahren und darauf achten, dass es niemals in böse Hände gerät.\n\nEure Dienste für mich sind nun zu Ende, {name}. Ihr habt eine Legende berührt und Eure Taten werden eines Tages das Antlitz unserer Erde verändern." }, enUS = { progress = "Have you defeated the avatar of Hakkar, {name}?  Has his essence yet empowered the egg I gave you?", completion = "The essence of Hakkar has been collected!  Even now the Egg stirs with life!  Could the myths of Hakkar be true?\n\nThat must not be true, for it is then I fear what Hakkar may do if birthed again.  I will keep this egg safe and be sure it does not fall into evil hands.\n\nYour labors with me are finished, {name}.  You have touched a legend, and your actions may one day change the face of our world." } })
apply(3541, { "classic", "forever" }, { deDE = { progress = "Ja? Was wollter denn, Mann? Hab heute noch viel zu tun, und Ihr seid in mei'm Terminkalender nich' eingetrag'n. Wenner mich weiter belästigt, kann sich das aber sicherlich noch ändern.", completion = "Ahhh, Jediga hat ihr Päckchen den weit'n Weg von Azshara hergeschickt. Gut. Hab da schon drauf gewartet.\n\nJediga, das is' mal 'ne feine Frau... 'ne tödliche dazu. Was könnt da besser sein?\n\nSeht Euch das an... die Schrifttafel is' in perfekt'm Zustand. Ihr seid 'n guter Bote, {name}." }, enUS = { progress = "Yes, what you be needin', mon? I got many tings to be takin' care of today, and you not be on me agenda as one of them. Pester me, and I make sure that changes.", completion = "Ahhh, Jediga be sendin' her package all the way from Azshara. Good. I be waitin' on this.\n\nJediga, now that be a fine woman... deadly too. What could be better?\n\nLook at this... the tablet be in perfect condition. You make a good messenger, {name}." } })
apply(3542, { "classic", "forever" }, { deDE = { progress = "Nun... <hick>... was für eine Überraschung? Ein Abenteurerererer... <hick>!\n\nWasss k'nn ich für Euch tun... <hick>?", completion = "Hier, nehmt ein paar Münzen... holt Euch'n... <hick>... neue Rüstung oder so was...\n\nDas gibt'n nettes Gold für die richt'gen... <hick> Leute." }, enUS = { progress = "Well... <hic>... isn't this a surprise? An adventurererere... <hic>!\n\nWhat c'n I do for you... <hic>?", completion = "Here, take some coin... get yerself... <hic>... some new armor or something....\n\nThis'll bring a shiny gold or two to the right... <hic> people." } })
apply(3561, { "classic", "forever" }, { deDE = { progress = "Wie kann ich Euch helfen, {name}?", completion = "Ah, die Schrifttafel von Sael'hai... wie lange habe ich darauf gewartet, sie zu erforschen.\n\nDanke, {name}. Ihr könnt Jediga mitteilen, dass sie ihre Sache gut gemacht hat. Das ist mit Sicherheit die Bezahlung wert, die sie gefordert hat." }, enUS = { progress = "What can I help you with, {name}?", completion = "Ah, the Tablet of Sael'hai... how long I've longed to study it.\n\nThank you, {name}. You may tell Jediga that she has done well. This will definitely be worth the payment she asked for." } })
apply(3562, { "classic", "forever" }, { deDE = { progress = "Na, was hat Magatha gesagt? Die alte Greisin... Ich wette, sie war nicht sehr höflich.", completion = "Ah, gut. Sie war ja vernünftiger, als ich es erwartet habe... zumindest zu Euch. Ich habe schon fast damit gerechnet, dass sie Euch für meine Ungebührlichkeit, jemand anderes an meiner Stelle zu schicken, bestrafen würde. Sie will diese Schrifttafel anscheinend wirklich dringend haben. Interessant.\n\nIch werde ein anderes Mal darüber nachdenken." }, enUS = { progress = "Well, what did Magatha say? The old crone... I bet she was less than polite.", completion = "Ah, good. She was much more reasonable than I expected... at least towards you. I half expected her to have you punished for my insolence in sending someone in my place. She must really want that tablet. Interesting.\n\nSomething to ponder another time." } })
apply(3563, { "classic", "forever" }, { deDE = { progress = "Habt Ihr schon mit Jes'rimon gesprochen?\n\nEr ist zwar ein Eber unter Trollen, aber seine Informationen sind eigentlich immer korrekt, und er bezahlt gut.\n\nWenn Ihr mit seinem Benehmen umgehen könnt, habt Ihr einiges an Geld von seinen geschäftlichen Bemühungen zu erwarten.", completion = "Wie ich an seiner Notiz erkennen kann, war er sehr erfreut... vielleicht ein wenig zu sehr.\n\nVielleicht werde ich mir eines Tages die Zeit nehmen, ihn wissen zu lassen, wie sehr ich seine Avancen schätze. Na, das ist immerhin ein Grund, sich auf eine längere Anwesenheit in Azshara zu freuen.\n\nHier habt Ihr Euren Anteil." }, enUS = { progress = "Have you spoken to Jes'rimon yet?\n\nHe's a boar among trolls, but his information is usually accurate and his jobs well paying.\n\nIf you can stand his attitude then you stand to make some good coin from his business endeavors.", completion = "I can see he was more than pleased by the looks of his note.... a little too pleased.\n\nPerhaps some day I'll take time to make sure he knows how much I appreciate his advances also. Well, at least there's one reason to look forward to spending more time in Azshara.\n\nHere's your share of our payment." } })
apply(3564, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Euch schon mit Andron getroffen? Er verlässt Undercity nur selten, Ihr müsstet ihn leicht finden können.", completion = "Perfekt... moment mal.\n\nHaha! Was habt Ihr ihm gesagt, als Ihr die Schrifttafel gebracht habt, {name}? Er hat uns viel zu viel bezahlt! Nicht, dass ich mich beschweren wollte. Habt Ihr ihm gesagt, dass der Preis sich geändert hat? Oder war er wieder mal betrunken?\n\nAuch egal... hier, Ihr sollt auch einen Extra-Anteil haben." }, enUS = { progress = "Have you met with Andron yet? He rarely leaves Undercity, so I don't think it'd be too hard to find him.", completion = "Perfect... wait a minute.\n\nHaha! What'd you tell him when you delivered the tablet, {name}? He overpaid us way too much! Not that I'm complaining. Did you tell him the deal changed? Or was he drunk again?\n\nDoesn't matter... here, take an extra share also." } })
apply(3565, { "classic", "forever" }, { deDE = { progress = "Nun, was hat Xylem gesagt? Er hat Euch doch nichts getan, oder? Hat er Euch verzaubert? Oder Euch dazu gebracht, für ihn zu arbeiten?", completion = "Keine Probleme? Überhaupt keine? Also das ist ja schon bemerkenswert... Ich habe erwartet, dass er einigen Widerstand zeigt oder zumindest unsere Übereinkunft verrät. Hmm, vielleicht kann man ihm ja doch trauen.\n\nGut, darüber muss ich jetzt nicht nachdenken. Hier ist Euer Anteil. Danke für Eure Hilfe." }, enUS = { progress = "Well, what did Xylem have to say? He didn't do anything to you, did he? Cast a spell on you? Con you into doing work for him?", completion = "No problems? None at all? Well, that's something to be said... I expected him to show some sort of reluctance or to at least betray our deal. Hmm, maybe he can be trusted after all.\n\nWell, no need to dwell on it that much. Here's your share. Thank you for your help." } })
apply(3566, { "classic", "forever" }, { deDE = { progress = "Ich glaube Euch nicht! Bringt mir Beweise!", completion = "<Thorius wird ganz blass.>\n\nDas... das darf nicht wahr sein. Mein eigener Bruder? Er hat all das inszeniert?\n\n<Thorius' Gesicht verzerrt sich vor Wut.>\n\nEr hat mich verraten, er hat Ironforge verraten! Es scheint, als sei der Einfluss der alten Götter in diesem Land immer noch sehr stark. Ich fürchte, wenn mein Bruder - ein einst so edler und ehrenwerter Mann - so leicht dem Willen von Ragnaros unterworfen werden konnte, ist hier niemand mehr sicher." }, enUS = { progress = "I don't believe you! Show me proof!", completion = "<Thorius' face turns white.>\n\nThis... this cannot be. My own brother? He set this all up?\n\n<Thorius' face contorts in anger.>\n\nHe betrayed me, he betrayed Ironforge! It seems as if the influence of the Old Gods is still strong in these lands. I fear that if my brother - a once noble and honorable man - was so easily turned to the will of Ragnaros, no one is safe." } })
apply(3568, { "classic", "forever" }, { deDE = { progress = "Ihr wisst, wohin das hier führt, nicht wahr, {name}? Sie wird dies nicht überleben... seht sie Euch an. Das Beste, was sie jetzt noch tun kann, ist, uns bei der Suche nach einem Heilmittel für die Seuche zu helfen. Das Wasser, das sie getrunken hat, könnte einen Hinweis enthalten, wie wir das anstellen können. Sie wird sowieso sterben; dann könnte sie doch, ehe sie stirbt, etwas Großmütiges für unser Volk tun. Ist es nicht so?", completion = "Großartig. Ihr seid zurück, bevor sie gestorben ist. Gut, gut.\n\nDann lasst uns mal anfangen, ja?\n\nIch habe ihre Symptome nun schon eine Weile beobachtet, und es ist sehr hässlich. Ich bin überrascht, dass sie noch steht. Sie musste sich schon drei oder vier Mal übergeben ... ein sehr angenehmer Geruch.\n\nBitte wartet einen Moment, bis ich etwas zusammengemischt habe, um es an unserer ... Freundin ... zu testen." }, enUS = { progress = "You know where this is leading, don't you, {name}? There's no way she can survive... look at her. The best thing for her now is to aid us in finding a cure for the plague. This water she drank might have a clue that helps us figure out how. She's going to die anyway--she might as well die doing something noble for our people before she does. Don't you agree?", completion = "Wonderful. You're back before she died. Good, good.\n\nLet's get started on this then, shall we?\n\nI've been studying her symptoms for some time now, and it's quite ugly. I'm surprised she's still standing. She's vomited three or four times all over the place... quite a pleasant odor.\n\nGive me just a moment to put something together to test on our... friend." } })
apply(3601, { "classic", "forever" }, { deDE = { progress = "Diese stinkenden Blutelfen. Ich sag Euch, wenn ich so stark wäre wie Ihr, würde ich mich dorthin begeben und ihnen selbst ein paar Dinge beibringen! Aber ich muss mich damit begnügen, Euch zu bezahlen, damit Ihr Euch um sie kümmert.", completion = "Haha! Denen habt Ihr's kräftig gezeigt, was?!\n\nDas ist toll! Das wird diese Blutelfen lehren, ihre Partner zu betrügen... besonders jemanden, der so loyal ist wie ein Goblin-Händler! Pah, Blutelfen...!\n\nTja, das Mindeste, was ich für Euch tun kann, ist, für Eure Zeit zu zahlen... so wie ich es gesagt habe.\n\nBitteschön... das hier sollte nützlich sein." }, enUS = { progress = "Those stinkin' Blood elves. I tell ya, if I was as strong as you are, I'd go down there and teach them a thing or two myself! But I'll have to settle with payin' you to take care of 'em for me.", completion = "Haha! You got them good, didn't you?!\n\nThis is great! That'll teach those Blood elves to betray their partners... especially someone as loyal as a goblin merchant! Bah, Blood elves...!\n\nWell, the least I can do for you is pay you for your time... just like I said I would.\n\nHere you go... those should be useful." } })
apply(3602, { "classic", "forever" }, { deDE = { progress = "Das Böse schläft nicht, Dummkopf. Ihr werdet genug Zeit zum Ausruhen haben, wenn Ihr erst einmal tot seid. Aber jetzt, bringt mir diese Kristalle.", completion = "Eure Aufgaben in Azshara sind abgeschlossen, sterbliches Wesen. Ich muss nun die notwendigen Komponenten für den nächsten Schritt Eures Abenteuers schmieden." }, enUS = { progress = "Evil does not sleep, fool. You will have time for rest when you are finally dead. Now, bring me those crystals.", completion = "Your tasks in Azshara are complete, mortal. I must now forge the necessary components for the next step in your adventure." } })
apply(3621, { "classic", "forever" }, { deDE = { progress = "Loramus, eh? Es ist schon viele Jahre her, dass ich diesen Namen hörte.", completion = "Meine Güte, allein der Gedanke, was Ihr wohl durchmachen musstet, um an dieses Material zu gelangen! Nur wenige wagen sich nach Azshara und kehren lebend zurück, ganz zu schweigen von denen, die sich mit Halbgöttern und Riesen messen!" }, enUS = { progress = "Loramus, eh? It has been many years since I have heard that name.", completion = "My goodness, I can only imagine what you went through to get these materials. Few venture into Azshara and return alive, let alone those that face demi-gods and giants!" } })
apply(3625, { "classic", "forever" }, { deDE = { progress = "Wenn der Schmiedevorgang unterbrochen wird, könnte die Waffe fehlerhaft sein. Habt Geduld, {name}.", completion = "<Galvan wischt sich den Schweiß von der Stirn.>\n\nEinen besseren Dämonentöter als diesen hier gab es noch nie, {name}." }, enUS = { progress = "To interrupt the forging process could result in an imperfect weapon. Be patient, {name}.", completion = "<Galvan wipes the sweat from his brow.>\n\nA finer demon slayer has never existed, {name}." } })
apply(3626, { "classic", "forever" }, { deDE = { completion = "Ihr seht aus wie ein erprobter Kämpfer, {name}. Seid Ihr bereit, Euch Razelikh und seinen Dienern zu stellen?" }, enUS = { completion = "You look battle hardened, {name}. Are you prepared to face Razelikh and his minions?" } })
apply(3628, { "classic", "forever" }, { deDE = { progress = "Es gibt nichts mehr zu fürchten.", completion = "Heute ist ein Tag, der bis in alle Ewigkeit unvergessen bleiben wird. Der dämonische Oberanführer der verwüsteten Lande ist endlich gefallen!" }, enUS = { progress = "There is nothing left to fear.", completion = "Today is a day that will be remembered for all eternity. The demonic overlord of the Blasted Lands has finally fallen!" } })
apply(3629, { "classic", "forever" }, { deDE = { progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, {name}, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, {name}, und Ihr könnt vielleicht was lernen." }, enUS = { progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away.  Have you come seeking to learn about the mastery of the explosion?", completion = "Well {name}, you were wise to seek my tutelage!  Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that.  It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked {name}, and you might learn something." } })
apply(3630, { "classic", "forever" }, { deDE = { progress = "Ja, ja, um welche Eurer Bedürfnisse darf ich mich heute bemühen? Ich habe ja offensichtlich Zeit dafür, da ich nur hier herumstehe, während unsere geliebte Stadt unter einer Wolke bestrahlten Todes liegt.", completion = "Ah, ein junger Ingenieur, der an der einen, wahren Disziplin der Ingenieurskunst interessiert ist! Entschuldigt meine Dramatik, Freund. Zwar ist unsere Lage immer noch sehr betrüblich, doch es ist immer ein guter Tag, wenn man einen weiteren Ingenieur findet, der dem Ruf der wahren Ingenieurskunst folgt!" }, enUS = { progress = "Yes, yes, what needs of yours might I address today?  Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.", completion = "Ah, a young engineer interested in pursuing the one, true discipline of engineering!  Well forgive my melodrama, friend.  While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!" } })
apply(3632, { "classic", "forever" }, { deDE = { progress = "Ja, ja, um welche Eurer Bedürfnisse darf ich mich heute bemühen? Ich habe ja offensichtlich Zeit dafür, da ich nur hier herumstehe, während unsere geliebte Stadt unter einer Wolke bestrahlten Todes liegt.", completion = "Ah, ein junger Ingenieur, der an der einen, wahren Disziplin der Ingenieurskunst interessiert ist! Entschuldigt meine Dramatik, Freund. Zwar ist unsere Lage immer noch sehr betrüblich, doch es ist immer ein guter Tag, wenn man einen weiteren Ingenieur findet, der dem Ruf der wahren Ingenieurskunst folgt!" }, enUS = { progress = "Yes, yes, what needs of yours might I address today?  Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.", completion = "Ah, a young engineer interested in pursuing the one, true discipline of engineering!  Well forgive my melodrama, friend.  While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!" } })
apply(3633, { "classic", "forever" }, { deDE = { progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, {name}, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, {name}, und Ihr könnt vielleicht was lernen." }, enUS = { progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away.  Have you come seeking to learn about the mastery of the explosion?", completion = "Well {name}, you were wise to seek my tutelage!  Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that.  It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked {name}, and you might learn something." } })
apply(3635, { "classic", "forever" }, { deDE = { progress = "Hallo! Wenn Ihr gekommen seid, um Euch über einen Leitroboter zu beschweren, der durch eine Wand Eures Domizils gebrochen ist, dann lasst mich Euch gleich zu meinem Anwalt weiterleiten. Anderenfalls, was kann ich heute für Euch tun?", completion = "Ihr seid gekommen, um die Gnomen-Ingenieurskunst zu erlernen, eh? Tja, da seid Ihr hier genau bei dem richtigen Gnom gelandet. Auch wenn die herrschende Fraktion in Gnomeregan die Politik benutzt, um diejenigen, die sie als intellektuelle Bedrohung sieht, zu ächten, wissen sie doch genau, dass Wissen ihrer Kontrolle nicht unterworfen werden kann.\n\nSie und ich wissen, dass sie einen ihrer größten noch lebenden Gnomen-Ingenieure verloren haben, als ich Gnomeregan verlassen habe. Wenn Ihr ein fähiger Student seid, werde ich Euch alles lehren, was ich weiß." }, enUS = { progress = "Hello there!  If you've come about a homing robot that may have smashed through a wall of your domicile, then I will refer you to my barrister in advance.  Otherwise, what can I do for you today?", completion = "You've come to learn about gnome engineering, eh?  Well, you've come to the right gnome.  While the ruling faction of Gnomeregan may use politics to ostracize those they view as an intellectual threat, they know that knowledge is something they cannot control.\n\nThey and I both know that when I left Gnomeregan, they lost one of their greatest gnome engineers alive today.  If you're a capable student, I'll teach you what I know." } })
apply(3636, { "classic", "forever" }, { deDE = { completion = "Danke, {name}. Die Geißel wird es sich nun zweimal überlegen, bevor sie erneut versucht, ihre Reihen zu verstärken.\n\nMöge das Licht Euch segnen." }, enUS = { completion = "Thank you , {name}. The Scourge will now think twice before attempting to bolster its ranks again.\n\nMay you be blessed by the Light." } })
apply(3637, { "classic", "forever" }, { deDE = { progress = "Hallo! Wenn Ihr gekommen seid, um Euch über einen Leitroboter zu beschweren, der durch eine Wand Eures Domizils gebrochen ist, dann lasst mich Euch gleich zu meinem Anwalt weiterleiten. Anderenfalls, was kann ich heute für Euch tun?", completion = "Ihr seid gekommen, um die Gnomen-Ingenieurskunst zu erlernen, eh? Tja, da seid Ihr hier genau bei dem richtigen Gnom gelandet. Auch wenn die herrschende Fraktion in Gnomeregan die Politik benutzt, um diejenigen, die sie als intellektuelle Bedrohung sieht, zu ächten, wissen sie doch genau, dass Wissen ihrer Kontrolle nicht unterworfen werden kann.\n\nSie und ich wissen, dass sie einen ihrer größten noch lebenden Gnomen-Ingenieure verloren haben, als ich Gnomeregan verlassen habe. Wenn Ihr ein fähiger Student seid, werde ich Euch alles lehren, was ich weiß." }, enUS = { progress = "Hello there!  If you've come about a homing robot that may have smashed through a wall of your domicile, then I will refer you to my barrister in advance.  Otherwise, what can I do for you today?", completion = "You've come to learn about gnome engineering, eh?  Well, you've come to the right gnome.  While the ruling faction of Gnomeregan may use politics to ostracize those they view as an intellectual threat, they know that knowledge is something they cannot control.\n\nThey and I both know that when I left Gnomeregan, they lost one of their greatest gnome engineers alive today.  If you're a capable student, I'll teach you what I know." } })
apply(3638, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr das Dokument unterzeichnet habt und bereit seid, es mir zu übergeben, dann war's das. Ihr wisst, dass diese Reise nur in eine Richtung geht. Wenn Ihr bereit seid, dann kommt an Bord!", completion = "Willkommen an Bord, Goblin-Ingenieur {name}! Ihr werdet bald Zugang zu den mächtigsten Ingenieurskunst-Schemata in ganz Azeroth haben.\n\nNun, da Ihr Euch dem Erwerb dieses Wissens verschrieben habt, ist es Zeit, Eure Goblin-orientierten Ingenieursarbeiten zu begutachten. Von dort ausgehend, werden wir Euch helfen, einen Plan zu erstellen, Eure Goblin-Ingenieurstalente voll auszuschöpfen!" }, enUS = { progress = "If you've signed the document and are ready to hand it to me, then that is that.  You've been told that this is a one way trip.  If you're ready, then hop on board!", completion = "Welcome aboard, Goblin Engineer {name}!  You soon will have access to the most powerful engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your goblin-oriented engineering work.  From there, we'll help you build a plan to maximize your goblin engineering talents!" } })
apply(3639, { "classic", "forever" }, { deDE = { progress = "Sobald ich die von Euch gefertigten Ingenieurskunst-Gegenstände zur Ansicht erhalten habe, werde ich Euch eine echte Goblin-Ingenieur-Mitgliedskarte aushändigen. Solange die Karte gültig ist, habt Ihr unbegrenzten Zugang zu jedem Goblin-Ingenieurskunstlehrer auf der ganzen Welt.", completion = "Hier ist Eure erste Goblin-Ingenieur-Mitgliedskarte!\n\nDiese Karte wurde für vierzehn Tage im Voraus bezahlt; alle Karten laufen nach zwei Wochen Aktivität ab. Ist das geschehen, zahlt Ihr Euren nächsten Beitrag bei einem beliebigen Goblin-Ingenieurskunstlehrer ein, um eine weitere Karte zu erhalten. Ohne die Karte wird Eure Mitgliedschaft zeitweilig unterbrochen und Ihr habt keinen Zugriff auf neue Baupläne.\n\nDas hat natürlich keinen Einfluss auf das, was Ihr bereits wisst. Einmal Goblin-Ingenieur, immer Goblin-Ingenieur." }, enUS = { progress = "Once I receive your crafted engineering items for my review, I will hand you a genuine Goblin Engineer Membership Card!  So long as the card is valid, you will have unlimited access to any goblin engineer trainer anywhere in the world.", completion = "Here is your first Goblin Engineer Membership Card!\n\nThis card has its dues paid for in advance for fourteen days; all cards expire after two weeks of activity.  When it does, pay your next set of dues to any goblin engineer trainer in order to get another card; without the card, your membership will temporarily lapse and you cannot access new schemata.\n\nThis never affects what you already know; once a goblin engineer, always a goblin engineer." } })
apply(3640, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr das Dokument unterzeichnet habt und bereit seid, es mir zu übergeben, dann war's das.\n\nDie Geheimnisse, die ich mit Euch teilen werde, sind von solcher Bedeutung, dass der Schwur der Geheimhaltung ein absolutes Muss ist. Ich habe ein solches Dokument unterschrieben, genau wie alle Gnomeningenieure. Ihr werdet einer viel versprechenden Zunft beitreten, Ingenieur {name}!", completion = "Willkommen an Bord, {name}! Ihr werdet bald Zugang zu den am höchsten entwickelten Ingenieurskunst-Schemata in ganz Azeroth haben.\n\nNun, da Ihr Euch dem Erwerb dieses Wissens verschrieben habt, ist es Zeit, Eure Gnomen-orientierten Ingenieursarbeiten zu begutachten. Von dort ausgehend, werden wir Euch helfen, einen Plan zu erstellen, Eure Gnomen-Ingenieurstalente voll auszuschöpfen!" }, enUS = { progress = "If you've signed the document and are ready to hand it to me, then that is that.\n\nThe secrets I will share with you are of such a magnitude that the signing of the Pledge of Secrecy is absolutely critical.  I signed one, as did my brother and sister gnome engineers.  You will be joining quite the auspicious fold, Engineer {name}!", completion = "Welcome aboard, {name}!  You soon will have access to the most advanced engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your gnome-oriented engineering work.  From there, we'll help you build a plan to maximize your gnome engineering talents!" } })
apply(3641, { "classic", "forever" }, { deDE = { progress = "Sobald ich Eure gefertigten Ingenieurskunst-Gegenstände zur Ansicht erhalten habe, werde ich Euch eine echte Gnomen-Ingenieur-Mitgliedskarte aushändigen. Solange die Karte gültig ist habt Ihr unbegrenzten Zugang zu jedem Gnomen-Ingenieurskunstlehrer auf der ganzen Welt.", completion = "Hier ist Eure erste Gnomen-Ingenieur-Mitgliedskarte!\n\nDiese Karte wurde für vierzehn Tage im Voraus bezahlt; alle Karten laufen nach zwei Wochen Aktivität ab. Ist das geschehen, zahlt Ihr Euren nächsten Beitrag bei einem beliebigen Gnomen-Ingenieurskunstlehrer ein, um eine weitere Karte zu erhalten. Ohne die Karte wird Eure Mitgliedschaft zeitweilig unterbrochen und Ihr habt keinen Zugriff auf neue Baupläne.\n\nDas hat natürlich keinen Einfluss auf das, was Ihr bereits wisst. Einmal Gnomen-Ingenieur, immer Gnomen-Ingenieur." }, enUS = { progress = "Once I receive your crafted engineering items for my review, I will hand you a genuine Gnome Engineer Membership Card!  So long as the card is valid, you will have unlimited access to any gnome engineer trainer anywhere in the world.", completion = "Here is your first Gnome Engineer Membership Card!\n\nThis card has its dues paid for in advance for fourteen days; all cards expire after two weeks of activity.  When it does, pay your next set of dues to any gnome engineer trainer in order to get another card; without the card, your membership will temporarily lapse and you cannot access new schemata.\n\nThis never affects what you already know; once a gnome engineer, always a gnome engineer." } })
apply(3642, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr das Dokument unterzeichnet habt und bereit seid, es mir zu übergeben, dann war's das.\n\nObwohl meine politische Überzeugung sich extrem von der in Gnomeregan vorherrschenden unterscheidet - besonders von der dieses Dummkopfes, Tüftlermeister Overspark -, geht doch der Schwur der Geheimhaltung über alles! Ihr müsst Euch einem einzigen Weg verschreiben und diesem Weg Euer ganzes Leben lang treu ergeben bleiben.", completion = "Willkommen an Bord, {name}! Ihr werdet bald Zugang zu den am höchsten entwickelten Ingenieurskunst-Schemata in ganz Azeroth haben.\n\nNun, da Ihr Euch dem Erwerb dieses Wissens verschrieben habt, ist es Zeit, Eure Gnomen-orientierten Ingenieursarbeiten zu begutachten. Von dort ausgehend, werden wir Euch helfen, einen Plan zu erstellen, Eure Gnomen-Ingenieurstalente voll auszuschöpfen!" }, enUS = { progress = "If you've signed the document and are ready to hand it to me, then that is that.\n\nWhile I may vehemently disagree with Gnomeregan - especially that fool Tinkmaster Overspark - politically, the Pledge of Secrecy transcends everything else!  You must agree to commit a single path and stay true to that path throughout your life.", completion = "Welcome aboard, {name}!  You soon will have access to the most advanced engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your gnome-oriented engineering work.  From there, we'll help you build a plan to maximize your gnome engineering talents!" } })
apply(3643, { "classic", "forever" }, { deDE = { progress = "Sobald ich Eure gefertigten Ingenieurskunst-Gegenstände zur Ansicht erhalten habe, werde ich Euch eine echte Gnomen-Ingenieur-Mitgliedskarte aushändigen. Solange die Karte gültig ist habt Ihr unbegrenzten Zugang zu jedem Gnomen-Ingenieurskunstlehrer auf der ganzen Welt.", completion = "Hier ist Eure erste Gnomen-Ingenieur-Mitgliedskarte!\n\nDiese Karte wurde für vierzehn Tage im Voraus bezahlt; alle Karten laufen nach zwei Wochen Aktivität ab. Ist das geschehen, zahlt Ihr Euren nächsten Beitrag bei einem beliebigen Gnomen-Ingenieurskunstlehrer ein, um eine weitere Karte zu erhalten. Ohne die Karte wird Eure Mitgliedschaft zeitweilig unterbrochen und Ihr habt keinen Zugriff auf neue Baupläne.\n\nDas hat natürlich keinen Einfluss auf das, was Ihr bereits wisst. Einmal Gnomen-Ingenieur, immer Gnomen-Ingenieur." }, enUS = { progress = "Once I receive your crafted engineering items for my review, I will hand you a genuine Gnome Engineer Membership Card!  So long as the card is valid, you will have unlimited access to any gnome engineer trainer anywhere in the world.", completion = "Here is your first Gnome Engineer Membership Card!\n\nThis card has its dues paid for in advance for fourteen days; all cards expire after two weeks of activity.  When it does, pay your next set of dues to any gnome engineer trainer in order to get another card; without the card, your membership will temporarily lapse and you cannot access new schemata.\n\nThis never affects what you already know; once a gnome engineer, always a gnome engineer." } })
apply(3661, { "classic", "forever" }, { deDE = { progress = "Versucht, ihnen möglichst aus dem Weg zu gehen, {name}. Die Wildekin könnten Euer Interesse missverstehen und denken, Ihr habt vor, sie zu verletzen...", completion = "Danke, dass Ihr sie mir gebracht habt, {name}.\n\nWas habt Ihr über die Wildekin erfahren können?\n\nVielleicht werden uns diese Federn mehr sagen. Wilde Monster oder einfach fehlgeleitete Tiere? Eines Tage möchte ich die Wahrheit kennen...\n\nIch werde meine Forschungen fortsetzen - kommt zu mir zurück und sprecht erneut mit mir, nachdem einige Zeit vergangen ist." }, enUS = { progress = "Try to avoid them if you can, {name}. The Wildkin may misread your interest as an intent to do them harm...", completion = "Thank you for bringing these to me, {name}.\n\nWhat did you learn of the Wildkin?\n\nPerhaps these feathers will tell us more. Ferocious monsters, or simply misguided pets? One day I'd like to know the truth...\n\nI am going to continue my research -- please come back and talk to me again after some time has passed." } })
apply(3681, { "classic", "forever" }, { deDE = { completion = "Willkommen in der Kathedrale des Lichts, {class}." }, enUS = { completion = "Welcome to the Cathedral of Light, {class}." } })
apply(3701, { "classic", "forever" }, { deDE = { progress = "Bringt Ihr neue Informationen?", completion = "Oh je! Diese Informationen erklären einiges in Bezug auf Thaurissan.\n\nEs gibt ja noch so viel mehr zu erfahren!" }, enUS = { progress = "Do you bring new information?", completion = "Oh my! This information explains quite a lot about Thaurissan.\n\nThere is much more to learn!" } })
apply(3702, { "classic", "forever" }, { deDE = { progress = "Erlaubt mir, Euch die Geschichte von Thaurissan zu Ende zu erzählen.", completion = "Sollen wir fortfahren?" }, enUS = { progress = "Allow me to finish telling you the story of Thaurissan.", completion = "Shall we proceed?" } })
apply(3741, { "classic", "forever" }, { deDE = { progress = "Hallo! Ich vermisse meine Halskette. Mein Papa hat sie mir geschenkt. Papa sagt, dass es Monster im See gibt. Habt Ihr irgendwelche Monster verhauen?", completion = "Vielen Dank, dass Ihr meine Halskette gefunden habt, lieber {class}... Ihr seid sehr gütig! Auch mein Kätzchen dankt Euch... nicht wahr, Effsee?" }, enUS = { progress = "Hi.  I miss my necklace.  My daddy got it for me.  Daddy says that there are monsters in the lake.  Did you beat up any monsters?", completion = "Thank you for finding my necklace mister {class}... you are very kind!  My kitty thanks you too - isn't that right Effsee?" } })
apply(3761, { "classic", "forever" }, { deDE = { progress = "Rühren, Gefreiter. Wenn Ihr hier seid, um Erde aus Un'Goro abzuladen - hervorragend! Anderenfalls verschwindet.", completion = "Oh, macht's Euch ruhig bequem, Gefreiter {name}. Bemüht Euch bloß nicht, mir zu helfen, diese Erde auf die Haufen da zu schaufeln! Wenn die großen Geister gewollt hätten, dass sie da hinkommt, hätten sie die dort bestimmt hinaufgezaubert, nicht wahr?!\n\nErzdruide Runetotem möchte erneut mit Euch sprechen, aber Ihr werdet feststellen, dass für seine nächste Aufgabe das Wissen eines Gesellen der Kräuterkunde hilfreich wäre. Falls Ihr nicht über dieses Wissen verfügt, wird er trotzdem Verwendung für Euch finden." }, enUS = { progress = "At ease, Private.  If you're here to unload soil from Un'Goro - outstanding then!  Otherwise, disappear.", completion = "Oh that's right Private {name}, don't make any effort to help me unload this soil up on to the piles!  If the Great Spirits had wanted it done they would have miracled it up there, now wouldn't they?!\n\nArch Druid Runetotem wants to speak with you again, but for his next task you find that a journeyman's understanding of Herbalism would be helpful.  If you don't know it though, he'll still find a use for you." } })
apply(3762, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {class}; ich freue mich, dass Ihr daran interessiert seid, an unseren Forschungen teilzunehmen. Es gibt viel zu tun und ich würde Euch einen schlechten Dienst erweisen, wenn ich Euch sagen würde, dass die Arbeit, die dies mit sich bringt, ungefährlich sei. Hoffentlich erschreckt Euch das nicht ... aber so, wie Ihr ausseht, würde ich sagen, dass Ihr schon früher der Gefahr ins Auge geblickt habt." }, enUS = { completion = "Greetings, {class}; I am glad you are interested in assisting our research.  There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous.  Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before." } })
